window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s23-85","number":85,"surah":23,"verses":[100],"verseLabel":"المؤمنون: 100","question":"ما سرّ تسمية طلب الرجوع ﴿كَلِمَةٌ هُوَ قَائِلُهَا﴾؟","answer":"سماها ﴿كلمة﴾ تحقيرًا لجدواها؛ فهي قول لا يتبعه عمل بعد انقضاء زمن التكليف، والرد بـ﴿كلا﴾ يقطع إمكان الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص240–259.","url":""}]},{"id":"s23-86","number":86,"surah":23,"verses":[101],"verseLabel":"المؤمنون: 101","question":"لماذا لا أنساب بينهم يومئذ ولا يتساءلون؟","answer":"لا تنفع الروابط في دفع الحكم، ويشغل الهول كل إنسان عن السؤال والمفاخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص260–266.","url":""}]},{"id":"s23-87","number":87,"surah":23,"verses":[102,103],"verseLabel":"المؤمنون: 102-103","question":"لماذا علق الفلاح بثقل الموازين والخسران بخفتها؟","answer":"ما يزن هو الإيمان والعمل الحق؛ ومن أضاعه أضاع نفسه لا مالًا خارجًا عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص267–280.","url":""}]},{"id":"s23-88","number":88,"surah":23,"verses":[104],"verseLabel":"المؤمنون: 104","question":"ما سرّ التعبير بـ﴿تَلْفَحُ وُجُوهَهُمُ النَّارُ﴾؟","answer":"اللفح إصابة الحرارة المباشرة، وخص الوجوه لأنها موضع الكرامة والتعبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص267–280.","url":""}]},{"id":"s23-89","number":89,"surah":23,"verses":[105],"verseLabel":"المؤمنون: 105","question":"لماذا جاء التوبيخ بصيغة السؤال ﴿أَلَمْ تَكُنْ آيَاتِي تُتْلَى عَلَيْكُمْ﴾؟","answer":"ليجعلهم يقرون بأن الحجة كانت متجددة على أسماعهم وهم يكذبون.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص281–286.","url":""}]},{"id":"s23-90","number":90,"surah":23,"verses":[108],"verseLabel":"المؤمنون: 108","question":"ما سرّ التعبير بقوله تعالى: لهم ﴿اخْسَئُوا فِيهَا وَلَا تُكَلِّمُونِ﴾؟","answer":"﴿اخسؤوا﴾ أمر بالطرد والإبعاد مع الذل، و﴿ولا تكلمون﴾ قطع لطلبهم بعد قيام الحجة؛ فبلغ التوبيخ غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص299–302.","url":""}]},{"id":"s23-91","number":91,"surah":23,"verses":[109],"verseLabel":"المؤمنون: 109","question":"لماذا ذُكر دعاء المؤمنين الذي كانوا يسخرون منه؟","answer":"الكلمات نفسها التي ضحكوا من أصحابها صارت حجة لنجاتهم وسببًا لإدانة الساخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص303–310.","url":""}]},{"id":"s23-92","number":92,"surah":23,"verses":[111],"verseLabel":"المؤمنون: 111","question":"ما سرّ التعبير بـ﴿إِنِّي جَزَيْتُهُمُ الْيَوْمَ بِمَا صَبَرُوا﴾؟","answer":"الصبر الذي بدا ضعفًا في الدنيا ظهر يوم الجزاء سبب الفوز الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص311–321.","url":""}]},{"id":"s23-93","number":93,"surah":23,"verses":[112,113,114],"verseLabel":"المؤمنون: 112-114","question":"لماذا سألهم عن عدد سنين لبثهم؟","answer":"ليقروا بقصر الدنيا وضياع حسابها؛ حتى العدد الذي عاشوه يتضاءل في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص322–334.","url":""}]},{"id":"s23-94","number":94,"surah":23,"verses":[115],"verseLabel":"المؤمنون: 115","question":"ما سرّ التعبير بـ﴿أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَاكُمْ عَبَثًا﴾؟","answer":"الاستفهام يهدم أصل الغفلة: الخلق بلا رجوع يجعل الأمر لعبًا، وقد تنزه الله عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص335–341.","url":""}]},{"id":"s23-95","number":95,"surah":23,"verses":[116],"verseLabel":"المؤمنون: 116","question":"لماذا عقب بـ﴿فَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ﴾؟","answer":"تعاليه وملكه وحقه تستلزم أن يكون الخلق بحكمة وحساب لا عبثًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص342–348.","url":""}]},{"id":"s23-96","number":96,"surah":23,"verses":[117],"verseLabel":"المؤمنون: 117","question":"ما سرّ وصف دعاء إله آخر بـ﴿لَا بُرْهَانَ لَهُ بِهِ﴾؟","answer":"جملة ﴿لا برهان له به﴾ كاشفة لحقيقة دعاء غير الله؛ فكل معبود سواه لا يقوم عليه دليل، ثم جعل حساب صاحبه عند ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص349–357.","url":""}]},{"id":"s23-97","number":97,"surah":23,"verses":[118],"verseLabel":"المؤمنون: 118","question":"لماذا ختمت السورة بـ﴿رَبِّ اغْفِرْ وَارْحَمْ وَأَنْتَ خَيْرُ الرَّاحِمِينَ﴾؟","answer":"بعد مشاهد الحساب جمع طلب إزالة الذنب بالمغفرة ونيل الفضل بالرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص358–362.","url":""}]},{"id":"s24-1","number":1,"surah":24,"verses":[1],"verseLabel":"النور: 1","question":"لماذا افتتحت السورة بكلمة ﴿سُورَةٌ﴾ نكرة؟","answer":"افتتحت بالنكرة ﴿سورة﴾ للتفخيم والتنويه بشأنها، ثم وصفت بالإنزال والفرض لتتهيأ النفس لما تضمنته من أحكام وحدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص375–386.","url":""}]},{"id":"s24-2","number":2,"surah":24,"verses":[1],"verseLabel":"النور: 1","question":"ما سرّ التعبير بـ﴿أَنْزَلْنَاهَا وَفَرَضْنَاهَا﴾ مع أن الإنزال يشمل أحكامها؟","answer":"الإنزال يثبت مصدرها الإلهي، و﴿فرضناها﴾ يصرح بإيجاب أحكامها وتقديرها؛ فالجمع ينبه إلى أن ما فيها وحي ملزم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص375–386.","url":""}]},{"id":"s24-3","number":3,"surah":24,"verses":[1],"verseLabel":"النور: 1","question":"ما سرّ وصف الآيات في المطلع بـ﴿آيَاتٍ بَيِّنَاتٍ﴾، وفي الآية 46 بـ﴿آيَاتٍ مُبَيِّنَاتٍ﴾؟","answer":"﴿بينات﴾ تصف الآيات بالوضوح في نفسها، و﴿مبينات﴾ تبرز فعلها في البيان والكشف؛ فناسب الأول افتتاح السورة، والثاني مقام الاستدلال والهداية في الآية 46.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص375–386؛ وج37، ص116–121.","url":""}]},{"id":"s24-4","number":4,"surah":24,"verses":[2],"verseLabel":"النور: 2","question":"ما سرّ تقديم ﴿الزَّانِيَةُ﴾ على ﴿الزَّانِي﴾؟","answer":"ذُكرت في تقديم الزانية وجوه، منها ظهور أثر الفاحشة فيها واتصال أحكام السورة بصيانة الأعراض، وقيل لأن داعي المرأة أو أثرها في هذه الجريمة أبرز؛ فلا يجزم بعلة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص387–403.","url":""}]},{"id":"s24-5","number":5,"surah":24,"verses":[2],"verseLabel":"النور: 2","question":"ما سرّ التعبير بـ﴿الزَّانِيَةُ وَالزَّانِي﴾ بصيغة اسم الفاعل؟","answer":"اسم الفاعل يلحظ ثبوت الوصف ممن تحقق منه الفعل وثبت شرعًا، لا مجرد وقوع تهمة أو خاطر؛ ولذلك رتب الحكم على الوصف المنضبط.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص387–403.","url":""}]},{"id":"s24-6","number":6,"surah":24,"verses":[2],"verseLabel":"النور: 2","question":"ما سرّ اختيار ﴿فَاجْلِدُوا﴾ بدل «فاضربوا»؟","answer":"الجلد ضرب مخصوص يقع على الجلد بضابط الحد، بخلاف الضرب المطلق الذي لا يحدد موضعه ولا صفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص387–403.","url":""}]},{"id":"s24-7","number":7,"surah":24,"verses":[2],"verseLabel":"النور: 2","question":"ما سرّ اختيار ﴿رَأْفَةٌ﴾ بدل «رحمة» في إقامة الحد؟","answer":"الرأفة شدة الرقة التي قد تحمل على ترك العقوبة، فنهي عن الرأفة المفضية إلى تعطيل حد الله، لا عن أصل الرحمة المحمودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص387–403.","url":""}]},{"id":"s24-8","number":8,"surah":24,"verses":[2],"verseLabel":"النور: 2","question":"لماذا علق إقامة الحد بقوله ﴿إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ﴾؟","answer":"علق النهي على الإيمان بالله واليوم الآخر تغليظًا للأمر؛ لأن إقامة حكم الله من مقتضى الانقياد له واستحضار الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص387–403.","url":""}]},{"id":"s24-9","number":9,"surah":24,"verses":[2],"verseLabel":"النور: 2","question":"لماذا أمر أن يشهد العذاب ﴿طَائِفَةٌ مِنَ الْمُؤْمِنِينَ﴾؟","answer":"شهود طائفة يحقق علانية الحد والاعتبار به، ولفظ الطائفة يحتمل أعدادًا ذكرت فيها أقوال؛ فلا يثبت عدد مخصوص من اللفظ وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص387–403.","url":""}]},{"id":"s24-10","number":10,"surah":24,"verses":[3],"verseLabel":"النور: 3","question":"لماذا جاء أسلوب ﴿الزَّانِي لَا يَنْكِحُ إِلَّا زَانِيَةً﴾ بهذه المقابلة؟","answer":"جاء التركيب في صورة خبر يفيد التناسب بين أهل الفجور وينفر المؤمن من هذه الرابطة، وفي حكم النكاح وتفسير الآية أقوال فقهية لا تختزل في معنى أخلاقي واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص404–412.","url":""}]},{"id":"s24-11","number":11,"surah":24,"verses":[4],"verseLabel":"النور: 4","question":"لماذا اشترط في القذف ﴿أَرْبَعَةِ شُهَدَاءَ﴾؟","answer":"اشتراط أربعة شهداء تشديد في حماية الأعراض وسد لباب القذف، فلا تثبت الفاحشة بمجرد الشيوع أو الظن.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص413–430.","url":""}]},{"id":"s24-12","number":12,"surah":24,"verses":[4],"verseLabel":"النور: 4","question":"لماذا جمع بين الجلد ورد الشهادة والحكم بالفسق؟","answer":"جمع للقاذف حد البدن، ورد الشهادة، والحكم بالفسق؛ لأن جنايته اعتداء على العرض والثقة الدينية والاجتماعية معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص413–430.","url":""}]},{"id":"s24-13","number":13,"surah":24,"verses":[5],"verseLabel":"النور: 5","question":"لماذا استثنى ﴿إِلَّا الَّذِينَ تَابُوا﴾ ثم ختم بـ﴿غَفُورٌ رَحِيمٌ﴾؟","answer":"الاستثناء فتح باب التوبة والإصلاح بعد القذف، وختم بالغفور الرحيم تقريرًا لقبول من تاب وأصلح؛ وفي عود قبول الشهادة خلاف فقهي لا يحسمه الجواب البلاغي وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص413–430.","url":""}]},{"id":"s24-14","number":14,"surah":24,"verses":[6],"verseLabel":"النور: 6","question":"لماذا خُص الزوج الذي لا شهود له بنظام اللعان؟","answer":"لأن اطلاعه على ما يخفى أقرب، ولأن إلزامه بالشهود أو حد القذف يوقع حرجًا لا يدفعه إلا تحليف الطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص431–444.","url":""}]},{"id":"s24-15","number":15,"surah":24,"verses":[6,7,8,9],"verseLabel":"النور: 6-9","question":"لماذا تكررت الشهادة أربع مرات ثم كانت الخامسة لعنة أو غضبًا؟","answer":"كررت الشهادة أربعًا لتقوم مقام الشهود الأربعة، ثم جعلت الخامسة دعاءً باللعنة أو الغضب تغليظًا واستحضارًا لعقوبة الله عند الكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص431–444.","url":""}]},{"id":"s24-16","number":16,"surah":24,"verses":[9],"verseLabel":"النور: 9","question":"ما سرّ مجيء الخامسة في حق المرأة بـ﴿غَضَبَ اللَّهِ عَلَيْهَا﴾، وفي حق الرجل بـ﴿لَعْنَتُ اللَّهِ عَلَيْهِ﴾؟","answer":"خُص الرجل باللعنة لأنها الطرد من الرحمة عند كذبه، وخُصت المرأة بالغضب لأن كذبها ـ على قول المفسرين ـ يقترن بدفع التهمة بعد تكرر الشهادة؛ وذكرت في الفرق وجوه فلا يجزم بعلة منفردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص445–453.","url":""}]},{"id":"s24-17","number":17,"surah":24,"verses":[10],"verseLabel":"النور: 10","question":"لماذا جاء جواب ﴿وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ﴾ محذوفًا؟","answer":"حذف جواب ﴿لولا﴾ للتهويل وتوسيع ما يقدره السامع من العنت والعقوبة، ودل السياق على أن فضل الله ورحمته دفعا ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص454–462.","url":""}]},{"id":"s24-18","number":18,"surah":24,"verses":[11],"verseLabel":"النور: 11","question":"ما سرّ تسمية أهل الإفك ﴿عُصْبَةٌ مِنْكُمْ﴾؟","answer":"العصبة جماعة متعاونة متعاضدة، و﴿منكم﴾ تبين أنهم من داخل المجتمع المسلم؛ فكان خطر الخبر ناشئًا من تداوله جماعيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص463–482.","url":""}]},{"id":"s24-19","number":19,"surah":24,"verses":[11],"verseLabel":"النور: 11","question":"ما سرّ التعبير بـ﴿لَا تَحْسَبُوهُ شَرًّا لَكُمْ بَلْ هُوَ خَيْرٌ لَكُمْ﴾؟","answer":"لأن المحنة انتهت ببراءة منزلة وتشريعات تحمي الأعراض وكشف المنافقين ورفع درجات الصابرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص463–482.","url":""}]},{"id":"s24-20","number":20,"surah":24,"verses":[11],"verseLabel":"النور: 11","question":"ما سرّ اختيار ﴿اكْتَسَبَ﴾ بدل «كسب» في وصف نصيب أهل الإفك؟","answer":"صيغة الافتعال في ﴿اكتسب﴾ تلائم تعمد تحصيل الإثم وتكلفه، بخلاف أصل الكسب الذي قد يستعمل في الأعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص463–482.","url":""}]},{"id":"s24-21","number":21,"surah":24,"verses":[12],"verseLabel":"النور: 12","question":"ما سرّ التعبير بـ﴿بِأَنْفُسِهِمْ خَيْرًا﴾ بدل «بإخوانهم»؟","answer":"سمى إخوانهم أنفسهم لاتحاد أهل الإيمان وتكافلهم؛ فسوء الظن بالمؤمن رجوع على الجماعة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص483–489.","url":""}]},{"id":"s24-22","number":22,"surah":24,"verses":[12],"verseLabel":"النور: 12","question":"لماذا كان الواجب أن يقولوا فورًا ﴿هَذَا إِفْكٌ مُبِينٌ﴾؟","answer":"لأن القرائن المعلومة من طهارة المتهمين تجعل الكذب ظاهرًا قبل البحث في التفاصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص483–489.","url":""}]},{"id":"s24-23","number":23,"surah":24,"verses":[13],"verseLabel":"النور: 13","question":"لماذا أعيد طلب الشهداء الأربعة بعد تقرير حد القذف؟","answer":"لنقل السامع من مجرد الحكم العام إلى محاكمة خبر الإفك نفسه وإسقاطه لافتقاره إلى البينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص490–497.","url":""}]},{"id":"s24-24","number":24,"surah":24,"verses":[14],"verseLabel":"النور: 14","question":"لماذا تكرر ﴿وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ﴾؟","answer":"تكرر الامتنان لأن كل مقام من مقامات قصة الإفك استدعى تذكيرًا مستقلًا بفضل الله ورحمته: عند التلقي، وعند بيان الأحكام والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص498–504، و535–538.","url":""}]},{"id":"s24-25","number":25,"surah":24,"verses":[15],"verseLabel":"النور: 15","question":"ما سرّ التعبير بـ﴿تَلَقَّوْنَهُ بِأَلْسِنَتِكُمْ﴾ مع أن التلقي يكون عادةً بالسمع؟","answer":"أسند التلقي إلى الألسنة تصويرًا لسرعة انتقال الخبر من فم إلى فم من غير تثبت بالقلب أو استناد إلى علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص505–512.","url":""}]},{"id":"s24-26","number":26,"surah":24,"verses":[15],"verseLabel":"النور: 15","question":"ما سرّ التعبير بـ﴿وَتَحْسَبُونَهُ هَيِّنًا وَهُوَ عِنْدَ اللَّهِ عَظِيمٌ﴾؟","answer":"ليصحح ميزان الخطورة: سهولة ترديد الكلمة لا تعني صغر أثرها ولا ذنبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص505–512.","url":""}]},{"id":"s24-27","number":27,"surah":24,"verses":[16],"verseLabel":"النور: 16","question":"لماذا كان الأنسب أن يقولوا ﴿سُبْحَانَكَ هَذَا بُهْتَانٌ عَظِيمٌ﴾؟","answer":"جاء التسبيح تعجبًا وتنزيهًا لله عما لا يليق، ثم سمي الخبر بهتانًا عظيمًا؛ ولا يلزم حصر دلالته في مساس حكمة اختيار بيت النبوة وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص513–519.","url":""}]},{"id":"s24-28","number":28,"surah":24,"verses":[17],"verseLabel":"النور: 17","question":"ما سرّ التعبير بـ﴿يَعِظُكُمُ اللَّهُ أَنْ تَعُودُوا لِمِثْلِهِ أَبَدًا﴾؟","answer":"لم ينه عن اللفظ وحده، بل عن كل طريق يماثله في نشر التهمة بلا علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص520–526.","url":""}]},{"id":"s24-29","number":29,"surah":24,"verses":[19],"verseLabel":"النور: 19","question":"ما سرّ التعبير بـ﴿يُحِبُّونَ أَنْ تَشِيعَ الْفَاحِشَةُ﴾ ولم يشترط وقوعها؟","answer":"مجرد محبة انتشار السوء فساد قلبي يهيئ له ويستطيب أثره، ولو لم يباشر الفاحشة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص527–534.","url":""}]},{"id":"s24-30","number":30,"surah":24,"verses":[21],"verseLabel":"النور: 21","question":"ما سرّ التعبير بـ﴿لَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ﴾ بالجمع؟","answer":"لأن الانحراف غالبًا يبدأ مراحل صغيرة متتابعة؛ فمنع الطريق قبل نهايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص539–558.","url":""}]},{"id":"s24-31","number":31,"surah":24,"verses":[21],"verseLabel":"النور: 21","question":"ما سرّ التعبير بـ﴿مَا زَكَى مِنْكُمْ مِنْ أَحَدٍ أَبَدًا﴾؟","answer":"«من» و«أحد» و«أبدًا» تبالغ في نفي استقلال الإنسان بتطهير نفسه؛ الفضل لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص539–558.","url":""}]},{"id":"s24-32","number":32,"surah":24,"verses":[22],"verseLabel":"النور: 22","question":"ما سرّ التعبير بـ﴿وَلْيَعْفُوا وَلْيَصْفَحُوا﴾ فجمع بينهما؟","answer":"العفو ترك المؤاخذة، والصفح إزالة أثرها من المعاملة؛ فطلب كمال التجاوز.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص559–577.","url":""}]},{"id":"s24-33","number":33,"surah":24,"verses":[22],"verseLabel":"النور: 22","question":"لماذا عقب العفو بسؤال ﴿أَلَا تُحِبُّونَ أَنْ يَغْفِرَ اللَّهُ لَكُمْ﴾؟","answer":"حوّل النفس من ألم الإساءة إلى حاجتها هي للمغفرة؛ فمن أحب عفو الله عفا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص559–577.","url":""}]},{"id":"s24-34","number":34,"surah":24,"verses":[23],"verseLabel":"النور: 23","question":"ما سرّ وصف المقذوفات بـ﴿الْمُحْصَنَاتِ الْغَافِلَاتِ الْمُؤْمِنَاتِ﴾؟","answer":"تراكم الصفات يبين فظاعة الاعتداء: عفة ظاهرة، وبراءة قلب، وحرمة إيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص578–587.","url":""}]},{"id":"s24-35","number":35,"surah":24,"verses":[24],"verseLabel":"النور: 24","question":"لماذا تشهد الألسنة والأيدي والأرجل عليهم؟","answer":"تتحول أدوات القول والعمل نفسها إلى شهود، فلا يملك الإنسان إنكار ما باشرته جوارحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص588–594.","url":""}]},{"id":"s24-36","number":36,"surah":24,"verses":[25],"verseLabel":"النور: 25","question":"ما سرّ تسمية الجزاء ﴿دِينَهُمُ الْحَقَّ﴾؟","answer":"الدين هنا الجزاء المستوفى؛ يرد عليهم عملهم كاملًا في يوم تظهر فيه الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص595–604.","url":""}]},{"id":"s24-37","number":37,"surah":24,"verses":[26],"verseLabel":"النور: 26","question":"ما معنى مقابلة ﴿الْخَبِيثَاتُ لِلْخَبِيثِينَ﴾ و﴿الطَّيِّبَاتُ لِلطَّيِّبِينَ﴾ في سياق الإفك؟","answer":"في ﴿الخبيثات﴾ و﴿الطيبات﴾ أقوال: الكلمات لأهلها، أو النساء والرجال؛ وسياق الإفك يقرر براءة الطيبين مما يقول الخبيثون، فلا يحصر اللفظ في تفسير واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص605–618.","url":""}]},{"id":"s24-38","number":38,"surah":24,"verses":[27],"verseLabel":"النور: 27","question":"ما سرّ التعبير بـ﴿لَا تَدْخُلُوا بُيُوتًا غَيْرَ بُيُوتِكُمْ﴾ قبل الاستئذان؟","answer":"بدأ بحرمة المجال الخاص، ثم بين مفتاح الدخول المشروع: الاستئناس والسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص619–633.","url":""}]},{"id":"s24-39","number":39,"surah":24,"verses":[27],"verseLabel":"النور: 27","question":"ما سرّ اختيار ﴿تَسْتَأْنِسُوا﴾ بدل «تستأذنوا» في القراءة المشهورة؟","answer":"الاستئناس طلب الأنس واستكشاف رضا أهل البيت، وهو يتضمن الاستئذان ويزيد عليه إزالة الوحشة؛ وهذه هي القراءة المتواترة الثابتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص619–633.","url":""}]},{"id":"s24-40","number":40,"surah":24,"verses":[28],"verseLabel":"النور: 28","question":"ما سرّ التعبير عند عدم الإذن بـ﴿فَارْجِعُوا هُوَ أَزْكَى لَكُمْ﴾؟","answer":"الرجوع يحفظ قلب الزائر من الإلحاح وبيت المزور من الحرج؛ فكان أطهر للطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص634–648.","url":""}]},{"id":"s24-41","number":41,"surah":24,"verses":[29],"verseLabel":"النور: 29","question":"لماذا استثنى ﴿بُيُوتًا غَيْرَ مَسْكُونَةٍ فِيهَا مَتَاعٌ لَكُمْ﴾؟","answer":"لأن علة الاستئذان صيانة خصوصية السكان، فإذا انتفت وبقيت منفعة عامة خف الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص649–657.","url":""}]},{"id":"s24-42","number":42,"surah":24,"verses":[30],"verseLabel":"النور: 30","question":"ما سرّ مجيء ﴿مِنْ أَبْصَارِهِمْ﴾ بـ«من»، ومجيء ﴿وَيَحْفَظُوا فُرُوجَهُمْ﴾ بلا «من»؟","answer":"جاءت ﴿من﴾ في الأبصار للتبعيض؛ إذ ليس كل نظر محرمًا، ولم تدخل على الفروج لأن المطلوب أصل الحفظ التام إلا ما استثناه الشرع.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص658–670.","url":""}]},{"id":"s24-43","number":43,"surah":24,"verses":[30],"verseLabel":"النور: 30","question":"لماذا ختم أمر غض البصر بـ﴿إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ﴾؟","answer":"اختير «يصنعون» لما فيه من التعمد والترتيب؛ والله يعلم النظرة الخفية وما وراءها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص658–670.","url":""}]},{"id":"s24-44","number":44,"surah":24,"verses":[31],"verseLabel":"النور: 31","question":"لماذا أعاد للنساء أمر غض البصر ولم يكتف بأمر الرجال؟","answer":"لأن التكليف فردي، ولكل جنس دواعيه وأحكامه، فلا يغني خطاب أحدهما عن الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص671–699.","url":""}]},{"id":"s24-45","number":45,"surah":24,"verses":[31],"verseLabel":"النور: 31","question":"ما سرّ التعبير بـ﴿إِلَّا مَا ظَهَرَ مِنْهَا﴾ بدل «ما أظهرن»؟","answer":"أسند الظهور إلى الزينة نفسها ليدل على ما ظهر بغير تعمد أو جرت الحاجة والعادة بظهوره، وفي تحديد المستثنى أقوال فقهية لا يحصرها البيان اللغوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص671–699.","url":""}]},{"id":"s24-46","number":46,"surah":24,"verses":[31],"verseLabel":"النور: 31","question":"ما سرّ التعبير بـ﴿وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ﴾؟","answer":"لأن الخمار كان موجودًا، فوجه النص طريقة استعماله ليستر موضع الصدر والنحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص671–699.","url":""}]},{"id":"s24-47","number":47,"surah":24,"verses":[31],"verseLabel":"النور: 31","question":"لماذا جاء ﴿الطِّفْلِ﴾ مفردًا مع أن المراد جنس الأطفال؟","answer":"المفرد المعرف يستغرق الجنس، ويصور وصف الطفولة المشترك قبل إدراك العورات.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص671–699.","url":""}]},{"id":"s24-48","number":48,"surah":24,"verses":[31],"verseLabel":"النور: 31","question":"لماذا نهى عن ضرب الأرجل ليُعلم ما يخفين من الزينة؟","answer":"سد الطريق إلى الفتنة ولو كانت الزينة مستورة؛ فالمسموع قد يستدعي النظر والتخيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص671–699.","url":""}]},{"id":"s24-49","number":49,"surah":24,"verses":[32],"verseLabel":"النور: 32","question":"ما سرّ التعبير بـ﴿وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ﴾ فجعل الخطاب للجماعة؟","answer":"لأن تيسير الزواج مسؤولية اجتماعية لا شأنًا فرديًا محضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص700–709.","url":""}]},{"id":"s24-50","number":50,"surah":24,"verses":[32],"verseLabel":"النور: 32","question":"ما سرّ التعبير بـ﴿إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ﴾؟","answer":"أبطل جعل الفقر مانعًا مطلقًا؛ فالزواج سبب عفة وعمل، والرزق بيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص700–709.","url":""}]},{"id":"s24-51","number":51,"surah":24,"verses":[33],"verseLabel":"النور: 33","question":"ما سرّ التعبير في المكاتبة بـ﴿إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا﴾ بـ«إن»؟","answer":"لأن تحقق القدرة والأمانة ليس مفروضًا في كل مملوك، فعلق الحكم على ثبوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص710–731.","url":""}]},{"id":"s24-52","number":52,"surah":24,"verses":[33],"verseLabel":"النور: 33","question":"ما سرّ اختيار ﴿الْبِغَاءِ﴾ بدل «الزنا» في إكراه الإماء؟","answer":"البغاء يفيد اتخاذ الفاحشة حرفة وطلب الكسب بها، وهو عين صورة الإكراه المذكورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص710–731.","url":""}]},{"id":"s24-53","number":53,"surah":24,"verses":[33],"verseLabel":"النور: 33","question":"ما سرّ التعبير بـ﴿فَإِنَّ اللَّهَ مِنْ بَعْدِ إِكْرَاهِهِنَّ غَفُورٌ رَحِيمٌ﴾؟","answer":"المغفرة والرحمة راجعتان إلى المكرهات على البغاء عند جمهور المفسرين، وحذف متعلق الخبر لدلالة السياق؛ فلا تجعل الآية إكراههن ذنبًا عليهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص710–731.","url":""}]},{"id":"s24-54","number":54,"surah":24,"verses":[35],"verseLabel":"النور: 35","question":"ما سرّ التعبير بـ﴿اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ﴾ بدل «ضياؤهما»؟","answer":"النور هنا فسر بالهادي والمنور ومدبر أنوار السماوات والأرض، وليس المراد ضوءًا حسيًا يحويه المكان؛ والآية من باب التمثيل لهداية الله ونوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص740–765.","url":""}]},{"id":"s24-55","number":55,"surah":24,"verses":[35],"verseLabel":"النور: 35","question":"لماذا شُبّه نوره بمشكاة فيها مصباح؟","answer":"المشكاة كوة تجمع ضوء المصباح، وتتابع المصباح والزجاجة والزيت يضاعف صفاء الصورة؛ وهو مثل لنور الله في قلب المؤمن أو لهدايته، مع تعدد عبارات المفسرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص740–765.","url":""}]},{"id":"s24-56","number":56,"surah":24,"verses":[35],"verseLabel":"النور: 35","question":"ما سرّ التعبير بـ﴿الْمِصْبَاحُ فِي زُجَاجَةٍ الزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّيٌّ﴾ فأعاد الاسمين؟","answer":"الإظهار بعد الإضمار المحتمل يفصل طبقات الصورة ويجعل كل عنصر منها منظورًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص740–765.","url":""}]},{"id":"s24-57","number":57,"surah":24,"verses":[35],"verseLabel":"النور: 35","question":"ما سرّ وصف الشجرة بأنها ﴿لَا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ﴾؟","answer":"ذُكرت في ﴿لا شرقية ولا غربية﴾ أقوال، أشهرها توسط الشجرة وتعرضها للشمس طول النهار؛ والمقصود كمال صفاء زيتها لا تحديد جهة جغرافية جازمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص740–765.","url":""}]},{"id":"s24-58","number":58,"surah":24,"verses":[35],"verseLabel":"النور: 35","question":"ما سر ﴿نُورٌ عَلَى نُورٍ﴾؟","answer":"﴿نور على نور﴾ تراكم لأسباب الإضاءة في المثل، وفسر بتضافر نور الفطرة والوحي أو الإيمان والقرآن؛ فلا يقتصر على تركيب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص740–765.","url":""}]},{"id":"s24-59","number":59,"surah":24,"verses":[36,37],"verseLabel":"النور: 36-37","question":"لماذا انتقل من مثل النور إلى ﴿فِي بُيُوتٍ أَذِنَ اللَّهُ أَنْ تُرْفَعَ﴾؟","answer":"بيّن مواضع إشعاع ذلك النور في الواقع: بيوت العبادة التي تعمر بالذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص766–773.","url":""}]},{"id":"s24-60","number":60,"surah":24,"verses":[37],"verseLabel":"النور: 37","question":"ما سرّ الجمع بين ﴿تِجَارَةٌ﴾ و﴿بَيْعٌ﴾ مع دخول البيع في التجارة؟","answer":"ذكر التجارة للنشاط العام، والبيع للحظة إبرام الصفقة التي يشتد عندها التعلق بالربح.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص774–793.","url":""}]},{"id":"s24-61","number":61,"surah":24,"verses":[37],"verseLabel":"النور: 37","question":"ما سرّ التعبير بـ﴿وَإِقَامِ الصَّلَاةِ﴾ بالمصدر لا «يقيمون الصلاة»؟","answer":"عطف المصدر على الذكر وجعله شأنًا ثابتًا ملازمًا، لا فعلًا عارضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص774–793.","url":""}]},{"id":"s24-62","number":62,"surah":24,"verses":[39],"verseLabel":"النور: 39","question":"لماذا شُبهت أعمال الكافرين بالسراب؟","answer":"لأنها تبدو نافعة من بعيد، ثم تنهار عند شدة الحاجة إليها كما يخيب الظمآن عند بلوغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص10–29.","url":""}]},{"id":"s24-63","number":63,"surah":24,"verses":[39],"verseLabel":"النور: 39","question":"لماذا خص ﴿الظَّمْآنُ﴾ بأنه يحسب السراب ماء؟","answer":"شدة حاجته تقوي الوهم وتضاعف صدمة الخيبة؛ فالمثل يصور رجاء الكافر عند الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص10–29.","url":""}]},{"id":"s24-64","number":64,"surah":24,"verses":[39],"verseLabel":"النور: 39","question":"ما سرّ التعبير بـ﴿وَوَجَدَ اللَّهَ عِنْدَهُ﴾؟","answer":"معنى ﴿وجد الله عنده﴾ أنه وجد جزاء الله أو حكمه عند عمله، وقيل لقي الله؛ فحلت حقيقة الحساب محل الماء الذي توهمه الظمآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص10–29.","url":""}]},{"id":"s24-65","number":65,"surah":24,"verses":[40],"verseLabel":"النور: 40","question":"لماذا جاء المثل الثاني بـ﴿ظُلُمَاتٍ﴾ جمعًا؟","answer":"لأن أسباب الضلال متراكبة: بحر عميق وموج فوق موج وسحاب؛ فناسبها جمع الظلمات.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص30–53.","url":""}]},{"id":"s24-66","number":66,"surah":24,"verses":[40],"verseLabel":"النور: 40","question":"ما سرّ التعبير بـ﴿فِي بَحْرٍ لُجِّيٍّ﴾؟","answer":"اللجي العميق الكثير الماء؛ يجمع بعد القعر واضطراب السطح ليبلغ انعدام الرؤية غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص30–53.","url":""}]},{"id":"s24-67","number":67,"surah":24,"verses":[40],"verseLabel":"النور: 40","question":"ما سرّ التعبير بـ﴿إِذَا أَخْرَجَ يَدَهُ لَمْ يَكَدْ يَرَاهَا﴾؟","answer":"نفى قرب رؤية اليد في شدة الظلمات؛ و﴿لم يكد يراها﴾ من أساليب نفي مقاربة الرؤية، فاختيرت اليد لأنها أقرب الأشياء إلى صاحبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص30–53.","url":""}]},{"id":"s24-68","number":68,"surah":24,"verses":[41],"verseLabel":"النور: 41","question":"ما سرّ التعبير عن الطير بـ﴿كُلٌّ قَدْ عَلِمَ صَلَاتَهُ وَتَسْبِيحَهُ﴾؟","answer":"لكل مخلوق وجه عبادة ألهمه الله إياه، وإن خفيت كيفيته على الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص54–70.","url":""}]},{"id":"s24-69","number":69,"surah":24,"verses":[43],"verseLabel":"النور: 43","question":"ما سرّ التعبير بـ﴿يُزْجِي سَحَابًا ثُمَّ يُؤَلِّفُ بَيْنَهُ ثُمَّ يَجْعَلُهُ رُكَامًا﴾؟","answer":"رتب مراحل تكوّن السحاب من سوق القطع إلى ضمها ثم تراكمها، فـ«ثم» تناسب تدرج المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص76–97.","url":""}]},{"id":"s24-70","number":70,"surah":24,"verses":[43],"verseLabel":"النور: 43","question":"لماذا ذكر البرد دون الثلج؟","answer":"ذكر البرد لأنه المقصود في مقام الإصابة والصرف، أما الثلج فليس موضوع السياق؛ ولا يثبت من النص وحده تعليل ذلك ببيئة المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص76–97.","url":""}]},{"id":"s24-71","number":71,"surah":24,"verses":[43],"verseLabel":"النور: 43","question":"ما سرّ التعبير بـ﴿مِنْ جِبَالٍ فِيهَا مِنْ بَرَدٍ﴾؟","answer":"في ﴿من جبال فيها من برد﴾ وجوه: جبال من سحاب، أو كتل عظيمة شبيهة بالجبال، و﴿من﴾ تتنوع دلالتها؛ فلا يجزم بأن الجبال حقيقة جامدة في السماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص76–97.","url":""}]},{"id":"s24-72","number":72,"surah":24,"verses":[44],"verseLabel":"النور: 44","question":"لماذا ختم تقليب الليل والنهار بـ﴿لَعِبْرَةً لِأُولِي الْأَبْصَارِ﴾؟","answer":"التحول يُرى بالعين، لكن العبرة لا تحصل إلا ببصيرة تعبر من الظاهرة إلى مدبرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص98–115.","url":""}]},{"id":"s24-73","number":73,"surah":24,"verses":[45],"verseLabel":"النور: 45","question":"ما سرّ تنكير ﴿مِنْ مَاءٍ﴾ هنا، وتعريف الماء في قوله بالأنبياء ﴿مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ﴾؟","answer":"عُرف الماء في الأنبياء لأنه في مقام تقرير الجنس المعروف أصلًا للحياة، ونكر هنا لأن المقام في تنويع الدواب المخلوقة من ماء مع اختلاف صورها؛ وقد قوبل الموضعان مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص98–115؛ مع ج33، ص274–286.","url":""}]},{"id":"s24-74","number":74,"surah":24,"verses":[45],"verseLabel":"النور: 45","question":"لماذا فصل أصناف الدواب إلى من يمشي على بطنه ورجلين وأربع؟","answer":"جمع أبعد الهيئات اختلافًا ليظهر أن القدرة الواحدة تنوع الخلق من مادة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص98–115.","url":""}]},{"id":"s24-75","number":75,"surah":24,"verses":[46],"verseLabel":"النور: 46","question":"ما سرّ مجيء ﴿آيَاتٍ مُبَيِّنَاتٍ﴾ بلا واو في الآية 46، وبالواو في الآية 34؟","answer":"آية 34 استئناف في تعداد ما أنزل الله فناسبتها الواو، أما آية 46 فجاءت متصلة بما قبلها في الاستدلال فتركت الواو؛ وقد صححت الإحالة بفتح الموضعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص116–121؛ مع ج36، ص732–739.","url":""}]},{"id":"s24-76","number":76,"surah":24,"verses":[47,48],"verseLabel":"النور: 47-48","question":"ما سرّ التعبير عن المنافقين بـ﴿آمَنَّا بِاللَّهِ وَبِالرَّسُولِ وَأَطَعْنَا﴾ ثم تولي فريق منهم؟","answer":"فضح التناقض بين إعلان شامل وفعل جماعة ثابت؛ فالإيمان الذي لا يحكم السلوك مجرد دعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص122–133.","url":""}]},{"id":"s24-77","number":77,"surah":24,"verses":[49],"verseLabel":"النور: 49","question":"لماذا يأتون مذعنين إن كان الحق لهم؟","answer":"لأنهم لم يطلبوا حكم الله لعدله، بل اتخذوه طريقًا إلى المصلحة؛ فالإذعان هنا شاهد عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص142–146.","url":""}]},{"id":"s24-78","number":78,"surah":24,"verses":[50],"verseLabel":"النور: 50","question":"لماذا رتب الاحتمالات: ﴿أَفِي قُلُوبِهِمْ مَرَضٌ أَمِ ارْتَابُوا أَمْ يَخَافُونَ...﴾؟","answer":"رتبت الاحتمالات لاستقصاء أسباب امتناعهم عن الحكم: مرض القلب، أو الشك، أو خوف الجور؛ ثم أبطلها بقوله ﴿بل أولئك هم الظالمون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص147–159.","url":""}]},{"id":"s24-79","number":79,"surah":24,"verses":[51],"verseLabel":"النور: 51","question":"لماذا كان قول المؤمنين ﴿سَمِعْنَا وَأَطَعْنَا﴾؟","answer":"جمع تلقي الحكم والانقياد له في كلمتين، في مقابلة قول المنافقين وانصرافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص160–169.","url":""}]},{"id":"s24-80","number":80,"surah":24,"verses":[52],"verseLabel":"النور: 52","question":"لماذا جمع ﴿يُطِعِ اللَّهَ وَرَسُولَهُ وَيَخْشَ اللَّهَ وَيَتَّقْهِ﴾؟","answer":"الطاعة امتثال ظاهر، والخشية باعث باطن، والتقوى دوام الوقاية؛ وباجتماعها يتم الفوز.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص170–177.","url":""}]},{"id":"s24-81","number":81,"surah":24,"verses":[53],"verseLabel":"النور: 53","question":"ما سرّ التعبير بـ﴿لَا تُقْسِمُوا طَاعَةٌ مَعْرُوفَةٌ﴾؟","answer":"رد الاستعراض اللفظي إلى المطلوب الحقيقي: طاعة صادقة تعرفها الأعمال ولا تحتاج قسمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص178–192.","url":""}]},{"id":"s24-82","number":82,"surah":24,"verses":[54],"verseLabel":"النور: 54","question":"لماذا أظهر لفظ ﴿الرَّسُولِ﴾ في ﴿وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلَاغُ﴾؟","answer":"لإبراز أن وظيفته ناشئة عن رسالته: البلاغ الواضح، أما حساب المعرض فعليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص193–209.","url":""}]},{"id":"s24-83","number":83,"surah":24,"verses":[55],"verseLabel":"النور: 55","question":"لماذا كرر ﴿لَيَسْتَخْلِفَنَّهُمْ... وَلَيُمَكِّنَنَّ... وَلَيُبَدِّلَنَّهُمْ﴾ باللام والنون؟","answer":"توالي المؤكدات يحول الوعد في زمن الخوف إلى يقين راسخ بالاستخلاف والأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص210–236.","url":""}]},{"id":"s24-84","number":84,"surah":24,"verses":[55],"verseLabel":"النور: 55","question":"ما سرّ التعبير بـ﴿يَعْبُدُونَنِي لَا يُشْرِكُونَ بِي شَيْئًا﴾ بضمير المتكلم؟","answer":"قرب الخطاب وشرف العبودية، ثم نفى أي شائبة شرك بـ«شيئًا».","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص210–236.","url":""}]},{"id":"s24-85","number":85,"surah":24,"verses":[58],"verseLabel":"النور: 58","question":"لماذا حدد للاستئذان ثلاث عورات فقط؟","answer":"هي أوقات يغلب فيها انكشاف الإنسان في بيته: قبل الفجر، ووقت القيلولة، وبعد العشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص257–278.","url":""}]},{"id":"s24-86","number":86,"surah":24,"verses":[58],"verseLabel":"النور: 58","question":"ما سرّ التعبير بـ﴿ثَلَاثُ عَوْرَاتٍ لَكُمْ﴾ فسماها عورات؟","answer":"سمى الأزمنة باسم ما يقع فيها للمبالغة في وجوب صونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص257–278.","url":""}]},{"id":"s24-87","number":87,"surah":24,"verses":[59],"verseLabel":"النور: 59","question":"ما سرّ استعمال ﴿إِذَا بَلَغَ﴾ في بلوغ الأطفال بدل «إن بلغ»؟","answer":"استعملت ﴿إذا﴾ لأن بلوغ الأطفال أمر متوقع الوقوع عادة، بخلاف الشرط النادر أو المشكوك؛ وعند البلوغ ينتقل حكمهم إلى الاستئذان العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص279–297.","url":""}]},{"id":"s24-88","number":88,"surah":24,"verses":[60],"verseLabel":"النور: 60","question":"ما سرّ تقييد رخصة القواعد بقوله ﴿غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ﴾؟","answer":"الرخصة في وضع بعض الثياب مرتبطة بزوال قصد إظهار الزينة، فلا تتحول الرخصة إلى تبرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص298–317.","url":""}]},{"id":"s24-89","number":89,"surah":24,"verses":[60],"verseLabel":"النور: 60","question":"لماذا ختم الرخصة بقوله ﴿وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ﴾؟","answer":"بيّن أن الجائز ليس دائمًا الأكمل؛ زيادة الاحتياط أبعد عن الريبة وأصون.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص298–317.","url":""}]},{"id":"s24-90","number":90,"surah":24,"verses":[61],"verseLabel":"النور: 61","question":"لماذا ذكر الأقارب واحدًا واحدًا في رخصة الأكل؟","answer":"رفع الحرج المتوهم بتعيين البيوت المأذون فيها عرفًا، حتى لا يبقى التباس في الحقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص318–358.","url":""}]},{"id":"s24-91","number":91,"surah":24,"verses":[61],"verseLabel":"النور: 61","question":"ما سرّ التعبير بـ﴿أَنْ تَأْكُلُوا جَمِيعًا أَوْ أَشْتَاتًا﴾؟","answer":"أبطل الحرج في صورتين متقابلتين: الاجتماع والانفراد، فكلاهما مباح بلا تكلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص318–358.","url":""}]},{"id":"s24-92","number":92,"surah":24,"verses":[61],"verseLabel":"النور: 61","question":"ما سرّ التعبير بـ﴿فَسَلِّمُوا عَلَى أَنْفُسِكُمْ﴾ عند دخول البيوت؟","answer":"سلام الداخل على أهل البيت سلام على جماعته ونفسه، لما بين المؤمنين من وحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص318–358.","url":""}]},{"id":"s24-93","number":93,"surah":24,"verses":[62],"verseLabel":"النور: 62","question":"ما سرّ وصف المؤمنين بأنهم لا يذهبون حتى يستأذنوا الرسول؟","answer":"جعل أدب الاستئذان علامة إيمان؛ لأن بقاء الجماعة في الأمر الجامع جزء من نجاحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص359–382.","url":""}]},{"id":"s24-94","number":94,"surah":24,"verses":[62],"verseLabel":"النور: 62","question":"ما سرّ اختيار ﴿لِبَعْضِ شَأْنِهِمْ﴾ بدل «لأمرهم»؟","answer":"الشأن أمر ذو عناية وخصوصية، و«بعض» تمنع توهم أن كل عذر يبيح الانصراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص359–382.","url":""}]},{"id":"s24-95","number":95,"surah":24,"verses":[63],"verseLabel":"النور: 63","question":"ما سرّ التعبير بـ﴿لَا تَجْعَلُوا دُعَاءَ الرَّسُولِ بَيْنَكُمْ كَدُعَاءِ بَعْضِكُمْ بَعْضًا﴾؟","answer":"يحتمل النهي ألا ينادوا الرسول باسمه كما ينادي بعضهم بعضًا، أو ألا يجعلوا دعاءه إياهم كدعائهم بعضهم بعضًا؛ والمقام يوجب تعظيم أمره وطاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص383–399.","url":""}]},{"id":"s24-96","number":96,"surah":24,"verses":[63],"verseLabel":"النور: 63","question":"لماذا توعد ﴿الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ﴾ بفتنة أو عذاب؟","answer":"المخالفة ميل وانفصال عن الطريق، و«عن» تصور المجاوزة؛ فعاقبتها فساد القلب أو العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص383–399.","url":""}]},{"id":"s24-97","number":97,"surah":24,"verses":[64],"verseLabel":"النور: 64","question":"لماذا ختمت السورة بـ﴿قَدْ يَعْلَمُ مَا أَنْتُمْ عَلَيْهِ﴾؟","answer":"بعد أحكام الخصوصية كشف أن أحوالهم لا تخفى، وأن الرجوع إليه ينتهي بكشف الأعمال كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص400–414.","url":""}]},{"id":"s25-1","number":1,"surah":25,"verses":[1],"verseLabel":"الفرقان: 1","question":"لماذا افتتحت السورة بـ﴿تَبَارَكَ﴾؟","answer":"افتتحت بـ﴿تبارك﴾ الدالة على تعاظم خير الله وثبوته وعلوه، ثم ذكر تنزيل الفرقان بوصفه من أعظم آثار هذا الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص426–444.","url":""}]},{"id":"s25-2","number":2,"surah":25,"verses":[1],"verseLabel":"الفرقان: 1","question":"ما سرّ تسمية القرآن هنا ﴿الْفُرْقَانَ﴾؟","answer":"سمي القرآن فرقانًا لأنه يفرق بين الحق والباطل والهدى والضلال، وهو معنى يلائم مجادلة السورة لشبه المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص426–444.","url":""}]},{"id":"s25-3","number":3,"surah":25,"verses":[1],"verseLabel":"الفرقان: 1","question":"ما سرّ تعدية ﴿نَزَّلَ الْفُرْقَانَ﴾ بـ«على» في قوله ﴿عَلَى عَبْدِهِ﴾؟","answer":"تعدية التنزيل بـ﴿على﴾ تستحضر نزول الوحي من العلو وتمكنه من قلب المتلقي، ووصف الرسول بالعبودية تشريف له في مقام التلقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص426–444.","url":""}]},{"id":"s25-4","number":4,"surah":25,"verses":[1],"verseLabel":"الفرقان: 1","question":"ما سرّ تخصيص المقام بـ﴿نَذِيرًا﴾ دون الجمع بين البشارة والنذارة؟","answer":"خص الإنذار لأن سياق السورة في مواجهة التكذيب والشرك والتحذير من عاقبتهما، ولا ينفي ذلك ثبوت البشارة في رسالته بمواضع أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص426–444.","url":""}]},{"id":"s25-5","number":5,"surah":25,"verses":[2],"verseLabel":"الفرقان: 2","question":"لماذا جمع ﴿خَلَقَ كُلَّ شَيْءٍ فَقَدَّرَهُ تَقْدِيرًا﴾؟","answer":"الخلق إيجاد، والتقدير إحكام الخصائص والمقادير والغايات؛ فنفى العبث والعشوائية.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص426–444.","url":""}]},{"id":"s25-6","number":6,"surah":25,"verses":[3],"verseLabel":"الفرقان: 3","question":"ما سرّ وصف الآلهة بـ﴿لَا يَخْلُقُونَ شَيْئًا وَهُمْ يُخْلَقُونَ﴾؟","answer":"جمع بين نفي خلقهم شيئًا وإثبات أنهم هم مخلوقون؛ فانتفى عنهم فعل الخالق ووصف الاستقلال، وبطل استحقاقهم للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص445–464.","url":""}]},{"id":"s25-7","number":7,"surah":25,"verses":[3],"verseLabel":"الفرقان: 3","question":"لماذا كرر ﴿لَا يَمْلِكُونَ﴾ في الضر والنفع والموت والحياة والنشور؟","answer":"كرر نفي الملك مع الضر والنفع والموت والحياة والنشور لتفصيل وجوه عجز المعبودات، فنفى عنها التصرف في مبادئ الوجود ومصيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص445–464.","url":""}]},{"id":"s25-8","number":8,"surah":25,"verses":[4],"verseLabel":"الفرقان: 4","question":"ما سرّ التعبير في قولهم ﴿إِفْكٌ افْتَرَاهُ وَأَعَانَهُ عَلَيْهِ قَوْمٌ آخَرُونَ﴾؟","answer":"جمعوا تهمتي الكذب والاستعانة ليبرروا عجزهم عن معارضته، فجاء الحكم ﴿ظُلْمًا وَزُورًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص465–479.","url":""}]},{"id":"s25-9","number":9,"surah":25,"verses":[5],"verseLabel":"الفرقان: 5","question":"ما سرّ تسميتهم القرآن ﴿أَسَاطِيرُ الْأَوَّلِينَ﴾؟","answer":"الأساطير ما سطر من أخبار الأولين، ووصف القرآن بها قصد إلى نفي الوحي عنه وجعله منقولًا من كتب السابقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص480–495.","url":""}]},{"id":"s25-10","number":10,"surah":25,"verses":[5],"verseLabel":"الفرقان: 5","question":"ما سرّ التعبير في قولهم ﴿تُمْلَى عَلَيْهِ بُكْرَةً وَأَصِيلًا﴾؟","answer":"صوروا تعليمًا متكررًا صباحًا ومساءً ليصنعوا قصة بشرية متماسكة، مع افتقارها إلى الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص480–495.","url":""}]},{"id":"s25-11","number":11,"surah":25,"verses":[6],"verseLabel":"الفرقان: 6","question":"لماذا كان الرد ﴿أَنْزَلَهُ الَّذِي يَعْلَمُ السِّرَّ﴾؟","answer":"ناسب الرد اتهامهم بالاختلاق والاستعانة؛ فالذي أنزله يعلم السر في السماوات والأرض، فلا يخفى عليه مصدر القول ولا حقيقة المتهمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص480–495.","url":""}]},{"id":"s25-12","number":12,"surah":25,"verses":[7],"verseLabel":"الفرقان: 7","question":"لماذا اعترضوا بأنه ﴿يَأْكُلُ الطَّعَامَ وَيَمْشِي فِي الْأَسْوَاقِ﴾؟","answer":"جعلوا أكل الطعام والمشي في الأسواق دليلًا على نفي الرسالة؛ فرد السياق بأن البشرية ليست مانعًا، بل الرسل قبلَه كانوا كذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص496–514.","url":""}]},{"id":"s25-13","number":13,"surah":25,"verses":[7],"verseLabel":"الفرقان: 7","question":"ما سرّ مجيء ﴿أُنْزِلَ إِلَيْهِ مَلَكٌ﴾ بـ«إلى» بدل «على»؟","answer":"جاءت ﴿إليه﴾ بالنظر إلى وصول الملك ومصاحبته الرسول في زعمهم، بينما يغلب ﴿عليه﴾ في تنزيل الوحي؛ وهذا فرق سياقي لا قاعدة مطردة بلا استثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص496–514.","url":""}]},{"id":"s25-14","number":14,"surah":25,"verses":[8],"verseLabel":"الفرقان: 8","question":"لماذا اقترحوا كنزًا أو جنة يأكل منها؟","answer":"قاسوا الرسالة على مقاييس الثراء والسلطان، فعجزوا عن إدراك قيمة الهدى ذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص496–514.","url":""}]},{"id":"s25-15","number":15,"surah":25,"verses":[9],"verseLabel":"الفرقان: 9","question":"ما سرّ التعبير بـ﴿انْظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا﴾؟","answer":"الأمثال هنا الأوصاف المتناقضة التي ضربوها للرسول؛ فنتج عنها ضلالهم وعجزهم عن سلوك طريق مستقيم في الاعتراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص515–522.","url":""}]},{"id":"s25-16","number":16,"surah":25,"verses":[10],"verseLabel":"الفرقان: 10","question":"لماذا أجاب اقتراحاتهم بـ﴿تَبَارَكَ الَّذِي إِنْ شَاءَ جَعَلَ لَكَ خَيْرًا مِنْ ذَلِكَ﴾؟","answer":"رد الغنى إلى مشيئة الله، وبيّن أن ترك الإعطاء الدنيوي ليس عجزًا بل حكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص523–531.","url":""}]},{"id":"s25-17","number":17,"surah":25,"verses":[11],"verseLabel":"الفرقان: 11","question":"لماذا انتقل من شبهاتهم إلى ﴿بَلْ كَذَّبُوا بِالسَّاعَةِ﴾؟","answer":"كشف أصل الموقف: ليست مشكلتهم هيئة الرسول، بل إنكار الحساب الذي يلزمهم باتباعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص532–537.","url":""}]},{"id":"s25-18","number":18,"surah":25,"verses":[12],"verseLabel":"الفرقان: 12","question":"ما سرّ تصوير النار بأنها تراهم من مكان بعيد، وأن لهم منها تغيظًا وزفيرًا؟","answer":"شُخِّصت النار حتى كأنها ترى أهلها من بُعد، وأثبت لها التغيظ والزفير؛ لتقديم الرعب قبل الوصول إليها، وفي الآية استعارة وتمثيل لهول الاستقبال.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص538–549.","url":""}]},{"id":"s25-19","number":19,"surah":25,"verses":[13],"verseLabel":"الفرقان: 13","question":"لماذا ألقوا في ﴿مَكَانًا ضَيِّقًا مُقَرَّنِينَ﴾؟","answer":"جمع ضيق المكان وتقييد الأجساد واليأس النفسي؛ فلا حركة ولا فرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص550–561.","url":""}]},{"id":"s25-20","number":20,"surah":25,"verses":[14],"verseLabel":"الفرقان: 14","question":"ما سرّ التعبير بـ﴿لَا تَدْعُوا الْيَوْمَ ثُبُورًا وَاحِدًا وَادْعُوا ثُبُورًا كَثِيرًا﴾؟","answer":"حتى طلب الهلاك لا ينهي العذاب؛ فتعدد أسباب الحسرة يكرر النداء بلا استجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص550–561.","url":""}]},{"id":"s25-21","number":21,"surah":25,"verses":[15],"verseLabel":"الفرقان: 15","question":"لماذا قوبلت النار بـ﴿جَنَّةُ الْخُلْدِ﴾؟","answer":"الخوف الأكبر في العذاب دوامه، فجاء الوعد بجنة وصفها الخلود يزيل كل خوف من الانقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص562–578.","url":""}]},{"id":"s25-22","number":22,"surah":25,"verses":[16],"verseLabel":"الفرقان: 16","question":"ما سرّ التعبير بـ﴿لَهُمْ فِيهَا مَا يَشَاءُونَ﴾ مع حذف مفعول المشيئة؟","answer":"حذف مفعول ﴿يشاءون﴾ لتعم المشيئة كل مرغوب يصلح لهم، ثم أكد ثبوت ذلك بوصفه وعدًا مسؤولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص562–578.","url":""}]},{"id":"s25-23","number":23,"surah":25,"verses":[17],"verseLabel":"الفرقان: 17","question":"لماذا يحشر المعبودين مع عابديهم ويسألهم؟","answer":"ليصدر التكذيب ممن اتخذوهم حجة، فتنهار أمام العابد آخر ذريعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص579–592.","url":""}]},{"id":"s25-24","number":24,"surah":25,"verses":[18],"verseLabel":"الفرقان: 18","question":"لماذا بدأ جواب المعبودين بـ﴿سُبْحَانَكَ﴾؟","answer":"بادروا بتنزيه الله عن الشريك قبل تبرئة أنفسهم، فالتوحيد أعظم من الدفاع الشخصي.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص593–605.","url":""}]},{"id":"s25-25","number":25,"surah":25,"verses":[18],"verseLabel":"الفرقان: 18","question":"ما سرّ التعبير في قول المعبودين ﴿وَلَكِنْ مَتَّعْتَهُمْ وَآبَاءَهُمْ حَتَّى نَسُوا الذِّكْرَ﴾؟","answer":"كشفوا أن طول النعمة بلا شكر أورث الغفلة، لا أن المتاع دليل رضا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص593–605.","url":""}]},{"id":"s25-26","number":26,"surah":25,"verses":[19],"verseLabel":"الفرقان: 19","question":"ما سرّ التعبير بـ﴿فَقَدْ كَذَّبُوكُمْ بِمَا تَقُولُونَ﴾؟","answer":"جعل قول العابد نفسه مادة تكذيبه حين تبرأ منه معبوده؛ فالحجة من داخل دعواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص606–612.","url":""}]},{"id":"s25-27","number":27,"surah":25,"verses":[20],"verseLabel":"الفرقان: 20","question":"ما سرّ تقرير أن الرسل ﴿يَأْكُلُونَ الطَّعَامَ وَيَمْشُونَ فِي الْأَسْوَاقِ﴾؟","answer":"حوّل موضع اعتراضهم إلى سنة عامة في الرسل؛ فالبشرية شرط القدوة لا نقص الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص613–622.","url":""}]},{"id":"s25-28","number":28,"surah":25,"verses":[20],"verseLabel":"الفرقان: 20","question":"ما سرّ التعبير بـ﴿وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً أَتَصْبِرُونَ﴾؟","answer":"اختلاف الأحوال يختبر المتبوع والتابع والغني والفقير؛ والسؤال يستنفر الصبر أمام المقارنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص613–622.","url":""}]},{"id":"s25-29","number":29,"surah":25,"verses":[21],"verseLabel":"الفرقان: 21","question":"ما سرّ التعبير في قولهم ﴿لَوْلَا أُنْزِلَ عَلَيْنَا الْمَلَائِكَةُ أَوْ نَرَى رَبَّنَا﴾؟","answer":"انتقلوا من طلب دليل إلى اشتراط كشف الغيب، فوصفهم النص بالاستكبار والعتو الكبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص624–634.","url":""}]},{"id":"s25-30","number":30,"surah":25,"verses":[22],"verseLabel":"الفرقان: 22","question":"ما سرّ التعبير بـ﴿لَا بُشْرَى يَوْمَئِذٍ لِلْمُجْرِمِينَ﴾ مع أنهم يرون الملائكة؟","answer":"الرؤية التي طلبوها تتحقق يوم انقضاء الاختبار، فتصير علامة عذاب لا بشرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص635–645.","url":""}]},{"id":"s25-31","number":31,"surah":25,"verses":[23],"verseLabel":"الفرقان: 23","question":"ما سرّ تصوير أعمالهم بـ﴿هَبَاءً مَنْثُورًا﴾؟","answer":"الهَبَاء دقائق لا تثبت ولا ينتفع بها، و﴿منثورًا﴾ يزيد صورة التبدد؛ فالمقصود ذهاب نفع أعمالهم يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص646–653.","url":""}]},{"id":"s25-32","number":32,"surah":25,"verses":[24],"verseLabel":"الفرقان: 24","question":"ما سرّ وصف أصحاب الجنة بأنهم ﴿خَيْرٌ مُسْتَقَرًّا وَأَحْسَنُ مَقِيلًا﴾؟","answer":"خاطب حس المقارنة الذي استعمله المكذبون، وقلب ميزانهم إلى الراحة الباقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص654–662.","url":""}]},{"id":"s25-33","number":33,"surah":25,"verses":[25],"verseLabel":"الفرقان: 25","question":"ما سرّ التعبير بـ﴿تَشَقَّقُ السَّمَاءُ بِالْغَمَامِ﴾؟","answer":"مشهد انصداع النظام المألوف وخروج الغمام الذي تنزل فيه الملائكة يصور بدء القضاء العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص663–677.","url":""}]},{"id":"s25-34","number":34,"surah":25,"verses":[27],"verseLabel":"الفرقان: 27","question":"لماذا يعض الظالم على يديه لا على يد واحدة؟","answer":"مضاعفة العض تصور بلوغ الندم أقصاه حتى يستغرق اليدين معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص678–699.","url":""}]},{"id":"s25-35","number":35,"surah":25,"verses":[27],"verseLabel":"الفرقان: 27","question":"ما سرّ التعبير بـ﴿يَا لَيْتَنِي اتَّخَذْتُ مَعَ الرَّسُولِ سَبِيلًا﴾؟","answer":"جعل اتباع الرسول طريقًا كاملًا يسلك، لا معلومة عابرة يسمعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص678–699.","url":""}]},{"id":"s25-36","number":36,"surah":25,"verses":[28,29],"verseLabel":"الفرقان: 28-29","question":"لماذا تحول الندم إلى تسمية الخليل الذي أضله؟","answer":"لأن الصحبة التي بدت قربًا في الدنيا انكشفت سببًا مباشرًا لترك الذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص678–699.","url":""}]},{"id":"s25-37","number":37,"surah":25,"verses":[29],"verseLabel":"الفرقان: 29","question":"لماذا ختم بـ﴿وَكَانَ الشَّيْطَانُ لِلْإِنْسَانِ خَذُولًا﴾؟","answer":"طريق الصديق المضل جزء من نمط شيطاني: يغري أولًا ثم يترك صاحبه عند الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص678–699.","url":""}]},{"id":"s25-38","number":38,"surah":25,"verses":[30],"verseLabel":"الفرقان: 30","question":"ما سرّ التعبير في قول الرسول ﴿اتَّخَذُوا هَذَا الْقُرْآنَ مَهْجُورًا﴾؟","answer":"«اتخذوا» تدل على تعمد حالة مستمرة من الترك، والإشارة تستحضر القرآن القريب الذي أعرضوا عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص700–706.","url":""}]},{"id":"s25-39","number":39,"surah":25,"verses":[31],"verseLabel":"الفرقان: 31","question":"لماذا جعل لكل نبي عدوًا من المجرمين؟","answer":"ليعلم الرسول أن المقاومة سنة الدعوات، وأن كفاية الله في الهداية والنصر أعظم من كثرة الخصوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص707–716.","url":""}]},{"id":"s25-40","number":40,"surah":25,"verses":[32],"verseLabel":"الفرقان: 32","question":"لماذا لم يُنزَّل القرآن جملة واحدة؟","answer":"صرحت الآية بأن التفريق لتثبيت فؤاد الرسول، وأن التنزيل جاء مرتبًا مترسلًا؛ فلا يثبت من هذا الموضع وحده كل تعليل زائد يذكر للتنجيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص717–730.","url":""}]},{"id":"s25-41","number":41,"surah":25,"verses":[32],"verseLabel":"الفرقان: 32","question":"ما سرّ التعبير بـ﴿وَرَتَّلْنَاهُ تَرْتِيلًا﴾؟","answer":"الترتيل تنسيق وتؤدة وتتابع محكم؛ فالتفرق الزمني لم يمنع تمام النظام.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص717–730.","url":""}]},{"id":"s25-42","number":42,"surah":25,"verses":[33],"verseLabel":"الفرقان: 33","question":"ما سرّ التعبير بـ﴿وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَاكَ بِالْحَقِّ﴾؟","answer":"كل شبهة يصوغونها تقابلها إجابة حق وتفسير أحسن، فيتحول اعتراضهم إلى مظهر للإعجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص731–741.","url":""}]},{"id":"s25-43","number":43,"surah":25,"verses":[34],"verseLabel":"الفرقان: 34","question":"لماذا يحشرون على وجوههم؟","answer":"الحشر على الوجوه غاية الإهانة وقلب لهيئة المشي المعتادة، وهو تصوير لعاقبة من ضل عن السبيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص742–751.","url":""}]},{"id":"s25-44","number":44,"surah":25,"verses":[35],"verseLabel":"الفرقان: 35","question":"ما سرّ التعبير بـ﴿وَجَعَلْنَا مَعَهُ أَخَاهُ هَارُونَ وَزِيرًا﴾؟","answer":"«معه» تبرز المعاونة الملازمة، والوزير من يحمل ثقل المهمة مع صاحبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص752–763.","url":""}]},{"id":"s25-45","number":45,"surah":25,"verses":[36],"verseLabel":"الفرقان: 36","question":"لماذا ثنّى الخطاب ﴿اذْهَبَا إِلَى الْقَوْمِ﴾ ثم قال ﴿فَدَمَّرْنَاهُمْ﴾؟","answer":"اختصر تفاصيل الدعوة المعلومة من مواضع أخرى لينتقل سريعًا إلى العبرة من التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص752–763.","url":""}]},{"id":"s25-46","number":46,"surah":25,"verses":[37],"verseLabel":"الفرقان: 37","question":"ما سرّ التعبير عن قوم نوح ﴿كَذَّبُوا الرُّسُلَ﴾ مع أن رسولهم واحد؟","answer":"تكذيب رسول واحد تكذيب لأصل الرسالة المشتركة ولجميع الرسل في دعوتهم الواحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص764–779.","url":""}]},{"id":"s25-47","number":47,"surah":25,"verses":[38],"verseLabel":"الفرقان: 38","question":"لماذا جمع عادًا وثمود وأصحاب الرس في آية واحدة؟","answer":"لضغط أمثلة كثيرة في سجل واحد يدل على تكرر سنة الإنذار والهلاك عبر أمم مختلفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص764–779.","url":""}]},{"id":"s25-48","number":48,"surah":25,"verses":[39],"verseLabel":"الفرقان: 39","question":"ما سرّ التعبير بـ﴿وَكُلًّا ضَرَبْنَا لَهُ الْأَمْثَالَ وَكُلًّا تَبَّرْنَا تَتْبِيرًا﴾؟","answer":"قابل تكرر البيان بتكرر التدمير؛ فلم يقع العقاب إلا بعد إقامة أمثال الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص764–779.","url":""}]},{"id":"s25-49","number":49,"surah":25,"verses":[40],"verseLabel":"الفرقان: 40","question":"ما سرّ التنبيه إلى مرورهم على قرية لوط ثم سؤالهم ﴿أَفَلَمْ يَكُونُوا يَرَوْنَهَا﴾؟","answer":"الدليل لم يكن خبرًا بعيدًا؛ آثار القرية في طريقهم، لكن إنكار البعث عطل الاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص780–791.","url":""}]},{"id":"s25-50","number":50,"surah":25,"verses":[41],"verseLabel":"الفرقان: 41","question":"ما سرّ التعبير في قولهم عن الرسول ﴿أَهَذَا الَّذِي بَعَثَ اللَّهُ رَسُولًا﴾؟","answer":"اسم الإشارة القريب ونبرة الاستفهام يجمعان الاستهزاء والتعجب من اختيار من لا يوافق مقاييسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص792–808.","url":""}]},{"id":"s25-51","number":51,"surah":25,"verses":[42],"verseLabel":"الفرقان: 42","question":"لماذا اعترفوا بأنه كاد يضلهم عن آلهتهم؟","answer":"انفلت من كلامهم اعتراف بقوة الحجة وثبات الرسول، لكنهم سموا الهداية إضلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص792–808.","url":""}]},{"id":"s25-52","number":52,"surah":25,"verses":[43],"verseLabel":"الفرقان: 43","question":"ما سرّ التعبير بـ﴿أَرَأَيْتَ مَنِ اتَّخَذَ إِلَهَهُ هَوَاهُ﴾؟","answer":"جعل الهوى نفسه إلهًا متبوعًا؛ لأن صاحبه يطيعه طاعة العابد، وفي التركيب قلب كاشف لاستيلاء الشهوة على الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص10–20.","url":""}]},{"id":"s25-53","number":53,"surah":25,"verses":[44],"verseLabel":"الفرقان: 44","question":"ما سرّ التعبير بـ﴿أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ﴾؟","answer":"المنفي هو السماع النافع والعقل الذي يهدي، لا مجرد وجود الحاسة؛ ولذلك شُبهوا بالأنعام ثم جعلوا أضل سبيلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص21–32.","url":""}]},{"id":"s25-54","number":54,"surah":25,"verses":[45],"verseLabel":"الفرقان: 45","question":"لماذا جعل الشمس دليلًا على الظل؟","answer":"تغير موقع الظل وطوله لا يدرك إلا بمقارنته بحركة الشمس؛ فكأنها تكشفه وتعرّفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص33–52.","url":""}]},{"id":"s25-55","number":55,"surah":25,"verses":[46],"verseLabel":"الفرقان: 46","question":"ما سرّ التعبير بـ﴿ثُمَّ قَبَضْنَاهُ إِلَيْنَا قَبْضًا يَسِيرًا﴾؟","answer":"صور تقلص الظل التدريجي بقبض لطيف منتظم، وفي ﴿إلينا﴾ رد الظاهرة إلى مدبرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص33–52.","url":""}]},{"id":"s25-56","number":56,"surah":25,"verses":[47],"verseLabel":"الفرقان: 47","question":"ما سرّ وصف الليل لباسًا والنوم سباتًا والنهار نشورًا؟","answer":"الليل يستر، والنوم يقطع الحركة، واليقظة تعيد الانتشار؛ دورة يومية تشبه الموت والبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص53–63.","url":""}]},{"id":"s25-57","number":57,"surah":25,"verses":[48],"verseLabel":"الفرقان: 48","question":"ما سرّ وصف الرياح بأنها ﴿بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ﴾؟","answer":"تسبق المطر بعلاماته كما يتقدم المبشر الخبر السار، وسُمي المطر رحمة لأثره في الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص64–81.","url":""}]},{"id":"s25-58","number":58,"surah":25,"verses":[49],"verseLabel":"الفرقان: 49","question":"ما سرّ وصف ﴿بَلْدَةً﴾ بالمذكر في قوله ﴿بَلْدَةً مَيْتًا﴾؟","answer":"جيء بـ﴿ميتًا﴾ على معنى البلد أو المكان، فروعِي المعنى المذكر مع أن لفظ ﴿بلدة﴾ مؤنث.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص64–81.","url":""}]},{"id":"s25-59","number":59,"surah":25,"verses":[50],"verseLabel":"الفرقان: 50","question":"ما سرّ التعبير بـ﴿وَلَقَدْ صَرَّفْنَاهُ بَيْنَهُمْ لِيَذَّكَّرُوا﴾؟","answer":"تنويع مواقع المطر ومقاديره يجعل النعمة مشاهدة متجددة ودليلًا على التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص82–88.","url":""}]},{"id":"s25-60","number":60,"surah":25,"verses":[52],"verseLabel":"الفرقان: 52","question":"ما سرّ التعبير بـ﴿فَلَا تُطِعِ الْكَافِرِينَ وَجَاهِدْهُمْ بِهِ جِهَادًا كَبِيرًا﴾؟","answer":"الضمير للقرآن؛ فمقاومة الباطل بالحجة والثبات سميت جهادًا كبيرًا لعظم أثرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص89–98.","url":""}]},{"id":"s25-61","number":61,"surah":25,"verses":[53],"verseLabel":"الفرقان: 53","question":"ما سرّ التعبير عن البحرين ﴿هَذَا عَذْبٌ فُرَاتٌ وَهَذَا مِلْحٌ أُجَاجٌ﴾؟","answer":"جمع الإشارة الحسية والوصف المتقابل ليظهر اجتماع الماءين مع بقاء خصائصهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص99–108.","url":""}]},{"id":"s25-62","number":62,"surah":25,"verses":[54],"verseLabel":"الفرقان: 54","question":"لماذا جمع بين النسب والصهر؟","answer":"النسب رابطة الولادة، والصهر رابطة الزواج؛ ومن ماء واحد تتسع شبكة المجتمع بهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص109–117.","url":""}]},{"id":"s25-63","number":63,"surah":25,"verses":[55],"verseLabel":"الفرقان: 55","question":"ما سرّ التعبير بـ﴿وَكَانَ الْكَافِرُ عَلَى رَبِّهِ ظَهِيرًا﴾؟","answer":"المفارقة أنه يستعمل قوة وهبها الرب لمظاهرة الباطل على حق ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص118–126.","url":""}]},{"id":"s25-64","number":64,"surah":25,"verses":[57],"verseLabel":"الفرقان: 57","question":"ما سرّ التعبير بـ﴿إِلَّا مَنْ شَاءَ أَنْ يَتَّخِذَ إِلَى رَبِّهِ سَبِيلًا﴾ بدل طلب الأجر؟","answer":"جعل أجر الرسول عائدًا إلى السامع نفسه: أن يختار طريق الهداية إلى ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص134–143.","url":""}]},{"id":"s25-65","number":65,"surah":25,"verses":[58],"verseLabel":"الفرقان: 58","question":"ما سرّ التعبير بـ﴿وَتَوَكَّلْ عَلَى الْحَيِّ الَّذِي لَا يَمُوتُ﴾؟","answer":"التوكل يحتاج سندًا لا ينقطع؛ فقيّد الحياة بنفي الموت ليبطل الاعتماد على كل فان.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص144–154.","url":""}]},{"id":"s25-66","number":66,"surah":25,"verses":[59],"verseLabel":"الفرقان: 59","question":"ما سرّ التعبير عن السماوات والأرض بضمير التثنية في ﴿وَمَا بَيْنَهُمَا﴾؟","answer":"ثُنّي الضمير لأن السماوات والأرض جُعلتا جهتين جامعتين لما علا وما سفل، فدخل ما بينهما في هذا التقابل.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص155–163.","url":""}]},{"id":"s25-67","number":67,"surah":25,"verses":[60],"verseLabel":"الفرقان: 60","question":"لماذا نفروا من اسم ﴿الرَّحْمَنُ﴾؟","answer":"لأنهم جحدوا الاسم وما يدل عليه، فجاء الأمر بالسجود له اختبارًا لانقيادهم لا لمعلوماتهم فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص164–169.","url":""}]},{"id":"s25-68","number":68,"surah":25,"verses":[61],"verseLabel":"الفرقان: 61","question":"لماذا جمع البروج والسراج والقمر المنير؟","answer":"رتب علامات السماء من منازل الأجرام إلى مصدر ضوء النهار ونور الليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص170–176.","url":""}]},{"id":"s25-69","number":69,"surah":25,"verses":[62],"verseLabel":"الفرقان: 62","question":"لماذا جعل الليل والنهار ﴿خِلْفَةً﴾؟","answer":"﴿خلفة﴾ أي يخلف كل منهما الآخر، فينتظم الزمن، ويجد من أراد التذكر أو الشكر فرصةً متجددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص177–185.","url":""}]},{"id":"s25-70","number":70,"surah":25,"verses":[63],"verseLabel":"الفرقان: 63","question":"لماذا بدأ صفات عباد الرحمن بالمشي على الأرض هونًا؟","answer":"لأن أثر العبودية يظهر أولًا في السمت اليومي ومعاملة الناس، لا في الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص186–193.","url":""}]},{"id":"s25-71","number":71,"surah":25,"verses":[63],"verseLabel":"الفرقان: 63","question":"لماذا يجيبون الجاهلين ﴿سَلَامًا﴾؟","answer":"﴿سلامًا﴾ قول سالم من الإثم أو متاركة بسلام؛ فجوابهم يقطع مجاراة الجاهل ولا يقابل السفه بسفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص186–193.","url":""}]},{"id":"s25-72","number":72,"surah":25,"verses":[64],"verseLabel":"الفرقان: 64","question":"ما سرّ التعبير بـ﴿يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا﴾؟","answer":"«يبيتون» تجعل العبادة وصفًا لليل كله، والجمع بين السجود والقيام يستوعب هيئات الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص194–198.","url":""}]},{"id":"s25-73","number":73,"surah":25,"verses":[65,66],"verseLabel":"الفرقان: 65-66","question":"ما سرّ التعبير في قولهم عن جهنم ﴿إِنَّ عَذَابَهَا كَانَ غَرَامًا﴾؟","answer":"الغرام ملازم لا يفارق المدين؛ فصور دوام العذاب والتصاقه بصاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص199–204.","url":""}]},{"id":"s25-74","number":74,"surah":25,"verses":[67],"verseLabel":"الفرقان: 67","question":"لماذا كان الإنفاق بين الإسراف والتقتير ﴿قَوَامًا﴾؟","answer":"القوام قدر يقيم المعيشة والواجبات؛ وسط منضبط لا مجرد نقطة حسابية بين طرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص205–210.","url":""}]},{"id":"s25-75","number":75,"surah":25,"verses":[68],"verseLabel":"الفرقان: 68","question":"لماذا جمع الشرك والقتل والزنا في سياق واحد؟","answer":"هي أعظم الاعتداءات على حق الخالق والنفس والأسرة، وبها ينهدم نظام الدين والحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص211–226.","url":""}]},{"id":"s25-76","number":76,"surah":25,"verses":[69],"verseLabel":"الفرقان: 69","question":"ما سرّ التعبير بـ﴿يُضَاعَفْ لَهُ الْعَذَابُ﴾ بعد ﴿يَلْقَ أَثَامًا﴾؟","answer":"فسر وعيد «أثامًا» بتعدد العقوبة ودوام الهوان بما يناسب تعدد الجرائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص227–234.","url":""}]},{"id":"s25-77","number":77,"surah":25,"verses":[70],"verseLabel":"الفرقان: 70","question":"ما سرّ التعبير في الفرقان بـ﴿وَعَمِلَ عَمَلًا صَالِحًا﴾، وفي مريم بـ﴿وَعَمِلَ صَالِحًا﴾؟","answer":"سياق مريم أوجز في ذكر المعاصي فأوجز في التوبة، أما الفرقان ففصل الكبائر فناسبه تأكيد العمل بالتصريح بالمفعول المطلق ﴿عملًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص235–246؛ ومع ج31، ص347–362.","url":""}]},{"id":"s25-78","number":78,"surah":25,"verses":[70],"verseLabel":"الفرقان: 70","question":"كيف يبدل الله سيئات التائب حسنات؟","answer":"يبدل الشرك إيمانًا والمعصية طاعة، ويجعل صدق التوبة وما يتبعها سببًا لمحو السيئات وإثابة الحسنات.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص235–246.","url":""}]},{"id":"s25-79","number":79,"surah":25,"verses":[72],"verseLabel":"الفرقان: 72","question":"ما سرّ التعبير بـ﴿لَا يَشْهَدُونَ الزُّورَ﴾ ثم ﴿مَرُّوا بِاللَّغْوِ مَرُّوا كِرَامًا﴾؟","answer":"نفى مشاركتهم في الباطل، ثم وصف مرورهم بما لا ينفع من غير تدنس ولا ابتذال.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص251–260.","url":""}]},{"id":"s25-80","number":80,"surah":25,"verses":[73],"verseLabel":"الفرقان: 73","question":"ما سرّ التعبير بـ﴿لَمْ يَخِرُّوا عَلَيْهَا صُمًّا وَعُمْيَانًا﴾؟","answer":"على توجيه كثير من المفسرين ليس النفي للخرور نفسه، بل لكونه خرورَ صمٍّ وعميان؛ فهم يقبلون على الآيات سامعين بآذان واعية مبصرين بعيون راعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص261–269.","url":""}]},{"id":"s25-81","number":81,"surah":25,"verses":[74],"verseLabel":"الفرقان: 74","question":"لماذا دعوا أن تكون الأزواج والذرية ﴿قُرَّةَ أَعْيُنٍ﴾؟","answer":"طلبوا صلاحًا تقر به العين وتسكن النفس، لا مجرد كثرة النسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص270–282.","url":""}]},{"id":"s25-82","number":82,"surah":25,"verses":[74],"verseLabel":"الفرقان: 74","question":"ما سرّ التعبير في قولهم ﴿وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا﴾ بالإفراد؟","answer":"«إمامًا» اسم جنس أو مصدر، وفيه طلب أن تصير جماعتهم قدوة موحدة في الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص270–282.","url":""}]},{"id":"s25-83","number":83,"surah":25,"verses":[75],"verseLabel":"الفرقان: 75","question":"لماذا كان جزاؤهم ﴿الْغُرْفَةَ بِمَا صَبَرُوا﴾؟","answer":"الغرفة أعلى منازل الجنة، والصبر هو الجامع العملي للصفات السابقة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص283–293.","url":""}]},{"id":"s25-84","number":84,"surah":25,"verses":[77],"verseLabel":"الفرقان: 77","question":"ما سرّ ختم السورة بـ﴿قُلْ مَا يَعْبَأُ بِكُمْ رَبِّي لَوْلَا دُعَاؤُكُمْ﴾؟","answer":"في ﴿دعاؤكم﴾ وجهان أصليان: دعاء الله الناس إلى طاعته، أو دعاؤهم إياه، ويدخل في الثاني العبادة والمسألة؛ فلا يحصر اللفظ في معنى واحد، ثم فرع عليه تهديد المكذبين باللزام.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص298–306.","url":""}]},{"id":"s26-1","number":1,"surah":26,"verses":[2],"verseLabel":"الشعراء: 2","question":"ما سرّ التعبير في الشعراء بـ﴿آيَاتُ الْكِتَابِ الْمُبِينِ﴾، وفي النمل بـ﴿آيَاتُ الْقُرْآنِ وَكِتَابٍ مُبِينٍ﴾؟","answer":"أفردت الشعراء وصف ﴿الكتاب﴾، وبيّن مبحثها دلالته على الكتاب المنزل الجامع للحق والشرائع؛ وجمع مبحث النمل بين الاسمين لأن القرآن هو الكتاب نفسه، فاستحضر وصف التلاوة ووصف الكتابة والجمع معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص317–322؛ وج39، ص587–591.","url":""}]},{"id":"s26-2","number":2,"surah":26,"verses":[3],"verseLabel":"الشعراء: 3","question":"ما سرّ التعبير بـ﴿لَعَلَّكَ بَاخِعٌ نَفْسَكَ﴾؟","answer":"﴿باخع﴾ بمعنى مهلك أو قاتل نفسه من شدة الحزن؛ فالتركيب يصور فرط حرص الرسول على إيمانهم، ثم يسليه بأن الإيمان القهري ليس مقصود الابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص323–343.","url":""}]},{"id":"s26-3","number":3,"surah":26,"verses":[3],"verseLabel":"الشعراء: 3","question":"ما سرّ التعبير بـ﴿أَلَّا يَكُونُوا مُؤْمِنِينَ﴾ بصيغة الوصف، لا «ألا يؤمنوا»؟","answer":"جيء بالخبر الدال على ثبوت الوصف واستمراره؛ لأن الحزن متعلق ببقائهم غير مؤمنين، لا بمجرد فوات فعل منفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص323–343.","url":""}]},{"id":"s26-4","number":4,"surah":26,"verses":[4],"verseLabel":"الشعراء: 4","question":"ما سرّ التعبير بـ﴿إِنْ نَشَأْ نُنَزِّلْ عَلَيْهِمْ مِنَ السَّمَاءِ آيَةً فَظَلَّتْ أَعْنَاقُهُمْ لَهَا خَاضِعِينَ﴾؟","answer":"بيّن أن الإيمان القهري ممكن، لكن الحكمة اقتضت ابتلاء الاختيار؛ وأسند الخضوع للأعناق تصويرًا للذلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص323–343.","url":""}]},{"id":"s26-5","number":5,"surah":26,"verses":[5],"verseLabel":"الشعراء: 5","question":"ما سرّ التعبير هنا بـ﴿مِنْ ذِكْرٍ مِنَ الرَّحْمَنِ مُحْدَثٍ﴾، وفي الأنبياء بـ﴿مِنْ ذِكْرٍ مِنْ رَبِّهِمْ مُحْدَثٍ﴾؟","answer":"اختير ﴿الرحمن﴾ في الشعراء لمناسبة الرحمة التي جاءهم بها الذكر مع إعراضهم عنها، واختير ﴿ربهم﴾ في الأنبياء لمقام إقامة الحجة عليهم بربوبيته ونعمته؛ والمقارنة مقيدة بما قرره المبحثان.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص323–343؛ وج33، ص53–61.","url":""}]},{"id":"s26-6","number":6,"surah":26,"verses":[6],"verseLabel":"الشعراء: 6","question":"ما سرّ التعبير بـ﴿فَقَدْ كَذَّبُوا فَسَيَأْتِيهِمْ أَنْبَاءُ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ﴾؟","answer":"درّج الجريمة من الإعراض إلى التكذيب إلى الاستهزاء، ثم جعل العذاب «أنباء» تتحول فيها الأخبار إلى واقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص323–343.","url":""}]},{"id":"s26-7","number":7,"surah":26,"verses":[7],"verseLabel":"الشعراء: 7","question":"ما سرّ التعبير بـ﴿كَمْ أَنْبَتْنَا فِيهَا مِنْ كُلِّ زَوْجٍ كَرِيمٍ﴾؟","answer":"«كم» تكثّر الأنواع، و«زوج» للصنف، و«كريم» لما اجتمع فيه الحسن والنفع؛ فالمشهد حجة مشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص344–354.","url":""}]},{"id":"s26-8","number":8,"surah":26,"verses":[8,9],"verseLabel":"الشعراء: 8-9","question":"لماذا تكرر بعد الآيات ﴿إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُمْ مُؤْمِنِينَ * وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ﴾؟","answer":"تكرار الخاتمة بعد القصص صار لازمة تربط بين الآية الدالة، وقلة المستجيبين، ثم الجمع بين عزة الله على المكذبين ورحمته بالمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص344–354.","url":""}]},{"id":"s26-9","number":9,"surah":26,"verses":[10],"verseLabel":"الشعراء: 10","question":"ما سرّ التعبير في بدء قصة موسى بـ﴿وَإِذْ نَادَى رَبُّكَ مُوسَى﴾؟","answer":"النداء يستحضر قرب التكليم وهيبة التكليف، فيدخل السامع القصة من لحظتها الحية.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص355–360.","url":""}]},{"id":"s26-10","number":10,"surah":26,"verses":[10],"verseLabel":"الشعراء: 10","question":"ما سرّ التعبير بـ﴿أَنِ ائْتِ الْقَوْمَ الظَّالِمِينَ * قَوْمَ فِرْعَوْنَ﴾؟","answer":"أجمل وصفهم بالظلم أولًا ثم أبدل الاسم ليفسرهم، فيسبق الحكم الأخلاقي التعريف التاريخي.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص355–360.","url":""}]},{"id":"s26-11","number":11,"surah":26,"verses":[12,13],"verseLabel":"الشعراء: 12-13","question":"ما سرّ التعبير في قول موسى ﴿يَضِيقُ صَدْرِي وَلَا يَنْطَلِقُ لِسَانِي فَأَرْسِلْ إِلَى هَارُونَ﴾؟","answer":"ذكر أثر التكليف في نفسه ووسيلة البيان، وطلب إشراك هارون في الرسالة لا إعفاءه منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص361–370.","url":""}]},{"id":"s26-12","number":12,"surah":26,"verses":[15],"verseLabel":"الشعراء: 15","question":"ما سرّ مجيء ﴿مَعَكُمْ﴾ بضمير الجمع في قوله ﴿إِنَّا مَعَكُمْ مُسْتَمِعُونَ﴾؟","answer":"عدل عن التثنية إلى الجمع لأن معية الله محيطة بموسى وهارون وفرعون وقومه: مع أهل الحق بالنصر والحفظ، ومع أهل الباطل بالقهر والكسر؛ وهذا هو التعليل الصريح في المبحث.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص371–379.","url":""}]},{"id":"s26-13","number":13,"surah":26,"verses":[16],"verseLabel":"الشعراء: 16","question":"ما سرّ التعبير في قولهما ﴿إِنَّا رَسُولُ رَبِّ الْعَالَمِينَ﴾ بإفراد ﴿رَسُولُ﴾؟","answer":"﴿رسول﴾ يجوز أن يكون مصدرًا يستوي فيه الواحد والاثنان، كما أن إفراده يلائم وحدة الرسالة التي حملاها معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص371–379.","url":""}]},{"id":"s26-14","number":14,"surah":26,"verses":[17],"verseLabel":"الشعراء: 17","question":"ما سرّ اختيار الاسم الصريح ﴿بَنِي إِسْرَائِيلَ﴾ بدل «قومنا»؟","answer":"الاسم الصريح يثبت هويتهم المستقلة التي حاول الاستعباد محوها، ويشرف نسبتهم إلى إسرائيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص371–379.","url":""}]},{"id":"s26-15","number":15,"surah":26,"verses":[18],"verseLabel":"الشعراء: 18","question":"ما سرّ التعبير في قول فرعون ﴿أَلَمْ نُرَبِّكَ فِينَا وَلِيدًا﴾؟","answer":"اختار «وليدًا» ليستحضر ضعفه وفضل القصر عليه، محاولًا تحويل التربية إلى دين يمنع الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص380–386.","url":""}]},{"id":"s26-16","number":16,"surah":26,"verses":[19],"verseLabel":"الشعراء: 19","question":"ما سرّ كناية فرعون عن القتل بقوله ﴿وَفَعَلْتَ فَعْلَتَكَ الَّتِي فَعَلْتَ﴾؟","answer":"أبهم الفعلة مع تكرار مادتها لاستحضارها والتشهير بها كأنها معلومة لا تحتاج إلى تسمية، وفي ذلك تهويل اتهامي.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص380–386.","url":""}]},{"id":"s26-17","number":17,"surah":26,"verses":[19],"verseLabel":"الشعراء: 19","question":"ما سرّ وصف فرعون موسى بقوله ﴿وَأَنْتَ مِنَ الْكَافِرِينَ﴾؟","answer":"فسر ﴿الكافرين﴾ هنا بكفران نعمة فرعون في زعمه، وقيل أراد الضلال عن دينه؛ فلا يلزم حمله على الكفر العقدي وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص380–386.","url":""}]},{"id":"s26-18","number":18,"surah":26,"verses":[20],"verseLabel":"الشعراء: 20","question":"ما سرّ التعبير في قول موسى ﴿فَعَلْتُهَا إِذًا وَأَنَا مِنَ الضَّالِّينَ﴾؟","answer":"أقر بالفعل ونفى تعمد القتل، فوصف حاله آنذاك بعدم معرفة طريق النبوة أو عاقبة الوكزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص387–407.","url":""}]},{"id":"s26-19","number":19,"surah":26,"verses":[22],"verseLabel":"الشعراء: 22","question":"ما سرّ تسمية موسى استعباد بني إسرائيل ﴿نِعْمَةً تَمُنُّهَا عَلَيَّ﴾؟","answer":"جاء الكلام على سبيل الإنكار وقلب المنة: فتربية موسى في بيت فرعون إنما نشأت من استعباد بني إسرائيل وقتل أبنائهم، فكانت الجناية أصل ما امتن به.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص387–407.","url":""}]},{"id":"s26-20","number":20,"surah":26,"verses":[23],"verseLabel":"الشعراء: 23","question":"ما سرّ سؤال فرعون بـ﴿وَمَا رَبُّ الْعَالَمِينَ﴾ باستعمال «ما»؟","answer":"استعمال ﴿ما﴾ سؤال عن حقيقة الرب على جهة الإنكار أو التجاهل، فأجابه موسى بآثار الربوبية المشهودة بدل التسليم بفساد السؤال.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص408–417.","url":""}]},{"id":"s26-21","number":21,"surah":26,"verses":[24,25,26],"verseLabel":"الشعراء: 24-26","question":"لماذا تنقل موسى من ﴿رَبُّ السَّمَاوَاتِ وَالْأَرْضِ﴾ إلى ﴿رَبُّكُمْ وَرَبُّ آبَائِكُمُ﴾؟","answer":"بدأ بالكون العام، ثم أدخل المخاطبين وآباءهم في سلطان الرب ليقطع وهم ألوهية فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص408–417.","url":""}]},{"id":"s26-22","number":22,"surah":26,"verses":[27],"verseLabel":"الشعراء: 27","question":"لماذا اتهم فرعون الرسول المرسل إليهم بأنه ﴿لَمَجْنُونٌ﴾؟","answer":"حين عجز عن مناقشة الدليل نقل الخصومة إلى شخص المتكلم؛ و«لمجنون» توكيد يراد به التحريض.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص427–437.","url":""}]},{"id":"s26-23","number":23,"surah":26,"verses":[28],"verseLabel":"الشعراء: 28","question":"لماذا ختم موسى الحجة بـ﴿رَبُّ الْمَشْرِقِ وَالْمَغْرِبِ وَمَا بَيْنَهُمَا﴾؟","answer":"أشار إلى النظام اليومي الذي لا يملكه فرعون ويشاهده الجميع، ثم علق الانتفاع بالتعقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص427–437.","url":""}]},{"id":"s26-24","number":24,"surah":26,"verses":[29],"verseLabel":"الشعراء: 29","question":"لماذا انتقل فرعون من الجدل إلى التهديد بالسجن؟","answer":"لأن الحجة أفلتت من يده، فاستبدل سلطان البرهان بسلطان القهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص438–459.","url":""}]},{"id":"s26-25","number":25,"surah":26,"verses":[30],"verseLabel":"الشعراء: 30","question":"ما سرّ التعبير في قول موسى ﴿أَوَلَوْ جِئْتُكَ بِشَيْءٍ مُبِينٍ﴾؟","answer":"علّق التهديد على امتحان الدليل: أتسجنني حتى لو جئتك بحجة ظاهرة؟ فاضطر فرعون لقبول العرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص438–459.","url":""}]},{"id":"s26-26","number":26,"surah":26,"verses":[32,33],"verseLabel":"الشعراء: 32-33","question":"لماذا كانت العصا ﴿ثُعْبَانٌ مُبِينٌ﴾ واليد ﴿بَيْضَاءَ لِلنَّاظِرِينَ﴾؟","answer":"وصف العصا بـ﴿ثعبان مبين﴾ لظهور حقيقتها للناظرين، ووصف اليد بـ﴿بيضاء للناظرين﴾ لبيان ظهور بياضها السليم من المرض؛ فكلتا الآيتين مشاهدة لا تلتبس.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص438–459.","url":""}]},{"id":"s26-27","number":27,"surah":26,"verses":[34],"verseLabel":"الشعراء: 34","question":"ما سرّ قول فرعون للملأ ﴿إِنَّ هَذَا لَسَاحِرٌ عَلِيمٌ﴾ دون التصريح باسم موسى؟","answer":"اسم الإشارة يستحضر موسى أمام الملأ، ووصفه بالساحر العليم محاولة لتحويل المعجزة إلى مهارة بشرية مع توكيد الاتهام بـ﴿إن﴾ واللام.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص460–479.","url":""}]},{"id":"s26-28","number":28,"surah":26,"verses":[35],"verseLabel":"الشعراء: 35","question":"ما سرّ التعبير في قول فرعون ﴿يُرِيدُ أَنْ يُخْرِجَكُمْ مِنْ أَرْضِكُمْ﴾؟","answer":"حوّل قضية التوحيد إلى تهديد أمني ليستنفر الملأ دفاعًا عن مصالحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص460–479.","url":""}]},{"id":"s26-29","number":29,"surah":26,"verses":[36],"verseLabel":"الشعراء: 36","question":"ما سرّ التعبير بـ﴿أَرْجِهْ وَأَخَاهُ وَابْعَثْ فِي الْمَدَائِنِ حَاشِرِينَ﴾؟","answer":"﴿أرجه﴾ أي أخّره وأمهله، ثم طُلب بعث جامعين في المدن لحشر السحرة؛ فانتقلوا من استعجال العقوبة إلى إعداد المعارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص460–479.","url":""}]},{"id":"s26-30","number":30,"surah":26,"verses":[38,39],"verseLabel":"الشعراء: 38-39","question":"لماذا حُشر الناس ﴿لِمِيقَاتِ يَوْمٍ مَعْلُومٍ﴾ وسئلوا ﴿هَلْ أَنْتُمْ مُجْتَمِعُونَ﴾؟","answer":"ضخم الإعلام الجماهيري للمواجهة ليجعل انتصار الحق على الملأ نفسه الذي أعدوه للباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص480–487.","url":""}]},{"id":"s26-31","number":31,"surah":26,"verses":[41],"verseLabel":"الشعراء: 41","question":"ما سرّ التعبير في قول السحرة بـ﴿أَئِنَّ لَنَا لَأَجْرًا إِنْ كُنَّا نَحْنُ الْغَالِبِينَ﴾؟","answer":"كشفوا منذ البداية أن محركهم الأجر والقرب من السلطان، لا طلب الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص499–517.","url":""}]},{"id":"s26-32","number":32,"surah":26,"verses":[43],"verseLabel":"الشعراء: 43","question":"ما سرّ التعبير في قول موسى بـ﴿أَلْقُوا مَا أَنْتُمْ مُلْقُونَ﴾؟","answer":"لم يأمر بالسحر إقرارًا له، بل أذن ببدء المباراة ليظهر بطلانه بعد استفراغهم وسعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص518–531.","url":""}]},{"id":"s26-33","number":33,"surah":26,"verses":[44],"verseLabel":"الشعراء: 44","question":"لماذا أقسم السحرة ﴿بِعِزَّةِ فِرْعَوْنَ﴾؟","answer":"أظهر القسم مصدر ثقتهم الزائف، ليقابله بعد لحظات إيمانهم برب العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص518–531.","url":""}]},{"id":"s26-34","number":34,"surah":26,"verses":[45],"verseLabel":"الشعراء: 45","question":"ما سرّ التعبير عن العصا الواحدة بـ﴿تَلْقَفُ مَا يَأْفِكُونَ﴾ أمام حبال وعصي كثيرة؟","answer":"العصا آية حق واحدة، و﴿تلقف﴾ تصور الأخذ السريع؛ أما عمل السحرة فسماه ﴿إفكًا﴾ لأنه يقلب الإدراك عن الحقيقة، فلا يدل جمع أدواتهم على قوة أمام الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص532–551.","url":""}]},{"id":"s26-35","number":35,"surah":26,"verses":[46],"verseLabel":"الشعراء: 46","question":"ما سرّ التعبير بـ﴿فَأُلْقِيَ السَّحَرَةُ سَاجِدِينَ﴾ بالبناء للمجهول؟","answer":"صور قوة البرهان كأنها ألقتهم إلى السجود بلا تردد ولا تدبير سابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص532–551.","url":""}]},{"id":"s26-36","number":36,"surah":26,"verses":[47,48],"verseLabel":"الشعراء: 47-48","question":"ما سرّ قول السحرة ﴿آمَنَّا بِرَبِّ الْعَالَمِينَ * رَبِّ مُوسَى وَهَارُونَ﴾؟","answer":"أزال البدل أي التباس بفرعون الذي ادعى الربوبية، وحددوا الرب الذي جاء موسى وهارون بآياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص532–551.","url":""}]},{"id":"s26-37","number":37,"surah":26,"verses":[49],"verseLabel":"الشعراء: 49","question":"ما سرّ التعبير في قول فرعون بـ﴿آمَنْتُمْ لَهُ﴾ باللام؟","answer":"عدّ إيمانهم انقيادًا لموسى وتآمرًا معه، محاولًا صرف الأنظار عن إيمانهم بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص552–577.","url":""}]},{"id":"s26-38","number":38,"surah":26,"verses":[49],"verseLabel":"الشعراء: 49","question":"لماذا هددهم بتقطيع الأيدي والأرجل من خلاف ثم الصلب أجمعين؟","answer":"جمع التشويه والألم والتشهير، وأكد الشمول ليعيد بناء الخوف الذي هدمه الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص552–577.","url":""}]},{"id":"s26-39","number":39,"surah":26,"verses":[50],"verseLabel":"الشعراء: 50","question":"لماذا أجاب السحرة ﴿لَا ضَيْرَ إِنَّا إِلَى رَبِّنَا مُنْقَلِبُونَ﴾؟","answer":"صغّروا ضرر الدنيا أمام الرجوع المؤكد إلى الرب؛ فتحول تهديد الموت إلى طريق لقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص578–597.","url":""}]},{"id":"s26-40","number":40,"surah":26,"verses":[52],"verseLabel":"الشعراء: 52","question":"لماذا جاء الأمر بالإسراء ببني إسرائيل بعد قصة السحرة مباشرة؟","answer":"بعد سقوط هيبة فرعون معنويًا بدأ إخراج المستضعفين فعليًا؛ فانفتح طريق النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص598–619.","url":""}]},{"id":"s26-41","number":41,"surah":26,"verses":[53],"verseLabel":"الشعراء: 53","question":"ما سرّ تكرار فعل الحشر في قوله ﴿فَأَرْسَلَ فِرْعَوْنُ فِي الْمَدَائِنِ حَاشِرِينَ﴾ بعد وروده في جمع السحرة؟","answer":"تحقق اقتراحهم نفسه مرة ثانية، لكن الحشر الأول للسحرة والحشر الثاني للجنود؛ وكلاهما انتهى عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص598–619.","url":""}]},{"id":"s26-42","number":42,"surah":26,"verses":[54],"verseLabel":"الشعراء: 54","question":"ما سرّ وصف بني إسرائيل بـ﴿شِرْذِمَةٌ قَلِيلُونَ﴾؟","answer":"حقّر عددهم ليطمئن قومه، ثم بالغ في التعبئة ضدهم فكشف خوفه وتناقضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص598–619.","url":""}]},{"id":"s26-43","number":43,"surah":26,"verses":[57,58],"verseLabel":"الشعراء: 57-58","question":"لماذا عدد ﴿جَنَّاتٍ وَعُيُونٍ * وَكُنُوزٍ وَمَقَامٍ كَرِيمٍ﴾؟","answer":"فصّل ما أخرجوا منه ليظهر حجم الخسارة التي جرها الاستكبار في لحظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص620–635.","url":""}]},{"id":"s26-44","number":44,"surah":26,"verses":[61],"verseLabel":"الشعراء: 61","question":"ما سرّ التعبير في قول أصحاب موسى بـ﴿إِنَّا لَمُدْرَكُونَ﴾ بالاسمية والتوكيد؟","answer":"رأوا البحر أمامهم والعدو خلفهم فصاغوا الخطر كأنه واقع ثابت لا مهرب منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص636–643.","url":""}]},{"id":"s26-45","number":45,"surah":26,"verses":[62],"verseLabel":"الشعراء: 62","question":"ما سرّ التعبير في قول موسى بـ﴿كَلَّا إِنَّ مَعِيَ رَبِّي سَيَهْدِينِ﴾؟","answer":"قابل يقينهم بالهلاك بيقين المعية والهداية؛ لم يعرف الطريق بعد لكنه عرف المدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص644–648.","url":""}]},{"id":"s26-46","number":46,"surah":26,"verses":[63],"verseLabel":"الشعراء: 63","question":"ما سرّ إظهار اسم موسى في ﴿فَأَوْحَيْنَا إِلَى مُوسَى أَنِ اضْرِبْ﴾ بعد قوله ﴿قَالَ مُوسَى﴾؟","answer":"أُظهر اسم موسى بدل الضمير لتجديد حضوره عند انتقال المشهد من قوله المطمئن إلى تلقي الوحي وصنع المعجزة، ودفع أي التباس في تتابع الأحداث.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص649–657.","url":""}]},{"id":"s26-47","number":47,"surah":26,"verses":[63],"verseLabel":"الشعراء: 63","question":"لماذا صار كل فرق من البحر ﴿كَالطَّوْدِ الْعَظِيمِ﴾؟","answer":"الطود جبل راسخ؛ فصوّر الماء السائل جدارًا شامخًا ثابتًا بقدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص649–657.","url":""}]},{"id":"s26-48","number":48,"surah":26,"verses":[65],"verseLabel":"الشعراء: 65","question":"ما سرّ التعبير بـ﴿وَأَنْجَيْنَا مُوسَى وَمَنْ مَعَهُ أَجْمَعِينَ﴾؟","answer":"التصريح بالمعية والشمول يقطع توهم ضياع فرد من الجماعة المستضعفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص658–664.","url":""}]},{"id":"s26-49","number":49,"surah":26,"verses":[69],"verseLabel":"الشعراء: 69","question":"ما سرّ التعبير بـ﴿وَاتْلُ عَلَيْهِمْ نَبَأَ إِبْرَاهِيمَ﴾ بعد قصة موسى؟","answer":"انتقل من طغيان السلطة إلى تقليد الآباء، وهما أصلان بارزان لمقاومة الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص672–681.","url":""}]},{"id":"s26-50","number":50,"surah":26,"verses":[71],"verseLabel":"الشعراء: 71","question":"ما سرّ التعبير في قول قوم إبراهيم ﴿فَنَظَلُّ لَهَا عَاكِفِينَ﴾؟","answer":"«نظل» تفيد ملازمة النهار، و«عاكفين» الثبات؛ فافتخروا بدوام ما كان موضع نقدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص672–681.","url":""}]},{"id":"s26-51","number":51,"surah":26,"verses":[72,73],"verseLabel":"الشعراء: 72-73","question":"لماذا سألهم إبراهيم عن السماع والنفع والضر؟","answer":"نقل العبادة من قوة العادة إلى اختبار العقل: هل للمعبود إدراك أو أثر يستحق العبادة؟","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص682–686.","url":""}]},{"id":"s26-52","number":52,"surah":26,"verses":[74],"verseLabel":"الشعراء: 74","question":"لماذا لم يجيبوا عن الحجة وقالوا ﴿بَلْ وَجَدْنَا آبَاءَنَا كَذَلِكَ يَفْعَلُونَ﴾؟","answer":"لأن التقليد كان دليلهم الأخير؛ وصفوا فعل الآباء بدل بيان حق المعبود.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص687–691.","url":""}]},{"id":"s26-53","number":53,"surah":26,"verses":[77],"verseLabel":"الشعراء: 77","question":"ما سرّ إفراد ﴿عَدُوٌّ﴾ في قول إبراهيم عن الأصنام ﴿فَإِنَّهُمْ عَدُوٌّ لِي﴾؟","answer":"﴿عدو﴾ يستعمل للمفرد والجمع، وفي إفراده جمع الأصنام كلها في جهة عداوة واحدة للهدى، مع بقاء المطابقة المعنوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص692–700.","url":""}]},{"id":"s26-54","number":54,"surah":26,"verses":[78,79,80,81,82],"verseLabel":"الشعراء: 78-82","question":"ما سرّ تكرار الضمير المنفصل في ﴿فَهُوَ يَهْدِينِ﴾ و﴿هُوَ يُطْعِمُنِي وَيَسْقِينِ﴾ و﴿فَهُوَ يَشْفِينِ﴾؟","answer":"تكرار الضمير يجدد قصر هذه الأفعال على الله واستحضار المنعم عند كل نعمة؛ واختص الشفاء بالتعبير ﴿فهو﴾ بعد إسناد المرض إلى المتكلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص701–716.","url":""}]},{"id":"s26-55","number":55,"surah":26,"verses":[80],"verseLabel":"الشعراء: 80","question":"ما سرّ التعبير بـ﴿وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ﴾ فنسب إبراهيم المرض إلى نفسه؟","answer":"هذا من أدب النبوة في العبارة؛ صرّح بنسبة الخلق والهداية والإطعام والشفاء إلى الله، وأسند المرض إلى نفسه مع أن الجميع بتقدير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص701–716.","url":""}]},{"id":"s26-56","number":56,"surah":26,"verses":[83],"verseLabel":"الشعراء: 83","question":"لماذا دعا ﴿رَبِّ هَبْ لِي حُكْمًا﴾؟","answer":"«هب» تسأل عطية محضة، و«حكمًا» يجمع العلم الصائب والقدرة على العمل والقضاء به.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص717–722.","url":""}]},{"id":"s26-57","number":57,"surah":26,"verses":[84],"verseLabel":"الشعراء: 84","question":"لماذا طلب ﴿لِسَانَ صِدْقٍ فِي الْآخِرِينَ﴾؟","answer":"طلب ثناءً صادقًا يبقي أثر دعوته في الأجيال، لا شهرة منفصلة عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص723–732.","url":""}]},{"id":"s26-58","number":58,"surah":26,"verses":[85],"verseLabel":"الشعراء: 85","question":"ما سرّ التعبير بـ﴿مِنْ وَرَثَةِ جَنَّةِ النَّعِيمِ﴾؟","answer":"صور الجنة ميراثًا مستقرًا يؤول إلى أهل الإيمان، وخص النعيم لمقابلة عذاب ذلك اليوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص733–739.","url":""}]},{"id":"s26-59","number":59,"surah":26,"verses":[86],"verseLabel":"الشعراء: 86","question":"لماذا دعا لأبيه بالمغفرة مع أنه عدو لله؟","answer":"كان ذلك قبل أن يتبين له إصراره وعداوته، فلما تبين تبرأ منه كما أوضحت التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص740–749.","url":""}]},{"id":"s26-60","number":60,"surah":26,"verses":[88,89],"verseLabel":"الشعراء: 88-89","question":"ما سرّ التعبير بـ﴿يَوْمَ لَا يَنْفَعُ مَالٌ وَلَا بَنُونَ * إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ﴾؟","answer":"أبطل أعظم أدوات القوة الدنيوية، واستثنى سلامة القلب من الشرك والفساد لأنها أصل النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص750–768.","url":""}]},{"id":"s26-61","number":61,"surah":26,"verses":[90,91],"verseLabel":"الشعراء: 90-91","question":"ما سرّ التعبير بـ﴿وَأُزْلِفَتِ الْجَنَّةُ﴾ و﴿بُرِّزَتِ الْجَحِيمُ﴾؟","answer":"قُرّبت الجنة إكرامًا، وكُشفت النار إزالة لكل ستر ووهم عند الغاوين.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص769–783.","url":""}]},{"id":"s26-62","number":62,"surah":26,"verses":[94,95],"verseLabel":"الشعراء: 94-95","question":"ما سرّ التعبير بـ﴿فَكُبْكِبُوا فِيهَا هُمْ وَالْغَاوُونَ * وَجُنُودُ إِبْلِيسَ﴾؟","answer":"تكرار بنية «كب» يصور التدحرج المتتابع، وجمع القادة والأتباع ومصادر الإغواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص795–806.","url":""}]},{"id":"s26-63","number":63,"surah":26,"verses":[97],"verseLabel":"الشعراء: 97","question":"ما سرّ القسم بالتاء في قول أهل النار ﴿تَاللَّهِ إِنْ كُنَّا لَفِي ضَلَالٍ مُبِينٍ﴾؟","answer":"تاء القسم تستعمل في مقام التعجب، فناسبت دهشتهم المتأخرة من تسويتهم الأصنام برب العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص10–25.","url":""}]},{"id":"s26-64","number":64,"surah":26,"verses":[105],"verseLabel":"الشعراء: 105","question":"ما سرّ تأنيث ﴿كَذَّبَتْ﴾ وجمع ﴿الْمُرْسَلِينَ﴾ في قوله ﴿كَذَّبَتْ قَوْمُ نُوحٍ الْمُرْسَلِينَ﴾؟","answer":"أُنث الفعل على معنى الجماعة أو القبيلة في لفظ ﴿قوم﴾، وجُمع المرسلون لأن تكذيب رسول واحد تكذيب لأصل الرسالة الذي اتفق عليه جميع الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص62–88.","url":""}]},{"id":"s26-65","number":65,"surah":26,"verses":[106],"verseLabel":"الشعراء: 106","question":"ما سرّ وصف نوح بأنه ﴿أَخُوهُمْ﴾؟","answer":"أثبت قرب النسب والمعرفة ليبطل توهم الغرابة أو الجهل بحاله، لا أخوة الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص62–88.","url":""}]},{"id":"s26-66","number":66,"surah":26,"verses":[109],"verseLabel":"الشعراء: 109","question":"ما سرّ تكرار ﴿وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ﴾ على ألسنة الرسل؟","answer":"تكرر اللفظ لتأكيد وحدة دعوة الرسل ونزاهتها من طلب المال، فكل رسول يرد شبهة المصلحة الشخصية بأن أجره على رب العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص62–88.","url":""}]},{"id":"s26-67","number":67,"surah":26,"verses":[111],"verseLabel":"الشعراء: 111","question":"لماذا اعترض قوم نوح بأن أتباعه هم ﴿الْأَرْذَلُونَ﴾؟","answer":"لما عجزوا عن رد الرسالة طعنوا في المكانة الاجتماعية لأتباعها، وكأن الحق يقاس بطبقتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص89–100.","url":""}]},{"id":"s26-68","number":68,"surah":26,"verses":[112],"verseLabel":"الشعراء: 112","question":"ما سرّ التعبير في قول نوح بـ﴿وَمَا عِلْمِي بِمَا كَانُوا يَعْمَلُونَ﴾؟","answer":"مهمته الحكم بالظاهر ودعوة الناس، لا تفتيش سرائر الفقراء لإرضاء المتكبرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص101–117.","url":""}]},{"id":"s26-69","number":69,"surah":26,"verses":[114],"verseLabel":"الشعراء: 114","question":"ما سرّ التعبير الاسمي بـ﴿وَمَا أَنَا بِطَارِدِ الْمُؤْمِنِينَ﴾؟","answer":"التركيب الاسمي المؤكد بالباء ينفي أن يكون طرد المؤمنين وصفًا أو شأنًا ثابتًا لنوح، لا مجرد نفي واقعة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص101–117.","url":""}]},{"id":"s26-70","number":70,"surah":26,"verses":[119],"verseLabel":"الشعراء: 119","question":"لماذا دعا نوح ﴿رَبِّ إِنَّ قَوْمِي كَذَّبُونِ * فَافْتَحْ بَيْنِي وَبَيْنَهُمْ فَتْحًا﴾؟","answer":"عرض الجريمة بلا طلب انتقام شخصي، وسأل حكمًا يفصل الحق بعد استنفاد الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص118–133.","url":""}]},{"id":"s26-71","number":71,"surah":26,"verses":[128,129],"verseLabel":"الشعراء: 128-129","question":"ما سرّ إنكار هود بناء آية بكل ريع واتخاذ مصانع بقوله ﴿لَعَلَّكُمْ تَخْلُدُونَ﴾؟","answer":"فُسرت ﴿المصانع﴾ بالقصور المشيدة أو الأبنية والحصون ومجاري الماء؛ والإنكار متوجه إلى العبث والتفاخر والتعلق بالبقاء كأنهم يخلدون، فلا يحصر اللفظ في نوع بناء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص153–168.","url":""}]},{"id":"s26-72","number":72,"surah":26,"verses":[130],"verseLabel":"الشعراء: 130","question":"ما سرّ التعبير الشرطي بـ﴿وَإِذَا بَطَشْتُمْ بَطَشْتُمْ جَبَّارِينَ﴾؟","answer":"«إذا» تفيد تحقق عادتهم، وتكرار الفعل يكشف أن القوة عندهم لا تعمل إلا بطشًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص153–168.","url":""}]},{"id":"s26-73","number":73,"surah":26,"verses":[146,147,148],"verseLabel":"الشعراء: 146-148","question":"لماذا سأل صالح: أتتركون في النعيم آمنين ثم عدد الجنات والعيون والزروع؟","answer":"فصل عناصر الرفاه ليوقظ شعورهم بهشاشة الأمن إن استعملت النعمة في التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص226–246.","url":""}]},{"id":"s26-74","number":74,"surah":26,"verses":[149],"verseLabel":"الشعراء: 149","question":"ما دلالة وصفهم في قوله ﴿وَتَنْحِتُونَ مِنَ الْجِبَالِ بُيُوتًا فَارِهِينَ﴾؟","answer":"في ﴿فارهين﴾ قراءات ومعانٍ، منها الحذق والنشاط والقوة، ومنها الأشر والبطر؛ والسياق يذم تحول القدرة على النحت إلى اغترار، فلا يعتمد معنى منفرد بلا تقييد.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص226–246.","url":""}]},{"id":"s26-75","number":75,"surah":26,"verses":[152],"verseLabel":"الشعراء: 152","question":"ما سرّ وصف المفسدين بأنهم ﴿يُفْسِدُونَ فِي الْأَرْضِ وَلَا يُصْلِحُونَ﴾؟","answer":"نفي الإصلاح يمنع توهم أن بعض نشاطهم العمراني يعوض فسادهم الأخلاقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص247–261.","url":""}]},{"id":"s26-76","number":76,"surah":26,"verses":[154],"verseLabel":"الشعراء: 154","question":"ما سرّ التعبير في قولهم لصالح ﴿مَا أَنْتَ إِلَّا بَشَرٌ مِثْلُنَا﴾ بالقصر؟","answer":"حصروا هويته في البشرية ليُسقطوا الرسالة، مع أن المماثلة البشرية هي موضع القدوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص262–276.","url":""}]},{"id":"s26-77","number":77,"surah":26,"verses":[160],"verseLabel":"الشعراء: 160","question":"ما سرّ التعبير بـ﴿كَذَّبَتْ قَوْمُ لُوطٍ الْمُرْسَلِينَ﴾ ولم يذكر اسم المدينة؟","answer":"ركز على الجماعة المسؤولة عن الاختيار، وربط تكذيب لوط بتكذيب جميع الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص307–320.","url":""}]},{"id":"s26-78","number":78,"surah":26,"verses":[165],"verseLabel":"الشعراء: 165","question":"ما سرّ التعبير بـ﴿أَتَأْتُونَ الذُّكْرَانَ مِنَ الْعَالَمِينَ﴾؟","answer":"«الذكران» وجمعه يبرز قلب الفطرة، و«من العالمين» يزيد التعجيب من تخصيص الرجال بالشهوة المحرمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص321–339.","url":""}]},{"id":"s26-79","number":79,"surah":26,"verses":[168],"verseLabel":"الشعراء: 168","question":"ما سرّ اختيار ﴿الْقَالِينَ﴾ في قول لوط ﴿إِنِّي لِعَمَلِكُمْ مِنَ الْقَالِينَ﴾؟","answer":"﴿القَالِين﴾ من القِلى، وهو البغض الشديد؛ وإدخال نفسه في جماعة القالين يقرر أن بغض هذا العمل موقف ثابت تشترك فيه الفطر السليمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص340–352.","url":""}]},{"id":"s26-80","number":80,"surah":26,"verses":[169],"verseLabel":"الشعراء: 169","question":"لماذا دعا ﴿رَبِّ نَجِّنِي وَأَهْلِي مِمَّا يَعْمَلُونَ﴾ لا «احفظني»؟","answer":"النجاة تتضمن إخراجه سالمًا من محيط نزل به الهلاك، وهو أخص من الحفظ العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص340–352.","url":""}]},{"id":"s26-81","number":81,"surah":26,"verses":[171],"verseLabel":"الشعراء: 171","question":"ما معنى كون العجوز ﴿فِي الْغَابِرِينَ﴾؟","answer":"﴿الغابرين﴾ الباقون؛ أي بقيت العجوز مع من بقي للهلاك ولم تدخل في الناجين، ولا يحتاج اللفظ إلى زيادة غير مسندة عن كيفية اختيارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص353–365.","url":""}]},{"id":"s26-82","number":82,"surah":26,"verses":[176],"verseLabel":"الشعراء: 176","question":"ما سرّ نسبة شعيب إلى أصحاب الأيكة دون وصفه بـ﴿أَخُوهُمْ﴾؟","answer":"لم يقل ﴿أخوهم شعيب﴾ لأن النسبة هنا إلى أصحاب الأيكة، وذُكر في ذلك أن شعيبًا أخو مدين لا الأيكة؛ والتعليل مقيد بهذا الوجه التفسيري ولا يجزم به خارج الخلاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص374–387.","url":""}]},{"id":"s26-83","number":83,"surah":26,"verses":[181,182,183],"verseLabel":"الشعراء: 181-183","question":"لماذا جمع شعيب بين إيفاء الكيل والوزن بالقسط وعدم بخس الناس؟","answer":"انتقل من سلامة أداة القياس إلى سلامة حقوق الناس عمومًا؛ فلا يكفي ميزان صحيح مع غش بوجه آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص388–401.","url":""}]},{"id":"s26-84","number":84,"surah":26,"verses":[187],"verseLabel":"الشعراء: 187","question":"لماذا طلبوا ﴿كِسَفًا مِنَ السَّمَاءِ﴾؟","answer":"بلغ استهزاؤهم أن طلبوا قطعة عذاب تسقط عليهم بدل أن يسألوا آية هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص420–426.","url":""}]},{"id":"s26-85","number":85,"surah":26,"verses":[197],"verseLabel":"الشعراء: 197","question":"لماذا كانت معرفة علماء بني إسرائيل بالقرآن آية لقريش؟","answer":"شهادة أهل العلم بصفات الوحي والرسول حجة خارج بيئة النبي الأمي.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص464–468.","url":""}]},{"id":"s26-86","number":86,"surah":26,"verses":[198,199],"verseLabel":"الشعراء: 198-199","question":"لماذا لو نزل القرآن على بعض الأعجمين فقرأه عليهم ما كانوا به مؤمنين؟","answer":"المشكلة ليست فصاحة المبلّغ ولا نسبه؛ العناد قادر على رد الآية في أي صورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص469–473.","url":""}]},{"id":"s26-87","number":87,"surah":26,"verses":[200],"verseLabel":"الشعراء: 200","question":"ما أوجه معنى الضمير في قوله ﴿كَذَلِكَ سَلَكْنَاهُ فِي قُلُوبِ الْمُجْرِمِينَ﴾؟","answer":"في الضمير أقوال: قيل المراد سلك القرآن في قلوبهم مع عدم انتفاعهم به، وقيل سلك التكذيب؛ لذلك لا يحصر الجواب في أحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص474–485.","url":""}]},{"id":"s26-88","number":88,"surah":26,"verses":[205,206,207],"verseLabel":"الشعراء: 205-207","question":"لماذا سأل: أرأيت إن متعناهم سنين ثم جاءهم ما يوعدون؟","answer":"يطوي سنين المتاع أمام لحظة العذاب؛ فما يغني طول اللذة إذا انتهت إلى الهلاك؟","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص486–498.","url":""}]},{"id":"s26-89","number":89,"surah":26,"verses":[208,209],"verseLabel":"الشعراء: 208-209","question":"ما سرّ التعبير بـ﴿وَمَا أَهْلَكْنَا مِنْ قَرْيَةٍ إِلَّا لَهَا مُنْذِرُونَ﴾؟","answer":"جعل الإنذار سنة سابقة للهلاك، ونفى الظلم لأن الحجة تصل قبل العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص499–510.","url":""}]},{"id":"s26-90","number":90,"surah":26,"verses":[210,211,212],"verseLabel":"الشعراء: 210-212","question":"لماذا نفى أن تتنزل الشياطين بالقرآن؟","answer":"أبطل التهمة من ثلاث جهات: لا يليق بهم، ولا يقدرون عليه، وهم معزولون عن سماع الملأ الأعلى.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص511–520.","url":""}]},{"id":"s26-91","number":91,"surah":26,"verses":[214],"verseLabel":"الشعراء: 214","question":"لماذا بدأ الإنذار بـ﴿عَشِيرَتَكَ الْأَقْرَبِينَ﴾؟","answer":"الأقرب أعرف بصدقه وأولى بالنصيحة، ونجاتهم لا تقوم على القرابة بلا إيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص521–536.","url":""}]},{"id":"s26-92","number":92,"surah":26,"verses":[215],"verseLabel":"الشعراء: 215","question":"ما سرّ التعبير بـ﴿وَاخْفِضْ جَنَاحَكَ لِمَنِ اتَّبَعَكَ﴾؟","answer":"استعار جناح الطائر للرعاية واللين؛ فالقائد يحوط المؤمنين بدل التعالي عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص521–536.","url":""}]},{"id":"s26-93","number":93,"surah":26,"verses":[218,219],"verseLabel":"الشعراء: 218-219","question":"ما أوجه معنى ﴿وَتَقَلُّبَكَ فِي السَّاجِدِينَ﴾؟","answer":"ذُكرت أوجه، منها أن الله يرى قيام الرسول في الصلاة وتقلبه في السجود، ومنها تقلبه في جماعة المصلين؛ فلا يقتصر اللفظ على حركة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص537–545.","url":""}]},{"id":"s26-94","number":94,"surah":26,"verses":[221,222,223],"verseLabel":"الشعراء: 221-223","question":"ما سرّ التعبير بأن الشياطين تنزل على كل أفاك أثيم، يلقون السمع وأكثرهم كاذبون؟","answer":"رسم صفات مستقبلي الوحي الشيطاني وعادته؛ وهي نقيض أمانة الرسول وصدق القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص546–557.","url":""}]},{"id":"s26-95","number":95,"surah":26,"verses":[224,225,226],"verseLabel":"الشعراء: 224-226","question":"ما سرّ ذم الشعراء في قوله ﴿وَالشُّعَرَاءُ يَتَّبِعُهُمُ الْغَاوُونَ﴾ مع بلاغة السورة؟","answer":"الذم متعلق بالشعر الذي يتبعه الغاوون ويهيم أصحابه في كل واد ويقولون ما لا يفعلون، لا بأصل البيان والشعر؛ ولذلك استثنت الآية التالية شعراء الإيمان والعمل والذكر والانتصار من الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص558–576.","url":""}]},{"id":"s26-96","number":96,"surah":26,"verses":[227],"verseLabel":"الشعراء: 227","question":"ما سرّ ختم السورة بـ﴿وَسَيَعْلَمُ الَّذِينَ ظَلَمُوا أَيَّ مُنْقَلَبٍ يَنْقَلِبُونَ﴾؟","answer":"أبهم ﴿أي منقلب﴾ للتهويل، وجاء فعل ﴿ينقلبون﴾ من مادة الاسم نفسه لتوكيد حتمية المصير؛ فخُتمت السورة بوعيد يجمع الظالمين بعد عرض مصارع المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص558–576.","url":""}]},{"id":"s27-1","number":1,"surah":27,"verses":[1],"verseLabel":"النمل: 1","question":"ما سرّ الجمع بين ﴿الْقُرْآنِ﴾ و﴿كِتَابٍ مُبِينٍ﴾؟","answer":"جمع بين الاسمين لأن القرآن هو الكتاب نفسه: وُصف من جهة تلاوته وقراءته، ومن جهة كتابته وجمعه، مع وصفه بالإبانة والوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص587–591.","url":""}]},{"id":"s27-2","number":2,"surah":27,"verses":[2],"verseLabel":"النمل: 2","question":"ما سرّ التعبير بـ﴿هُدًى وَبُشْرَى لِلْمُؤْمِنِينَ﴾؟","answer":"القرآن يهدي إلى الطريق، ثم يبشر من سلكه؛ فرتب الدلالة قبل الثمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص592–601.","url":""}]},{"id":"s27-3","number":3,"surah":27,"verses":[3],"verseLabel":"النمل: 3","question":"لماذا جمع إقامة الصلاة وإيتاء الزكاة واليقين بالآخرة؟","answer":"جمع صلة الخالق وإصلاح المجتمع والباعث الذي يضمن دوامهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص592–601.","url":""}]},{"id":"s27-4","number":4,"surah":27,"verses":[4],"verseLabel":"النمل: 4","question":"ما معنى إسناد التزيين إلى الله في قوله ﴿زَيَّنَّا لَهُمْ أَعْمَالَهُمْ فَهُمْ يَعْمَهُونَ﴾؟","answer":"التزيين جزاء على اختيارهم الكفر بالآخرة وإصرارهم عليه؛ فخُلّوا وما استحسنته نفوسهم حتى صاروا يعمهون، ولا يحمل اللفظ على إجبار سابق ينفي مسؤوليتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص602–612.","url":""}]},{"id":"s27-5","number":5,"surah":27,"verses":[6],"verseLabel":"النمل: 6","question":"ما سرّ اختيار ﴿لَتُلَقَّى الْقُرْآنَ﴾ بدل «لتأخذ القرآن»؟","answer":"التلقي استقبال بعناية واستعداد، والبناء للمجهول يعظم الواهب الذي وصف بالحكمة والعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص613–618.","url":""}]},{"id":"s27-6","number":6,"surah":27,"verses":[7],"verseLabel":"النمل: 7","question":"ما سرّ اختلاف قول موسى عند النار بين النمل وطه والقصص؟","answer":"في النمل قُدم الخبر وجيء بالجزم ﴿سآتيكم﴾، وفي طه ذُكر القبس أو الهدى، وفي القصص الخبر أو الجذوة مع الترجي؛ وقد ربط مبحث النمل الجزم بقوة التلقي، وربط الترجي في طه والقصص بسياق السير والتعب، ولكل موضع قدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص619–639؛ وج31، ص667–684؛ وج41، ص81–96.","url":""}]},{"id":"s27-7","number":7,"surah":27,"verses":[7],"verseLabel":"النمل: 7","question":"ما سرّ الجزم بـ﴿سَآتِيكُمْ﴾ في النمل، والترجي بـ﴿لَعَلِّي آتِيكُمْ﴾ في القصص؟","answer":"﴿سآتيكم﴾ أقوى في تثبيت الخبر مستقبلًا، وناسبها في النمل سبق الحديث عن قوة تلقي القرآن؛ أما ﴿لعلي﴾ في القصص فترجٍّ لا يَعِد بما ليس مستيقنًا، وقد فُتح الموضعان مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص619–639؛ وج41، ص81–96.","url":""}]},{"id":"s27-8","number":8,"surah":27,"verses":[8],"verseLabel":"النمل: 8","question":"ما أوجه معنى ﴿بُورِكَ مَنْ فِي النَّارِ وَمَنْ حَوْلَهَا﴾؟","answer":"ذُكرت أقوال في ﴿من في النار﴾ و﴿من حولها﴾، فقيل البركة لموسى والملائكة في مكان النور، وقيل غير ذلك؛ والمقطوع به تنزيه الله في ختام الآية، فلا يحصر المبهم في تعيين واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص619–639.","url":""}]},{"id":"s27-9","number":9,"surah":27,"verses":[9],"verseLabel":"النمل: 9","question":"لماذا عرّف نفسه لموسى بقوله ﴿إِنَّهُ أَنَا اللَّهُ الْعَزِيزُ الْحَكِيمُ﴾؟","answer":"ثبت مصدر النداء، وجمع العزة التي تؤمنه من فرعون والحكمة التي تضبط رسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص619–639.","url":""}]},{"id":"s27-10","number":10,"surah":27,"verses":[10],"verseLabel":"النمل: 10","question":"ما سرّ تشبيه العصا بـ﴿جَانٌّ﴾ في النمل، ووصفها بـ﴿ثُعْبَانٌ مُبِينٌ﴾ في الشعراء؟","answer":"وصفها بالجان يبرز سرعة حركتها واضطرابها عند مفاجأة موسى، ووصفها بالثعبان المبين في مقام مواجهة السحرة يبرز عظم جرمها ووضوح حقيقتها؛ فالشيء واحد والوصفان لحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص640–663؛ وج38، ص438–459.","url":""}]},{"id":"s27-11","number":11,"surah":27,"verses":[10],"verseLabel":"النمل: 10","question":"ما سرّ التعبير بـ﴿وَلَّى مُدْبِرًا وَلَمْ يُعَقِّبْ﴾؟","answer":"جمع سرعة الفرار وعدم الالتفات ليصور خوف المفاجأة، ثم جاء النداء بالأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص640–663.","url":""}]},{"id":"s27-12","number":12,"surah":27,"verses":[11],"verseLabel":"النمل: 11","question":"ما أوجه الاستثناء في ﴿إِلَّا مَنْ ظَلَمَ ثُمَّ بَدَّلَ حُسْنًا بَعْدَ سُوءٍ﴾ بعد أمان المرسلين؟","answer":"في الاستثناء أقوال: قيل منقطع، أي لكن من ظلم ثم تاب فالله غفور رحيم؛ وقيل متصل بالنظر إلى ما يقع من غير المعصوم أو من ترك الأولى. لذلك لا يصح جعله تقريرًا واحدًا بلا خلاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص640–663.","url":""}]},{"id":"s27-13","number":13,"surah":27,"verses":[12],"verseLabel":"النمل: 12","question":"ما سرّ التعبير بـ﴿فِي تِسْعِ آيَاتٍ إِلَى فِرْعَوْنَ وَقَوْمِهِ﴾؟","answer":"جعل العصا واليد داخل منظومة آيات متكاملة، لا عرضًا منفردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص640–663.","url":""}]},{"id":"s27-14","number":14,"surah":27,"verses":[13],"verseLabel":"النمل: 13","question":"ما سرّ التعبير في قولهم عن الآيات المبصرة ﴿هَذَا سِحْرٌ مُبِينٌ﴾؟","answer":"قلبوا وصف الدليل: ما جاء ليبصرهم سموه سحرًا ظاهرًا؛ اعترافًا بوضوحه مع إنكاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص640–663.","url":""}]},{"id":"s27-15","number":15,"surah":27,"verses":[14],"verseLabel":"النمل: 14","question":"ما سرّ التعبير بـ﴿وَجَحَدُوا بِهَا وَاسْتَيْقَنَتْهَا أَنْفُسُهُمْ﴾؟","answer":"فصل بين حكم اللسان ويقين الداخل؛ فالتكذيب كان ظلمًا وعلوًا لا نقص دليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص664–675.","url":""}]},{"id":"s27-16","number":16,"surah":27,"verses":[15],"verseLabel":"النمل: 15","question":"ما سرّ اختيار داود وسليمان ﴿الْحَمْدُ لِلَّهِ﴾ دون «الشكر لله»؟","answer":"الحمد ثناء على كمال المحمود وصفاته ونعمه، وهو أعم متعلقًا من الشكر الذي يكون في مقابلة النعمة؛ فناسب مقام العلم والاصطفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص676–690.","url":""}]},{"id":"s27-17","number":17,"surah":27,"verses":[15],"verseLabel":"النمل: 15","question":"ما سرّ عطف حمد داود وسليمان بالواو بعد إيتائهما العلم؟","answer":"الواو لا تجعل الحمد مجرد نتيجة زمنية فورية لإيتاء العلم، بل تعطف خبرًا يدل على خُلُق ثابت وملازم لهما في مقابلة النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص676–690.","url":""}]},{"id":"s27-18","number":18,"surah":27,"verses":[16],"verseLabel":"النمل: 16","question":"ما سرّ التعبير في قول سليمان بـ﴿وَوَرِثَ سُلَيْمَانُ دَاوُودَ﴾ مع كثرة أبناء داود؟","answer":"المراد وراثة النبوة والملك والعلم المختص، لا مجرد المال الذي يشترك فيه الأبناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص691–700.","url":""}]},{"id":"s27-19","number":19,"surah":27,"verses":[16],"verseLabel":"النمل: 16","question":"ما سرّ التعبير بـ﴿عُلِّمْنَا مَنْطِقَ الطَّيْرِ﴾؟","answer":"سمى أصواتها منطقًا لأن الله كشف له دلالاتها المقصودة، لا لأنها ألفاظ بشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص691–700.","url":""}]},{"id":"s27-20","number":20,"surah":27,"verses":[17],"verseLabel":"النمل: 17","question":"ما سرّ اختيار ﴿وَحُشِرَ لِسُلَيْمَانَ جُنُودُهُ﴾ بدل «جُمعت»؟","answer":"الحشر جمع مع سوق وضبط، وهو أنسب بجيش متعدد من الجن والإنس والطير يحتاج أن يُكف أوله حتى يلحق آخره.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص701–709.","url":""}]},{"id":"s27-21","number":21,"surah":27,"verses":[17],"verseLabel":"النمل: 17","question":"ما سرّ التعبير بـ﴿فَهُمْ يُوزَعُونَ﴾؟","answer":"يوزعون أي يُكف أولهم حتى يلحق آخرهم؛ صورة لانضباط جيش عظيم لا يطغى بعضه على بعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص701–709.","url":""}]},{"id":"s27-22","number":22,"surah":27,"verses":[18],"verseLabel":"النمل: 18","question":"ما سرّ التعبير في قول النملة ﴿لَا يَحْطِمَنَّكُمْ سُلَيْمَانُ وَجُنُودُهُ وَهُمْ لَا يَشْعُرُونَ﴾؟","answer":"جمعت التحذير والعدل؛ نسبت الضرر المحتمل إلى عدم الشعور لا إلى ظلم سليمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص710–722.","url":""}]},{"id":"s27-23","number":23,"surah":27,"verses":[19],"verseLabel":"النمل: 19","question":"ما سرّ الجمع بين التبسم والضحك في ﴿فَتَبَسَّمَ ضَاحِكًا مِنْ قَوْلِهَا﴾؟","answer":"﴿ضاحكًا﴾ حال تبين أن التبسم كان عن سرور، وقيل هو مبالغة في التبسم لا قهقهة؛ فجمع اللفظان لطف الابتداء وظهور الفرح بفهم كلام النملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص723–739.","url":""}]},{"id":"s27-24","number":24,"surah":27,"verses":[19],"verseLabel":"النمل: 19","question":"لماذا دعا ﴿رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ﴾ عند سماع النملة؟","answer":"حوّل ظهور القدرة إلى افتقار للشكر والعمل الصالح، حتى لا تنقلب النعمة إعجابًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص723–739.","url":""}]},{"id":"s27-25","number":25,"surah":27,"verses":[20],"verseLabel":"النمل: 20","question":"ما سرّ التعبير بـ﴿وَتَفَقَّدَ الطَّيْرَ فَقَالَ مَا لِيَ لَا أَرَى الْهُدْهُدَ﴾؟","answer":"التفقد نظر مقصود في أحوال الرعية، وبدأ باحتمال قصور رؤيته قبل اتهام الهدهد بالغياب.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص740–747.","url":""}]},{"id":"s27-26","number":26,"surah":27,"verses":[21],"verseLabel":"النمل: 21","question":"لماذا خيّر بين العذاب الشديد والذبح ثم استثنى ﴿أَوْ لَيَأْتِيَنِّي بِسُلْطَانٍ مُبِينٍ﴾؟","answer":"جمع هيبة النظام وضمان حق الغائب في تقديم عذر بيّن قبل العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص748–754.","url":""}]},{"id":"s27-27","number":27,"surah":27,"verses":[22],"verseLabel":"النمل: 22","question":"ما سرّ التعبير في قول الهدهد بـ﴿أَحَطْتُ بِمَا لَمْ تُحِطْ بِهِ﴾ لنبي ملك؟","answer":"قرر أن سعة علم القائد لا تمنع أن يحمل أصغر جنوده معلومة غابت عنه؛ فالعلم موزع بحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص755–764.","url":""}]},{"id":"s27-28","number":28,"surah":27,"verses":[22],"verseLabel":"النمل: 22","question":"ما سرّ وصف خبر الهدهد بـ﴿نَبَإٍ يَقِينٍ﴾؟","answer":"النبأ خبر عظيم الشأن، ووصفه باليقين يعلن تثبت الهدهد من خبره قبل عرضه على الملك، فيقابل احتمال العقوبة بحجة واضحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص755–764.","url":""}]},{"id":"s27-29","number":29,"surah":27,"verses":[23],"verseLabel":"النمل: 23","question":"ما سرّ اختيار ﴿تَمْلِكُهُمْ﴾ بدل «تحكمهم»؟","answer":"الملك أوسع من مجرد الحكم؛ فهو يتضمن السلطان والتصرف، وناسبه تفصيل ما أوتيته الملكة وقومها من أسباب القوة والعرش العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص765–775.","url":""}]},{"id":"s27-30","number":30,"surah":27,"verses":[24],"verseLabel":"النمل: 24","question":"ما سرّ التعبير بـ﴿وَجَدْتُهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِنْ دُونِ اللَّهِ﴾؟","answer":"أخر موضع الإنكار حتى تم وصف قوتهم، ليكشف أن الحضارة لا تعوض فساد وجهة العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص776–787.","url":""}]},{"id":"s27-31","number":31,"surah":27,"verses":[25],"verseLabel":"النمل: 25","question":"ما سرّ التعبير بـ﴿أَلَّا يَسْجُدُوا لِلَّهِ الَّذِي يُخْرِجُ الْخَبْءَ﴾؟","answer":"قابل الشمس الظاهرة بمن يخرج المخبوء في السماوات والأرض ويعلم السر والعلن.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص788–799.","url":""}]},{"id":"s27-32","number":32,"surah":27,"verses":[25],"verseLabel":"النمل: 25","question":"ما سرّ اختلاف القراءة بين الخطاب في ﴿مَا تُخْفُونَ وَمَا تُعْلِنُونَ﴾ والغيبة؟","answer":"قرأ الكسائي وحفص بالخطاب، وقرأ الباقون بالغيبة؛ والخطاب يواجه الحاضرين بما يخفون ويعلنون، والغيبة تحكي علم الله بحالهم، والكلام على القراءتين من قول الهدهد على الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص788–799.","url":""}]},{"id":"s27-33","number":33,"surah":27,"verses":[27],"verseLabel":"النمل: 27","question":"ما سرّ التعبير في قول سليمان ﴿سَنَنْظُرُ أَصَدَقْتَ أَمْ كُنْتَ مِنَ الْكَاذِبِينَ﴾ بعد خبر الهدهد؟","answer":"لم يجزم بصدق الخبر مع تأكيد الهدهد له، بل أعلن النظر والاختبار؛ فالتثبت يميز الصادق من الكاذب قبل بناء القرار على الخبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص14–19.","url":""}]},{"id":"s27-34","number":34,"surah":27,"verses":[28],"verseLabel":"النمل: 28","question":"ما سرّ التعبير بـ﴿فَأَلْقِهْ إِلَيْهِمْ ثُمَّ تَوَلَّ عَنْهُمْ فَانْظُرْ مَاذَا يَرْجِعُونَ﴾؟","answer":"أمره بإلقاء الكتاب ثم التنحي، ليترقب من غير أن يشعروا به ما يردونه وما يتشاورون فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص20–27.","url":""}]},{"id":"s27-35","number":35,"surah":27,"verses":[29],"verseLabel":"النمل: 29","question":"ما سرّ وصف ملكة سبأ الكتاب بأنه ﴿كِتَابٌ كَرِيمٌ﴾؟","answer":"ذكرت الموسوعة وجوهًا لوصفه بالكريم: كونه مختومًا، أو صادرًا من ملك، أو حسن المضمون والأسلوب، أو غريب طريق الوصول؛ فلا يحصر الوصف في سبب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص28–32.","url":""}]},{"id":"s27-36","number":36,"surah":27,"verses":[30],"verseLabel":"النمل: 30","question":"ما سرّ افتتاح كتاب سليمان بـ﴿بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ﴾؟","answer":"عرّف الدعوة من أولها بأنها باسم الله لا باسم الملك، وبالرحمة قبل الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص33–40.","url":""}]},{"id":"s27-37","number":37,"surah":27,"verses":[31],"verseLabel":"النمل: 31","question":"ما سرّ الجمع بين ﴿أَلَّا تَعْلُوا عَلَيَّ﴾ و﴿وَأْتُونِي مُسْلِمِينَ﴾؟","answer":"نهى عن الاستعلاء الذي يمنع قبول الحق، ثم أمرهم أن يأتوه منقادين؛ فجمع إزالة المانع وإظهار أثر الانقياد.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص33–40.","url":""}]},{"id":"s27-38","number":38,"surah":27,"verses":[32],"verseLabel":"النمل: 32","question":"ما سرّ التعبير في قول ملكة سبأ ﴿مَا كُنْتُ قَاطِعَةً أَمْرًا حَتَّى تَشْهَدُونِ﴾؟","answer":"أثبتت الشورى سياسة مستقرة، مع أنها صاحبة القرار النهائي.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص41–48.","url":""}]},{"id":"s27-39","number":39,"surah":27,"verses":[34],"verseLabel":"النمل: 34","question":"ما سرّ التعبير في قولها ﴿إِنَّ الْمُلُوكَ إِذَا دَخَلُوا قَرْيَةً أَفْسَدُوهَا﴾؟","answer":"قاسَت رسالة سليمان على عادة الملوك في الغزو؛ فلم تدرك بعد أنها دعوة نبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص55–61.","url":""}]},{"id":"s27-40","number":40,"surah":27,"verses":[35],"verseLabel":"النمل: 35","question":"لماذا اختبرت سليمان بهدية؟","answer":"كانت الهدية اختبارًا: أهو ملك يقبل المال فيصرفه عن طلبه، أم نبي لا يساوم على الدعوة إلى الله؟","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص62–67.","url":""}]},{"id":"s27-41","number":41,"surah":27,"verses":[36],"verseLabel":"النمل: 36","question":"ما سرّ إظهار اسم ﴿سُلَيْمَانَ﴾ في قوله ﴿فَلَمَّا جَاءَ سُلَيْمَانَ﴾؟","answer":"أعاد الاسم عند انتقال المشهد من الملكة إلى مجلسه، وثبت أن الرد صادر من مقام النبوة والملك.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص68–83.","url":""}]},{"id":"s27-42","number":42,"surah":27,"verses":[36],"verseLabel":"النمل: 36","question":"ما سرّ التعبير بـ﴿أَتُمِدُّونَنِ بِمَالٍ﴾ بدل «بهدية»؟","answer":"سماها مالًا لكشف حقيقتها المادية في مقام لا يغيره المال، ثم قابلها بما آتاه الله من فضل خير مما أوتوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص68–83.","url":""}]},{"id":"s27-43","number":43,"surah":27,"verses":[36],"verseLabel":"النمل: 36","question":"ما سرّ التعبير بـ﴿بَلْ أَنْتُمْ بِهَدِيَّتِكُمْ تَفْرَحُونَ﴾؟","answer":"رد الفرح بها إلى مقاييسهم المادية؛ أما ما آتاه الله فخير مما يملكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص68–83.","url":""}]},{"id":"s27-44","number":44,"surah":27,"verses":[37],"verseLabel":"النمل: 37","question":"ما سرّ تعدية ﴿ارْجِعْ﴾ بـ﴿إِلَيْهِمْ﴾؟","answer":"«إلى» تصور عودة الرسول إلى جهتهم حاملًا الرد والإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص68–83.","url":""}]},{"id":"s27-45","number":45,"surah":27,"verses":[37],"verseLabel":"النمل: 37","question":"ما سرّ الجمع بين ﴿وَلَنُخْرِجَنَّهُمْ مِنْهَا أَذِلَّةً﴾ و﴿وَهُمْ صَاغِرُونَ﴾؟","answer":"جمع الإخراج الحسي والذلة النفسية؛ فالوعيد يزيل سلطانهم وكبرياءهم معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص68–83.","url":""}]},{"id":"s27-46","number":46,"surah":27,"verses":[38],"verseLabel":"النمل: 38","question":"لماذا طلب سليمان عرشها قبل أن يأتوه مسلمين؟","answer":"أراد إقامة آية تسبق وصولها وتختبر عقلها، لا الاستيلاء على متاعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص84–108.","url":""}]},{"id":"s27-47","number":47,"surah":27,"verses":[39],"verseLabel":"النمل: 39","question":"ما سرّ التعبير بـ﴿قَبْلَ أَنْ تَقُومَ مِنْ مَقَامِكَ﴾ بدل «من مجلسك»؟","answer":"المقام يشمل مدة جلوسه المعهود للحكم، فيحدد زمنًا مفهومًا في نظام الملك.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص84–108.","url":""}]},{"id":"s27-48","number":48,"surah":27,"verses":[40],"verseLabel":"النمل: 40","question":"ما سرّ التعبير بـ﴿قَبْلَ أَنْ يَرْتَدَّ إِلَيْكَ طَرْفُكَ﴾؟","answer":"جعل الزمن أقصر من رجوع البصر بعد امتداده؛ ففاق عرض القوة بعلم موهوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص84–108.","url":""}]},{"id":"s27-49","number":49,"surah":27,"verses":[40],"verseLabel":"النمل: 40","question":"ما سرّ قول سليمان عند رؤية العرش ﴿هَذَا مِنْ فَضْلِ رَبِّي﴾؟","answer":"نسب الخارق إلى فضل الله فورًا، ثم رآه اختبار شكر لا دليل تفوق ذاتي.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص84–108.","url":""}]},{"id":"s27-50","number":50,"surah":27,"verses":[41],"verseLabel":"النمل: 41","question":"ما سرّ التعبير بـ﴿نَكِّرُوا لَهَا عَرْشَهَا نَنْظُرْ أَتَهْتَدِي﴾؟","answer":"غيّر بعض علاماته ليختبر دقة معرفتها ومرونتها أمام أمر يخالف المألوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص109–129.","url":""}]},{"id":"s27-51","number":51,"surah":27,"verses":[42],"verseLabel":"النمل: 42","question":"ما سرّ قول ملكة سبأ ﴿كَأَنَّهُ هُوَ﴾ دون جزم؟","answer":"جمعت قوة الشبه واستبعاد انتقاله، فكان جوابها احترازًا ذكيًا لا إنكارًا ولا تهورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص109–129.","url":""}]},{"id":"s27-52","number":52,"surah":27,"verses":[44],"verseLabel":"النمل: 44","question":"ما سرّ حسبان ملكة سبأ الصرح لجة وكشفها عن ساقيها؟","answer":"كان الصرح ممردًا من قوارير شديدة الصفاء فوق الماء، فحسبته لجة وكشفت عن ساقيها امتثالًا للدخول؛ ثم بين لها سليمان حقيقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص109–129.","url":""}]},{"id":"s27-53","number":53,"surah":27,"verses":[44],"verseLabel":"النمل: 44","question":"ما سرّ التعبير بـ﴿أَسْلَمْتُ مَعَ سُلَيْمَانَ لِلَّهِ﴾؟","answer":"قالت ﴿مع سليمان﴾ لا «لسليمان»؛ فأعلنت مشاركته في الإسلام لله، لا الخضوع لشخصه، وقدمت الاعتراف بظلم النفس على التخلية من الباطل ثم التحلي بالتوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص109–129.","url":""}]},{"id":"s27-54","number":54,"surah":27,"verses":[45],"verseLabel":"النمل: 45","question":"لماذا خصت النمل ثمود بقصة صالح بعد سليمان؟","answer":"انتقلت من أمة قبلت الآية بالعقل إلى أمة انقسمت فيها الخصومة رغم قرب الدليل؛ فتقابل الموقفان.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص130–144.","url":""}]},{"id":"s27-55","number":55,"surah":27,"verses":[46],"verseLabel":"النمل: 46","question":"ما سرّ التعبير في قول صالح بـ﴿لِمَ تَسْتَعْجِلُونَ بِالسَّيِّئَةِ قَبْلَ الْحَسَنَةِ﴾؟","answer":"سموا تحدي العذاب قوة، فقلب ترتيبهم: الأولى طلب الرحمة بالتوبة لا الشر بالاستهزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص145–158.","url":""}]},{"id":"s27-56","number":56,"surah":27,"verses":[47],"verseLabel":"النمل: 47","question":"ما سرّ التعبير في قولهم بـ﴿اطَّيَّرْنَا بِكَ وَبِمَنْ مَعَكَ﴾؟","answer":"نسبوا الشؤم إلى المصلحين بدل أعمالهم، فرد عليهم ﴿طائركم عند الله﴾ أي سبب مصيركم وحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص159–169.","url":""}]},{"id":"s27-57","number":57,"surah":27,"verses":[48],"verseLabel":"النمل: 48","question":"ما سرّ وصف الرهط التسعة بأنهم ﴿يُفْسِدُونَ فِي الْأَرْضِ وَلَا يُصْلِحُونَ﴾؟","answer":"نفى عنهم أي وجه إصلاح حتى لا تُلبس مؤامرتهم ثوب المصلحة العامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص170–178.","url":""}]},{"id":"s27-58","number":58,"surah":27,"verses":[49],"verseLabel":"النمل: 49","question":"ما سرّ استعمال المتآمرين القسم بالله في ﴿تَقَاسَمُوا بِاللَّهِ﴾؟","answer":"استعملوا اسم الله لتوثيق جريمة ضد نبيه؛ مفارقة تكشف فساد التدين حين ينفصل عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص179–195.","url":""}]},{"id":"s27-59","number":59,"surah":27,"verses":[51],"verseLabel":"النمل: 51","question":"ما سرّ التعبير بـ﴿فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ مَكْرِهِمْ﴾؟","answer":"طلب النظر في انقلاب التدبير على أصحابه: أرادوا إهلاكه فأهلكوا هم وقومهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص204–213.","url":""}]},{"id":"s27-60","number":60,"surah":27,"verses":[52],"verseLabel":"النمل: 52","question":"ما سرّ التعبير بـ﴿فَتِلْكَ بُيُوتُهُمْ خَاوِيَةً بِمَا ظَلَمُوا﴾؟","answer":"أشار إلى آثار قريبة مشاهدة، وجعل فراغ البيوت شاهدًا صامتًا على سبب الخراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص214–224.","url":""}]},{"id":"s27-61","number":61,"surah":27,"verses":[54],"verseLabel":"النمل: 54","question":"ما سرّ التعبير في قول لوط بـ﴿أَتَأْتُونَ الْفَاحِشَةَ وَأَنْتُمْ تُبْصِرُونَ﴾؟","answer":"زاد قبح الفعل بأنه يقع مع معرفة وبصيرة، لا عن جهل أو التباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص230–239.","url":""}]},{"id":"s27-62","number":62,"surah":27,"verses":[55],"verseLabel":"النمل: 55","question":"ما سرّ التعبير بـ﴿بَلْ أَنْتُمْ قَوْمٌ تَجْهَلُونَ﴾ مع أنهم يبصرون؟","answer":"أثبت علم الحس ونفى عمل العقل؛ فهم يعرفون الفعل ويجهلون قدره وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص240–248.","url":""}]},{"id":"s27-63","number":63,"surah":27,"verses":[59],"verseLabel":"النمل: 59","question":"ما سرّ الانتقال بعد القصص إلى ﴿قُلِ الْحَمْدُ لِلَّهِ وَسَلَامٌ عَلَى عِبَادِهِ الَّذِينَ اصْطَفَى﴾؟","answer":"حمد على نجاة الرسل، وسلم عليهم، ثم فتح محاجة التوحيد بسؤال ﴿آلله خير أم ما يشركون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص269–300.","url":""}]},{"id":"s27-64","number":64,"surah":27,"verses":[60],"verseLabel":"النمل: 60","question":"ما سرّ تكرار سؤال ﴿أَإِلَهٌ مَعَ اللَّهِ﴾ في براهين التوحيد؟","answer":"بعد كل نعمة كبرى يعيد السؤال لازمها العقلي، فتتراكم الحجة ولا يبقى للشريك عمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص269–300.","url":""}]},{"id":"s27-65","number":65,"surah":27,"verses":[61],"verseLabel":"النمل: 61","question":"ما سرّ التعبير عن الأرض بـ﴿قَرَارًا﴾ وعن الجبال بـ﴿رَوَاسِيَ﴾؟","answer":"الأرض مستقرة للعيش، والجبال مثبتة راسخة؛ جمع الأثر ووسيلته في صورة السكن.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص269–300.","url":""}]},{"id":"s27-66","number":66,"surah":27,"verses":[62],"verseLabel":"النمل: 62","question":"ما سرّ التعبير بـ﴿أَمَّنْ يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ﴾؟","answer":"اختار لحظة سقوط الأسباب كلها، حيث تشهد الفطرة بأن كشف السوء ليس للصنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص301–323.","url":""}]},{"id":"s27-67","number":67,"surah":27,"verses":[64],"verseLabel":"النمل: 64","question":"ما سرّ ختم براهين التوحيد بـ﴿قُلْ هَاتُوا بُرْهَانَكُمْ إِنْ كُنْتُمْ صَادِقِينَ﴾؟","answer":"بعد عرض أفعال الخالق نقل عبء الإثبات إلى مدعي الشريك؛ والدعوى بلا برهان ساقطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص324–338.","url":""}]},{"id":"s27-68","number":68,"surah":27,"verses":[65],"verseLabel":"النمل: 65","question":"ما سرّ التعبير بـ﴿لَا يَعْلَمُ مَنْ فِي السَّمَاوَاتِ وَالْأَرْضِ الْغَيْبَ إِلَّا اللَّهُ﴾؟","answer":"نفى علم الغيب عن جميع العوالم ثم استثنى الله وحده، فبطل تعلقهم بالكهنة والمعبودات.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص339–349.","url":""}]},{"id":"s27-69","number":69,"surah":27,"verses":[66],"verseLabel":"النمل: 66","question":"ما سرّ التدرج في ﴿ادَّارَكَ عِلْمُهُمْ... بَلْ هُمْ فِي شَكٍّ... بَلْ هُمْ مِنْهَا عَمُونَ﴾؟","answer":"انتقل من قصور العلم إلى اضطرابه ثم العمى التام؛ كل «بل» تكشف طبقة أعمق من الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص350–359.","url":""}]},{"id":"s27-70","number":70,"surah":27,"verses":[69],"verseLabel":"النمل: 69","question":"ما سرّ التعبير في النمل بـ﴿قُلْ سِيرُوا... فَانْظُرُوا﴾، وفي الأنعام بـ﴿ثُمَّ انْظُرُوا﴾؟","answer":"الفاء تفيد ترتيب النظر على بدء السير وتعقيبه به، أما ﴿ثم﴾ في الأنعام فتراعي تمام السير والتراخي، وناسبت كذلك سياق الأنعام المفصل في الحجج؛ وقد عرض مبحث النمل اللفظين والموضعين معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص374–383.","url":""}]},{"id":"s27-71","number":71,"surah":27,"verses":[70],"verseLabel":"النمل: 70","question":"ما سرّ الجمع في خطاب النبي بين ﴿وَلَا تَحْزَنْ عَلَيْهِمْ﴾ و﴿وَلَا تَكُنْ فِي ضَيْقٍ مِمَّا يَمْكُرُونَ﴾؟","answer":"نهاه عن ألم مصيرهم وعن انحصار النفس بسبب مكرهم؛ فالله محيط بالفعل والفاعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص384–395.","url":""}]},{"id":"s27-72","number":72,"surah":27,"verses":[71],"verseLabel":"النمل: 71","question":"ما سرّ التعبير بـ﴿هَذَا الْوَعْدُ﴾ في سؤال المكذبين؟","answer":"اسم الإشارة يستحضر الأمر الموعود به استهزاء، و﴿أل﴾ للعهد بوعد العذاب المعروف بينهم؛ واستعمال المصدر ﴿الوعد﴾ في معنى الموعود به يبالغ في إنكارهم أصل وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص396–402.","url":""}]},{"id":"s27-73","number":73,"surah":27,"verses":[72],"verseLabel":"النمل: 72","question":"ما سرّ التعبير بـ﴿عَسَى أَنْ يَكُونَ رَدِفَ لَكُمْ بَعْضُ الَّذِي تَسْتَعْجِلُونَ﴾؟","answer":"«ردف لكم» يصور العذاب قد لحق وراءهم وقاربهم، مع إبقاء وقته في علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص403–409.","url":""}]},{"id":"s27-74","number":74,"surah":27,"verses":[74],"verseLabel":"النمل: 74","question":"ما سرّ الجمع بين ﴿مَا تُكِنُّ صُدُورُهُمْ﴾ و﴿مَا يُعْلِنُونَ﴾؟","answer":"جمع المستور والمعلن ردًا على مكرهم الخفي وكلامهم الظاهر، فلا يفوت علمه شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص410–429.","url":""}]},{"id":"s27-75","number":75,"surah":27,"verses":[76],"verseLabel":"النمل: 76","question":"ما سرّ التعبير بـ﴿إِنَّ هَذَا الْقُرْآنَ يَقُصُّ عَلَى بَنِي إِسْرَائِيلَ أَكْثَرَ الَّذِي هُمْ فِيهِ يَخْتَلِفُونَ﴾؟","answer":"عرض تصحيح القرآن لاختلاف أهل الكتاب بوصفه شاهد علم وهدى، لا قصة لقريش وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص430–437.","url":""}]},{"id":"s27-76","number":76,"surah":27,"verses":[82],"verseLabel":"النمل: 82","question":"لماذا تخرج دابة من الأرض تكلم الناس؟","answer":"جعل خروج الدابة وكلامها من آيات اقتراب الوعيد حين يقع القول عليهم، ومضمون كلامها يواجه الناس بأنهم لم يكونوا بآيات الله يوقنون؛ ولا يعتمد ما لم يثبته المبحث من تفاصيل صفتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص470–479.","url":""}]},{"id":"s27-77","number":77,"surah":27,"verses":[83],"verseLabel":"النمل: 83","question":"ما سرّ تكرار ﴿فَهُمْ يُوزَعُونَ﴾ في جنود سليمان وفي حشر المكذبين؟","answer":"﴿يوزعون﴾ تعني كف أول الجمع حتى يلحق آخره؛ ففي جنود سليمان تصور انتظام الجيش، وفي حشر المكذبين تصور ضبط الأفواج وسوقها للحساب، وقد فُتح الموضعان.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص480–492؛ وج39، ص701–709.","url":""}]},{"id":"s27-78","number":78,"surah":27,"verses":[87],"verseLabel":"النمل: 87","question":"ما سرّ التعبير بـ﴿فَفَزِعَ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الْأَرْضِ إِلَّا مَنْ شَاءَ اللَّهُ﴾؟","answer":"عمم الفزع ليبين هول النفخة، واستثنى من يؤمنه الله ليبقى السلطان لمشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص508–517.","url":""}]},{"id":"s27-79","number":79,"surah":27,"verses":[88],"verseLabel":"النمل: 88","question":"ما سرّ الجمع يوم القيامة بين حسبان الجبال جامدة ومرورها مر السحاب؟","answer":"حسبانها جامدة وصف لما يبدو للناظر، ومرورها مر السحاب يكشف تحولها وسيرها يوم القيامة؛ فجمعت الآية بين ظاهر الثبات وحقيقة الحركة في ذلك المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص518–526.","url":""}]},{"id":"s27-80","number":80,"surah":27,"verses":[89],"verseLabel":"النمل: 89","question":"ما سرّ التعبير بـ﴿مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ خَيْرٌ مِنْهَا﴾؟","answer":"الجزاء ليس مساواة حسابية؛ فضل الله يجعل للحسنة ثوابًا خيرًا منها وأمنًا من الفزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص527–551.","url":""}]},{"id":"s27-81","number":81,"surah":27,"verses":[90],"verseLabel":"النمل: 90","question":"ما سرّ التعبير بـ﴿فَكُبَّتْ وُجُوهُهُمْ فِي النَّارِ﴾ بالبناء للمجهول؟","answer":"ركز على هول السقوط وذل الوجه دون حاجة لتسمية من ينفذ الحكم المعلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص527–551.","url":""}]},{"id":"s27-82","number":82,"surah":27,"verses":[91],"verseLabel":"النمل: 91","question":"ما سرّ التعبير في ختام السورة بـ﴿إِنَّمَا أُمِرْتُ أَنْ أَعْبُدَ رَبَّ هَذِهِ الْبَلْدَةِ﴾؟","answer":"في مكة مركز شركهم، أعلن عبادة مالكها الحقيقي الذي حرمها، لا الأصنام الموضوعة فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص552–588.","url":""}]},{"id":"s27-83","number":83,"surah":27,"verses":[92],"verseLabel":"النمل: 92","question":"ما سرّ اختيار ﴿وَأَنْ أَتْلُوَ الْقُرْآنَ﴾ بدل «الكتاب»؟","answer":"لأن المقام وظيفة الرسول في التلاوة والإسماع المستمر، فناسب اسم القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص552–588.","url":""}]},{"id":"s27-84","number":84,"surah":27,"verses":[93],"verseLabel":"النمل: 93","question":"ما سرّ ختم السورة بـ﴿سَيُرِيكُمْ آيَاتِهِ فَتَعْرِفُونَهَا﴾؟","answer":"وعد بأن تتحول الآيات المنذرة إلى وقائع يعرفون صدقها، ثم نفى الغفلة عن أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص552–588.","url":""}]},{"id":"s27-85","number":85,"surah":27,"verses":[52],"verseLabel":"النمل: 80؛ الروم: 52","question":"ما سرّ زيادة الفاء في ﴿فَإِنَّكَ لَا تُسْمِعُ الْمَوْتَى﴾ في الروم، وحذفها من نظيرها في النمل؟","answer":"الفاء في الروم رتبت نفي الإسماع على ما قبلها: إن استرسلوا في الكفر فهم كالموتى فلا تسمعهم؛ أما نظير النمل فجاء استئنافًا بلا هذا التفريع. وقد فُتح الموضعان مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص455–469؛ وج43، ص509–530.","url":""}]},{"id":"s28-1","number":1,"surah":28,"verses":[2],"verseLabel":"القصص: 2","question":"ما سرّ التعبير بـ﴿تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ﴾؟","answer":"الإشارة للبعيد تفخيم، و«المبين» يصف ما يكشف الحق في قصة لم يشهدها المخاطبون.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص598–609.","url":""}]},{"id":"s28-2","number":2,"surah":28,"verses":[3],"verseLabel":"القصص: 3","question":"ما سرّ التعبير بـ﴿نَتْلُوا عَلَيْكَ مِنْ نَبَإِ مُوسَى وَفِرْعَوْنَ بِالْحَقِّ لِقَوْمٍ يُؤْمِنُونَ﴾؟","answer":"«النبأ» خبر عظيم، و«من» تشير إلى اختيار مواضع العبرة، والمؤمنون هم المنتفعون وإن كان الخطاب للجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص598–609.","url":""}]},{"id":"s28-3","number":3,"surah":28,"verses":[4],"verseLabel":"القصص: 4","question":"ما سرّ إظهار اسم ﴿فِرْعَوْنَ﴾ بعد ذكره في الآية السابقة؟","answer":"بدأ تفصيل النبأ بتسمية رأس الطغيان لتتعلق به أفعال العلو والتفريق والقتل بلا التباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص610–627.","url":""}]},{"id":"s28-4","number":4,"surah":28,"verses":[4],"verseLabel":"القصص: 4","question":"ما سرّ التعبير بـ﴿جَعَلَ أَهْلَهَا شِيَعًا﴾؟","answer":"صور سياسة الاستبداد بتفريق المجتمع طوائف يستضعف بعضها ويستعين ببعضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص610–627.","url":""}]},{"id":"s28-5","number":5,"surah":28,"verses":[4],"verseLabel":"القصص: 4","question":"ما سرّ التعبير بالمضارع والتفعيل في ﴿يُذَبِّحُ أَبْنَاءَهُمْ وَيَسْتَحْيِي نِسَاءَهُمْ﴾؟","answer":"المضارع والتفعيل يصوران جريمة متكررة، و«يستحيي» إبقاء النساء أحياءً للاستعباد لا رحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص610–627.","url":""}]},{"id":"s28-6","number":6,"surah":28,"verses":[5,6],"verseLabel":"القصص: 5-6","question":"ما سرّ تتابع ﴿وَنُرِيدُ﴾ و﴿وَنَجْعَلَهُمْ﴾ و﴿وَنُمَكِّنَ﴾ و﴿وَنُرِيَ﴾ في مقابل فعل فرعون؟","answer":"تتابعت أفعال الإرادة والمن والجعل والتمكين والإراءة في مقابلة استضعاف فرعون وذبحه؛ فصورت تدبيرًا إلهيًا متدرجًا يقلب ما أراده الطاغية عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص628–636.","url":""}]},{"id":"s28-7","number":7,"surah":28,"verses":[7],"verseLabel":"القصص: 7","question":"لماذا أوحى الله إلى أم موسى أن ترضعه أولًا ثم تلقيه في اليم؟","answer":"أبقى الصلة والغذاء ما أمكن، ثم جعل الإلقاء عند الخوف تدبير نجاة لا تخلّيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص649–661.","url":""}]},{"id":"s28-8","number":8,"surah":28,"verses":[7],"verseLabel":"القصص: 7","question":"ما سرّ الجمع بين ﴿وَلَا تَخَافِي﴾ و﴿وَلَا تَحْزَنِي﴾؟","answer":"الخوف مما سيقع، والحزن على ما وقع من الفراق؛ فطمأنها من المستقبل والحاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص649–661.","url":""}]},{"id":"s28-9","number":9,"surah":28,"verses":[7],"verseLabel":"القصص: 7","question":"ما سرّ الجمع بين ﴿إِنَّا رَادُّوهُ إِلَيْكِ﴾ و﴿وَجَاعِلُوهُ مِنَ الْمُرْسَلِينَ﴾؟","answer":"جمع الوعد القريب الذي يسكن قلب الأم والوعد البعيد الذي يكشف أن الخطر نفسه طريق الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص649–661.","url":""}]},{"id":"s28-10","number":10,"surah":28,"verses":[8],"verseLabel":"القصص: 8","question":"ما سرّ اختيار ﴿فَالْتَقَطَهُ آلُ فِرْعَوْنَ﴾ بدل «أخذوه»؟","answer":"الالتقاط أخذ شيء مصادف من غير طلب؛ وهم لم يعلموا أنهم يربون من سيزيل ملكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص662–671.","url":""}]},{"id":"s28-11","number":11,"surah":28,"verses":[8],"verseLabel":"القصص: 8","question":"ما سرّ لام ﴿لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَنًا﴾؟","answer":"هي لام العاقبة: لم يقصدوا عداوته، لكن فعلهم آل إلى عكس ما أرادوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص662–671.","url":""}]},{"id":"s28-12","number":12,"surah":28,"verses":[9],"verseLabel":"القصص: 9","question":"ما سرّ تقديم امرأة فرعون نفسها في ﴿قُرَّتُ عَيْنٍ لِي وَلَكَ﴾؟","answer":"قدمت ﴿لي﴾ لأنها صاحبة القول وأول من استقر السرور في نفسها، ثم أشركت فرعون في رجاء قرة العين؛ وهذا وجه بلاغي لا دعوى تاريخية زائدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص672–682.","url":""}]},{"id":"s28-13","number":13,"surah":28,"verses":[9],"verseLabel":"القصص: 9","question":"ما سرّ التعبير بضمير الجمع في ﴿لَا تَقْتُلُوهُ﴾؟","answer":"خاطبت فرعون ومن ينفذ أمره، فقطعت القرار وسيلة التنفيذ معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص672–682.","url":""}]},{"id":"s28-14","number":14,"surah":28,"verses":[9],"verseLabel":"القصص: 9","question":"ما سرّ ختم الآية بـ﴿وَهُمْ لَا يَشْعُرُونَ﴾؟","answer":"كانوا يخططون لحفظ الملك وهم يحمون من سيكون سبب زواله؛ مفارقة تلخص خفاء التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص672–682.","url":""}]},{"id":"s28-15","number":15,"surah":28,"verses":[10],"verseLabel":"القصص: 10","question":"ما أوجه معنى ﴿فَارِغًا﴾ في وصف فؤاد أم موسى؟","answer":"ذكرت الموسوعة وجهين: خلو قلبها من الخوف والحزن ثقة بالوعد، أو خلوه من كل شاغل إلا التفكير في موسى، وهو الأظهر عندها؛ فلا يحصر اللفظ في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص683–701.","url":""}]},{"id":"s28-16","number":16,"surah":28,"verses":[10],"verseLabel":"القصص: 10","question":"ما سرّ تصوير تثبيت أم موسى بقوله ﴿لَوْلَا أَنْ رَبَطْنَا عَلَى قَلْبِهَا﴾؟","answer":"صور التثبيت برباط يشد القلب المتفلت تحت صدمة الفراق.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص683–701.","url":""}]},{"id":"s28-17","number":17,"surah":28,"verses":[11],"verseLabel":"القصص: 11","question":"ما سرّ اختيار أم موسى قولها لأخته ﴿قُصِّيهِ﴾؟","answer":"القص اتباع الأثر من بعيد؛ أمرتها بالمراقبة المتدرجة من غير أن تكشف صلتها به.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص683–701.","url":""}]},{"id":"s28-18","number":18,"surah":28,"verses":[11],"verseLabel":"القصص: 11","question":"ما سرّ التعبير بـ﴿فَبَصُرَتْ بِهِ عَنْ جُنُبٍ﴾؟","answer":"رأته من مكان بعيد أو بمظهر المتجانبة، فجمعت المراقبة وإخفاء الاهتمام.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص683–701.","url":""}]},{"id":"s28-19","number":19,"surah":28,"verses":[12],"verseLabel":"القصص: 12","question":"ما سرّ التعبير بـ﴿وَحَرَّمْنَا عَلَيْهِ الْمَرَاضِعَ مِنْ قَبْلُ﴾؟","answer":"امتناعه من ألبانهن تدبير سابق يعيده إلى أمه من داخل بيت فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص702–711.","url":""}]},{"id":"s28-20","number":20,"surah":28,"verses":[12],"verseLabel":"القصص: 12","question":"ما سرّ زيادة ﴿وَهُمْ لَهُ نَاصِحُونَ﴾ في القصص على نظيرها في طه؟","answer":"زاد موضع القصص ﴿وهم له ناصحون﴾ لأن سياقه مبسوط في عرض أهل بيت يكفلونه، فاحتاج إلى بيان أمانتهم وإخلاصهم له؛ أما طه فمقام امتنان موجز. وقد فُتح الموضعان.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص702–711؛ وج32، ص51–82.","url":""}]},{"id":"s28-21","number":21,"surah":28,"verses":[13],"verseLabel":"القصص: 13","question":"ما سرّ ترتيب ﴿كَيْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَلِتَعْلَمَ﴾؟","answer":"رتب سكون العاطفة ثم زوال الحزن ثم رسوخ المعرفة بأن وعد الله حق.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص712–721.","url":""}]},{"id":"s28-22","number":22,"surah":28,"verses":[14],"verseLabel":"القصص: 14","question":"ما سرّ زيادة ﴿وَاسْتَوَى﴾ في القصص، وحذفها من نظيرها في يوسف؟","answer":"خص موسى بذكر الاستواء لأنه بلغ منتهى الشباب وتكامل العقل عند الإيحاء، أما يوسف فقد أوحي إليه قبل الأربعين؛ وهذا هو التعليل الذي أثبته مبحث القصص بعد عرض الآيتين، مع فتح مبحث يوسف أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص722–732؛ وج22، ص402–411.","url":""}]},{"id":"s28-23","number":23,"surah":28,"verses":[14],"verseLabel":"القصص: 14","question":"ما سرّ الجمع بين ﴿حُكْمًا﴾ و﴿عِلْمًا﴾؟","answer":"الحكم رشد في الفعل والقضاء، والعلم إدراك للحق؛ جمع آلة القرار ومادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص722–732.","url":""}]},{"id":"s28-24","number":24,"surah":28,"verses":[15],"verseLabel":"القصص: 15","question":"لماذا دخل المدينة ﴿عَلَى حِينِ غَفْلَةٍ مِنْ أَهْلِهَا﴾؟","answer":"هيأ خلو المكان لوقوع الحادثة من غير قصد مواجهة عامة، فظهر أنها وكزة عارضة لا خطة قتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص733–752.","url":""}]},{"id":"s28-25","number":25,"surah":28,"verses":[15],"verseLabel":"القصص: 15","question":"ما سرّ وصف الرجلين بأن هذا من شيعته وهذا من عدوه؟","answer":"اختصر سبب التدخل دون أسماء، وجعل الانتماء السياسي ظاهرًا في مشهد الخصومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص733–752.","url":""}]},{"id":"s28-26","number":26,"surah":28,"verses":[15],"verseLabel":"القصص: 15","question":"ما سرّ التعبير بـ﴿فَوَكَزَهُ مُوسَى فَقَضَى عَلَيْهِ﴾؟","answer":"الوكز دفع بجمع الكف لا آلة قتل؛ ثم جاءت النتيجة بفاء تكشف سرعة ما لم يقصده.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص733–752.","url":""}]},{"id":"s28-27","number":27,"surah":28,"verses":[15],"verseLabel":"القصص: 15","question":"ما سرّ قول موسى ﴿هَذَا مِنْ عَمَلِ الشَّيْطَانِ﴾؟","answer":"نسب اندفاع الغضب وما جر إليه من قتل غير مقصود إلى إغواء العدو، لا إلى مشروعية العصبية.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص733–752.","url":""}]},{"id":"s28-28","number":28,"surah":28,"verses":[16],"verseLabel":"القصص: 16","question":"ما سرّ مبادرة موسى إلى قوله ﴿رَبِّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي﴾؟","answer":"لم يبرر النتيجة بحسن النية، بل اعترف بأثر فعله ولجأ إلى المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص753–760.","url":""}]},{"id":"s28-29","number":29,"surah":28,"verses":[17],"verseLabel":"القصص: 17","question":"ما سرّ تعهد موسى بقوله ﴿فَلَنْ أَكُونَ ظَهِيرًا لِلْمُجْرِمِينَ﴾؟","answer":"حوّل التوبة إلى التزام سلوكي بألا تكون قوته عونًا لمن يجره إلى الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص761–766.","url":""}]},{"id":"s28-30","number":30,"surah":28,"verses":[18],"verseLabel":"القصص: 18","question":"ما سرّ الجمع بين ﴿خَائِفًا﴾ و﴿يَتَرَقَّبُ﴾؟","answer":"جمع حالة القلب وفعل الحذر؛ الخوف لم يشله بل جعله يراقب العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص767–776.","url":""}]},{"id":"s28-31","number":31,"surah":28,"verses":[18],"verseLabel":"القصص: 18","question":"ما سرّ وصف موسى الإسرائيلي بقوله ﴿إِنَّكَ لَغَوِيٌّ مُبِينٌ﴾؟","answer":"كشف أن تكرر استغاثته وخصامه يوقع غيره في العواقب؛ فنقد انحراف حليفه قبل نصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص767–776.","url":""}]},{"id":"s28-32","number":32,"surah":28,"verses":[19],"verseLabel":"القصص: 19","question":"من القائل ﴿يَا مُوسَى أَتُرِيدُ أَنْ تَقْتُلَنِي﴾، وما وجه قوله؟","answer":"الراجح في المبحث أن القائل هو الإسرائيلي؛ ظن أن موسى يريد البطش به لما رآه غاضبًا، وهو الذي عرف قتل الأمس. وقيل: القائل هو القبطي؛ لذلك أثبت الخلاف ولم يحصر الجواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص777–789.","url":""}]},{"id":"s28-33","number":33,"surah":28,"verses":[20],"verseLabel":"القصص: 20","question":"ما سرّ التعبير بـ﴿مِنْ أَقْصَى الْمَدِينَةِ يَسْعَى﴾؟","answer":"قدم بُعد المكان وسرعة الحركة ليظهر إخلاص التحذير وخطر القرار الذي سبقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص790–800.","url":""}]},{"id":"s28-34","number":34,"surah":28,"verses":[20],"verseLabel":"القصص: 20","question":"ما سرّ اختيار ﴿يَأْتَمِرُونَ بِكَ﴾ في خبر الملأ؟","answer":"الائتمار تشاور ينتهي إلى قرار؛ لم تكن شائعة بل مؤامرة رسمية بالقتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص790–800.","url":""}]},{"id":"s28-35","number":35,"surah":28,"verses":[21],"verseLabel":"القصص: 21","question":"ما سرّ تكرار ﴿خَائِفًا يَتَرَقَّبُ﴾ عند خروج موسى؟","answer":"تكرار العبارة يصل الخطر الداخلي بلحظة الهجرة، ويبين أن النجاة كانت تحت ضغط مستمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص10–16.","url":""}]},{"id":"s28-36","number":36,"surah":28,"verses":[22],"verseLabel":"القصص: 22","question":"ما سرّ التعبير بـ﴿عَسَى رَبِّي أَنْ يَهْدِيَنِي سَوَاءَ السَّبِيلِ﴾؟","answer":"خرج بلا دليل طريق، فطلب الطريق المستوي حسيًا، وفيه إيحاء بطريق الرسالة الآتي.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص17–22.","url":""}]},{"id":"s28-37","number":37,"surah":28,"verses":[23],"verseLabel":"القصص: 23","question":"ما سرّ التعبير بـ﴿وَجَدَ مِنْ دُونِهِمُ امْرَأَتَيْنِ تَذُودَانِ﴾؟","answer":"«من دونهم» تفصل المرأتين عن زحام الرجال، و«تذودان» تدفعان غنمهما انتظارًا بلا مزاحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص23–37.","url":""}]},{"id":"s28-38","number":38,"surah":28,"verses":[23],"verseLabel":"القصص: 23","question":"ما سرّ سؤال موسى ﴿مَا خَطْبُكُمَا﴾؟","answer":"الخطب شأن غير معتاد؛ لفت نظره اجتماع حاجتهما وبعدهما عن المورد.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص23–37.","url":""}]},{"id":"s28-39","number":39,"surah":28,"verses":[23],"verseLabel":"القصص: 23","question":"ما سرّ قول المرأتين ﴿وَأَبُونَا شَيْخٌ كَبِيرٌ﴾؟","answer":"قدمتا عذر خروجهما واختلاطهما بمهمة السقي من غير إطالة أو استدرار للشفقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص23–37.","url":""}]},{"id":"s28-40","number":40,"surah":28,"verses":[24],"verseLabel":"القصص: 24","question":"ما سرّ التعبير بـ﴿فَسَقَى لَهُمَا ثُمَّ تَوَلَّى إِلَى الظِّلِّ﴾؟","answer":"بادر إلى الخدمة بلا مساومة، ثم انصرف ولم يتبعها بطلب أو تعلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص38–45.","url":""}]},{"id":"s28-41","number":41,"surah":28,"verses":[24],"verseLabel":"القصص: 24","question":"ما سرّ دعاء موسى ﴿رَبِّ إِنِّي لِمَا أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ﴾؟","answer":"عرض فقره لكل خير بلا تحديد، جامعًا الأدب والافتقار بعد عمل صالح لم يطلب عليه أجرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص38–45.","url":""}]},{"id":"s28-42","number":42,"surah":28,"verses":[25],"verseLabel":"القصص: 25","question":"ما سرّ التعبير بـ﴿تَمْشِي عَلَى اسْتِحْيَاءٍ﴾؟","answer":"جعل ﴿على استحياء﴾ حالًا يصور هيئة مشيها القائمة على الوقار والاحتشام، من غير أن يمنعها الحياء من أداء الرسالة بوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص46–58.","url":""}]},{"id":"s28-43","number":43,"surah":28,"verses":[25],"verseLabel":"القصص: 25","question":"ما سرّ قولها ﴿إِنَّ أَبِي يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ مَا سَقَيْتَ لَنَا﴾؟","answer":"نسبت الدعوة للأب وحددت الغرض، فقطعت كل ريبة في اللقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص46–58.","url":""}]},{"id":"s28-44","number":44,"surah":28,"verses":[25],"verseLabel":"القصص: 25","question":"ما سرّ مبادرة الشيخ إلى قوله ﴿لَا تَخَفْ نَجَوْتَ مِنَ الْقَوْمِ الظَّالِمِينَ﴾؟","answer":"أجابه عن أصل حاجته قبل الطعام والعمل؛ أمنه أولًا من سلطان فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص46–58.","url":""}]},{"id":"s28-45","number":45,"surah":28,"verses":[26],"verseLabel":"القصص: 26","question":"ما سرّ الجمع بين ﴿الْقَوِيُّ﴾ و﴿الْأَمِينُ﴾ في وصف موسى؟","answer":"القوة تنجز العمل، والأمانة تمنع إساءة استعمالها؛ وهما جماع الكفاية الخلقية والعملية.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص59–64.","url":""}]},{"id":"s28-46","number":46,"surah":28,"verses":[27],"verseLabel":"القصص: 27","question":"لماذا عرض الشيخ الزواج مع إجارة ثماني حجج؟","answer":"عرض عليه إنكاح إحدى ابنتيه في مقابل أن يأجره ثماني سنين، وجعل إتمام العشر تفضلًا من موسى لا إلزامًا؛ فحدد أصل العقد وخياره بوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص65–73.","url":""}]},{"id":"s28-47","number":47,"surah":28,"verses":[28],"verseLabel":"القصص: 28","question":"ما سرّ التعبير في قول موسى ﴿ذَلِكَ بَيْنِي وَبَيْنَكَ أَيَّمَا الْأَجَلَيْنِ قَضَيْتُ فَلَا عُدْوَانَ عَلَيَّ﴾؟","answer":"ثبت الخيار وحدوده ومنع الزيادة بعد الوفاء؛ وضوح العقود يحفظ المودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص74–80.","url":""}]},{"id":"s28-48","number":48,"surah":28,"verses":[29],"verseLabel":"القصص: 29","question":"ما سرّ تفصيل خبر إيناس النار في القصص بقوله ﴿آنَسَ مِنْ جَانِبِ الطُّورِ نَارًا﴾ وما تلاه؟","answer":"فصّل المبحث رجوع موسى بأهله بعد قضاء الأجل، وإبصاره النار من جانب الطور، وطلبه منها خبر الطريق أو جذوة للاصطلاء؛ فاجتمع في المشهد تحديد الجهة وحاجتا الاهتداء والدفء، من غير اعتماد تعليل زائد غير منصوص.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص81–96.","url":""}]},{"id":"s28-49","number":49,"surah":28,"verses":[29],"verseLabel":"القصص: 29","question":"ما سرّ التعبير في قول موسى ﴿لَعَلِّي آتِيكُمْ مِنْهَا بِخَبَرٍ أَوْ جَذْوَةٍ مِنَ النَّارِ﴾؟","answer":"قسّم مطلوبه إلى خبر يهدي إلى الطريق، أو جذوة من النار للاصطلاء؛ والجذوة قطعة من الجمر أو العود الغليظ الذي في رأسه نار، وقد عرض المبحث القراءات اللغوية فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص81–96.","url":""}]},{"id":"s28-50","number":50,"surah":28,"verses":[30],"verseLabel":"القصص: 30","question":"ما سرّ تفصيل موضع النداء في ﴿مِنْ شَاطِئِ الْوَادِ الْأَيْمَنِ فِي الْبُقْعَةِ الْمُبَارَكَةِ مِنَ الشَّجَرَةِ﴾؟","answer":"تدرج التحديد من شاطئ الوادي الأيمن إلى البقعة المباركة ثم الشجرة، فعيّن لموسى جهة سماع النداء وشرف الموضع، من غير أن يجعل الشجرة مصدر الكلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص97–108.","url":""}]},{"id":"s28-51","number":51,"surah":28,"verses":[31],"verseLabel":"القصص: 31","question":"ما سرّ تشبيه اهتزاز العصا بالجان في ﴿تَهْتَزُّ كَأَنَّهَا جَانٌّ﴾؟","answer":"ذكر المبحث أن العصا كانت في عظمها كالثعبان وفي خفة حركتها واهتزازها كالجان؛ فالتشبيه هنا للحركة السريعة التي فسرت فزع موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص109–120.","url":""}]},{"id":"s28-52","number":52,"surah":28,"verses":[31],"verseLabel":"القصص: 31","question":"ما سرّ التعبير بـ﴿أَقْبِلْ وَلَا تَخَفْ إِنَّكَ مِنَ الْآمِنِينَ﴾؟","answer":"جمع الأمر الإيجابي بالاقتراب والنهي عن الخوف والوعد الثابت بالأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص109–120.","url":""}]},{"id":"s28-53","number":53,"surah":28,"verses":[32],"verseLabel":"القصص: 32","question":"ما سرّ اختيار ﴿اسْلُكْ يَدَكَ فِي جَيْبِكَ﴾؟","answer":"«اسلك» تصور إدخالًا مقصودًا في مسلك الثوب، لتخرج اليد آية بلا سوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص121–135.","url":""}]},{"id":"s28-54","number":54,"surah":28,"verses":[32],"verseLabel":"القصص: 32","question":"ما أوجه معنى ﴿وَاضْمُمْ إِلَيْكَ جَنَاحَكَ مِنَ الرَّهْبِ﴾؟","answer":"عرض المبحث وجوهًا متقاربة: ضم اليد أو العضد إلى الجسد، واتخاذ هيئة السكون والثبات ليزول الرهب؛ لذلك لا يحصر التعبير في صورة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص121–135.","url":""}]},{"id":"s28-55","number":55,"surah":28,"verses":[33],"verseLabel":"القصص: 33","question":"ما سرّ التعبير في قول موسى ﴿فَأَخَافُ أَنْ يَقْتُلُونِ﴾ بعد تكليفه؟","answer":"ذكر سببًا واقعيًا لا رفضًا للرسالة، ليطلب ما يعين على البلاغ ويحفظه حتى يؤديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص136–141.","url":""}]},{"id":"s28-56","number":56,"surah":28,"verses":[34],"verseLabel":"القصص: 34","question":"ما سرّ التعبير في قول موسى ﴿وَأَخِي هَارُونُ هُوَ أَفْصَحُ مِنِّي لِسَانًا﴾؟","answer":"لم يمنعه الاصطفاء من الاعتراف بميزة أخيه وتوظيفها لخدمة الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص142–151.","url":""}]},{"id":"s28-57","number":57,"surah":28,"verses":[35],"verseLabel":"القصص: 35","question":"ما سرّ التعبير في قوله تعالى ﴿سَنَشُدُّ عَضُدَكَ بِأَخِيكَ﴾؟","answer":"العضد موضع القوة، فاستعار شده لهارون الذي يقوي موسى نفسيًا وبيانيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص152–161.","url":""}]},{"id":"s28-58","number":58,"surah":28,"verses":[38],"verseLabel":"القصص: 38","question":"ما سرّ التعبير في قول فرعون ﴿مَا عَلِمْتُ لَكُمْ مِنْ إِلَهٍ غَيْرِي﴾ بدل نفي الإله مباشرة؟","answer":"صاغ دعواه في صورة حد علمه المتعالي، ثم طلب بناء الصرح تمثيلًا لخداعه لا بحثًا صادقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص188–203.","url":""}]},{"id":"s28-59","number":59,"surah":28,"verses":[38],"verseLabel":"القصص: 38","question":"ما سرّ أمر فرعون هامان أن يوقد له على الطين؟","answer":"عبر عن صناعة الآجر من بدايتها ليضخم مشهد المشروع السلطاني الذي يتحدى به دعوة موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص188–203.","url":""}]},{"id":"s28-60","number":60,"surah":28,"verses":[39],"verseLabel":"القصص: 39","question":"ما سرّ التعبير بـ﴿وَظَنُّوا أَنَّهُمْ إِلَيْنَا لَا يُرْجَعُونَ﴾؟","answer":"جعل إنكار الرجوع أصل الاستكبار؛ من أسقط الحساب توهم أن القوة بلا نهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص204–212.","url":""}]},{"id":"s28-61","number":61,"surah":28,"verses":[40],"verseLabel":"القصص: 40","question":"ما سرّ التعبير بـ﴿فَأَخَذْنَاهُ وَجُنُودَهُ فَنَبَذْنَاهُمْ فِي الْيَمِّ﴾؟","answer":"«أخذنا» قبضة قدرة، و«نبذنا» طرح باحتقار؛ فانقلب صاحب الصرح إلى شيء مطروح.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص213–221.","url":""}]},{"id":"s28-62","number":62,"surah":28,"verses":[41],"verseLabel":"القصص: 41","question":"ما سرّ تسميتهم ﴿أَئِمَّةً يَدْعُونَ إِلَى النَّارِ﴾؟","answer":"كما يوجد قادة إلى الهدى يوجد رؤوس يسنون طريق الضلال؛ فإمامتهم تقود إلى عاقبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص222–227.","url":""}]},{"id":"s28-63","number":63,"surah":28,"verses":[42],"verseLabel":"القصص: 42","question":"ما سرّ الجمع بين اللعنة في الدنيا وكونهم من المقبوحين يوم القيامة؟","answer":"أُتبع طردهم من الرحمة في الدنيا بإبعادهم يوم القيامة وكونهم من المقبوحين؛ فجمع النص خزي الدارين، لا مجرد وصف حسي للمنظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص228–232.","url":""}]},{"id":"s28-64","number":64,"surah":28,"verses":[44,45,46],"verseLabel":"القصص: 44-46","question":"ما سرّ تكرار ﴿وَمَا كُنْتَ﴾ في نفي حضور النبي أحداث موسى؟","answer":"عدد المواطن التي غاب عنها ليقيم من مجموعها حجة أن هذا التفصيل وحي لا مشاهدة ولا تعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص244–252.","url":""}]},{"id":"s28-65","number":65,"surah":28,"verses":[46],"verseLabel":"القصص: 46","question":"ما سرّ التعبير بـ﴿وَلَكِنْ رَحْمَةً مِنْ رَبِّكَ﴾؟","answer":"بعد نفي مصادر المعرفة البشرية أثبت مصدر الرسالة وغايتها: رحمة الإنذار لقوم لم يأتهم نذير قريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص264–274.","url":""}]},{"id":"s28-66","number":66,"surah":28,"verses":[47],"verseLabel":"القصص: 47","question":"ما سرّ التعبير بـ﴿وَلَوْلَا أَنْ تُصِيبَهُمْ مُصِيبَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ﴾؟","answer":"بيّن أن إرسال الرسول يقطع اعتذارهم لو نزل العقاب قبل البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص275–284.","url":""}]},{"id":"s28-67","number":67,"surah":28,"verses":[48],"verseLabel":"القصص: 48","question":"ما أوجه قراءة ﴿سِحْرَانِ تَظَاهَرَا﴾ ومعناها في السياق؟","answer":"على قراءة ﴿سِحْرَانِ﴾ يكون المراد كتابين، وأشهر ما ذكر التوراة والقرآن، أي يعين أحدهما الآخر في الحجة؛ وعلى قراءة ﴿سَاحِرَانِ﴾ يكون المراد شخصين كَموسى ومحمد أو موسى وهارون على اختلاف التفسير. فإثبات القراءتين يمنع حصر الجواب في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص285–296.","url":""}]},{"id":"s28-68","number":68,"surah":28,"verses":[49],"verseLabel":"القصص: 49","question":"لماذا تحداهم ﴿فَأْتُوا بِكِتَابٍ مِنْ عِنْدِ اللَّهِ هُوَ أَهْدَى مِنْهُمَا﴾؟","answer":"لم يطالبهم بمجرد النقد، بل ببديل إلهي أشد هداية؛ فظهر فراغ اعتراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص297–301.","url":""}]},{"id":"s28-69","number":69,"surah":28,"verses":[50],"verseLabel":"القصص: 50","question":"ما سرّ التعبير بـ﴿فَإِنْ لَمْ يَسْتَجِيبُوا لَكَ فَاعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَاءَهُمْ﴾؟","answer":"بعد فتح باب البرهان لم يبق لرفضهم تفسير معرفي؛ إنه اتباع الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص302–310.","url":""}]},{"id":"s28-70","number":70,"surah":28,"verses":[51],"verseLabel":"القصص: 51","question":"ما سرّ التعبير بـ﴿وَلَقَدْ وَصَّلْنَا لَهُمُ الْقَوْلَ﴾؟","answer":"جعل آيات الوحي وحججه متتابعة متصلة، فلا حجة لمن يزعم أن البيان انقطع أو غمض.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص311–320.","url":""}]},{"id":"s28-71","number":71,"surah":28,"verses":[52],"verseLabel":"القصص: 52","question":"ما سرّ التعبير بـ﴿الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ مِنْ قَبْلِهِ هُمْ بِهِ يُؤْمِنُونَ﴾؟","answer":"شهادة أهل الكتاب المنصفين تصل الوحي الجديد بأصل الوحي السابق وتبطل دعوى الغرابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص311–320.","url":""}]},{"id":"s28-72","number":72,"surah":28,"verses":[54],"verseLabel":"القصص: 54","question":"لماذا يؤتون أجرهم مرتين؟","answer":"ذكر المبحث أن لهم أجرين لإيمانهم بالكتاب الأول ثم بالقرآن، ولصبرهم على الأذى والثبات على الحق؛ فالثواب المضاعف مرتبط بتكرر الإيمان والصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص321–335.","url":""}]},{"id":"s28-73","number":73,"surah":28,"verses":[55],"verseLabel":"القصص: 55","question":"ما سرّ التعبير في قولهم للجاهلين ﴿لَنَا أَعْمَالُنَا وَلَكُمْ أَعْمَالُكُمْ سَلَامٌ عَلَيْكُمْ﴾؟","answer":"فصلوا المسؤوليات وخرجوا بسلام من جدل لا يطلب الحق، دون مقابلة اللغو بمثله.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص336–343.","url":""}]},{"id":"s28-74","number":74,"surah":28,"verses":[56],"verseLabel":"القصص: 56","question":"ما سرّ التعبير في خطاب النبي بـ﴿إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ﴾؟","answer":"نفى عنه خلق الهداية في القلب ولو اجتمع الحب والحرص؛ وظيفته الدلالة، والتوفيق لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص344–351.","url":""}]},{"id":"s28-75","number":75,"surah":28,"verses":[57],"verseLabel":"القصص: 57","question":"ما سرّ التعبير في قولهم ﴿إِنْ نَتَّبِعِ الْهُدَى مَعَكَ نُتَخَطَّفْ مِنْ أَرْضِنَا﴾؟","answer":"سموا القرآن هدى واعترفوا به، لكنهم قدموا وهم الأمن السياسي على مقتضى المعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص352–365.","url":""}]},{"id":"s28-76","number":76,"surah":28,"verses":[57],"verseLabel":"القصص: 57","question":"لماذا رد عليهم بذكر الحرم الآمن الذي تجبى إليه الثمرات؟","answer":"أثبت أن أمنهم ورزقهم حاصلان بتدبير الله قبل إيمانهم؛ أفلا يحفظهما بعد طاعته؟","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص352–365.","url":""}]},{"id":"s28-77","number":77,"surah":28,"verses":[58],"verseLabel":"القصص: 58","question":"ما سرّ التعبير بـ﴿بَطِرَتْ مَعِيشَتَهَا﴾؟","answer":"جعل المعيشة نفسها مجال البطر؛ لم يشكروا النعمة بل حملتهم سعتها على الطغيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص366–376.","url":""}]},{"id":"s28-78","number":78,"surah":28,"verses":[59],"verseLabel":"القصص: 59","question":"لماذا لا يهلك الله القرى حتى يبعث في أمها رسولًا؟","answer":"جعل بعث الرسول في أم القرى أبلغ في انتشار الحجة إلى ما حولها، وربط الإهلاك بعد البيان بظلم أهل القرى؛ فلا مؤاخذة قبل قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص377–388.","url":""}]},{"id":"s28-79","number":79,"surah":28,"verses":[60],"verseLabel":"القصص: 60","question":"ما سرّ الجمع بين ﴿خَيْرٌ﴾ و﴿أَبْقَى﴾ في قوله ﴿وَمَا عِنْدَ اللَّهِ خَيْرٌ وَأَبْقَى﴾؟","answer":"جمع جودة الجزاء ودوامه في مقابل متاع حسن لكنه زائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص389–406.","url":""}]},{"id":"s28-80","number":80,"surah":28,"verses":[61],"verseLabel":"القصص: 61","question":"لماذا قابل ﴿وَعْدًا حَسَنًا﴾ بـ﴿مَتَاعَ الْحَيَاةِ الدُّنْيَا﴾؟","answer":"الوعد الحسن مستقبل مضمون دائم، والمتاع انتفاع قصير يعقبه الحضور للحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص407–422.","url":""}]},{"id":"s28-81","number":81,"surah":28,"verses":[62],"verseLabel":"القصص: 62","question":"ما سرّ الاستفهام التوبيخي في ﴿أَيْنَ شُرَكَائِيَ الَّذِينَ كُنْتُمْ تَزْعُمُونَ﴾؟","answer":"الإضافة تهكم بدعواهم، والسؤال يطلب حضور من لا وجود لشركته فينكشف الزعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص423–448.","url":""}]},{"id":"s28-82","number":82,"surah":28,"verses":[63],"verseLabel":"القصص: 63","question":"لماذا تبرأ الرؤساء من أتباعهم وقالوا ﴿أَغْوَيْنَاهُمْ كَمَا غَوَيْنَا﴾؟","answer":"اعترفوا بالمشاركة في الإغواء لكن نفوا الإكراه؛ اتبعهم القوم باختيارهم كما ضلوا هم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص423–448.","url":""}]},{"id":"s28-83","number":83,"surah":28,"verses":[64],"verseLabel":"القصص: 64","question":"ما سرّ أمرهم بـ﴿ادْعُوا شُرَكَاءَكُمْ﴾ ثم عدم استجابتهم لهم؟","answer":"تحول الدعاء الذي مارسوه في الدنيا إلى اختبار علني لعجز المعبودات عند الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص449–464.","url":""}]},{"id":"s28-84","number":84,"surah":28,"verses":[66],"verseLabel":"القصص: 66","question":"ما سرّ التعبير بـ﴿فَعَمِيَتْ عَلَيْهِمُ الْأَنْبَاءُ يَوْمَئِذٍ﴾؟","answer":"شبه الحجج والجوابات بطرق اختفت معالمها، فلا يجدون خبرًا ينجّيهم ولا سؤالًا يتبادلون به الحيلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص465–491.","url":""}]},{"id":"s28-85","number":85,"surah":28,"verses":[68],"verseLabel":"القصص: 68","question":"ما سرّ التعبير بـ﴿وَرَبُّكَ يَخْلُقُ مَا يَشَاءُ وَيَخْتَارُ مَا كَانَ لَهُمُ الْخِيَرَةُ﴾؟","answer":"كما ينفرد بالخلق ينفرد باختيار الرسل والأحكام؛ مقاييسهم لا تلزم الحكمة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص492–515.","url":""}]},{"id":"s28-86","number":86,"surah":28,"verses":[71,72],"verseLabel":"القصص: 71-72","question":"لماذا سألهم عن ليل سرمد ثم نهار سرمد؟","answer":"افترض دوام الليل ثم دوام النهار ليظهر افتقار الناس إلى تعاقبهما: فالليل للسكون والنهار للإبصار وابتغاء الفضل، ولا يملك الإتيان بضدهما إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص532–554.","url":""}]},{"id":"s28-87","number":87,"surah":28,"verses":[73],"verseLabel":"القصص: 73","question":"ما سرّ توزيع الغايتين في ﴿لِتَسْكُنُوا فِيهِ وَلِتَبْتَغُوا مِنْ فَضْلِهِ﴾؟","answer":"وزع وظائف الزمن: سكون الليل وطلب الرزق في النهار، ثم جعل الغاية الأبعد الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص555–568.","url":""}]},{"id":"s28-88","number":88,"surah":28,"verses":[76],"verseLabel":"القصص: 76","question":"ما سرّ التعبير بـ﴿إِنَّ قَارُونَ كَانَ مِنْ قَوْمِ مُوسَى فَبَغَى عَلَيْهِمْ﴾؟","answer":"المفارقة أن من عرف ذل قومه استعمل ثروته في البغي عليهم، فالنسب لم يمنع الفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص592–626.","url":""}]},{"id":"s28-89","number":89,"surah":28,"verses":[76],"verseLabel":"القصص: 76","question":"ما سرّ تصوير المفاتح بأنها تنوء بالعصبة أولي القوة؟","answer":"بالغ في تصوير كثرة الخزائن حتى صارت مفاتيحها نفسها تثقل جماعة قوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص592–626.","url":""}]},{"id":"s28-90","number":90,"surah":28,"verses":[76],"verseLabel":"القصص: 76","question":"ما المراد بالنهي في ﴿لَا تَفْرَحْ إِنَّ اللَّهَ لَا يُحِبُّ الْفَرِحِينَ﴾؟","answer":"المنهي عنه فرح البطر والأشر الملازم للاغترار بالمال، لا مطلق السرور بالنعمة؛ ولذلك عُلّل بعدم محبة الله للفرحين بهذا المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص592–626.","url":""}]},{"id":"s28-91","number":91,"surah":28,"verses":[77],"verseLabel":"القصص: 77","question":"ما سرّ التعبير بـ﴿وَلَا تَنْسَ نَصِيبَكَ مِنَ الدُّنْيَا﴾ وسط طلب الآخرة؟","answer":"لم يلغ الدنيا، بل جعل نصيبها تابعًا للغاية الكبرى ومادة للإحسان لا للاستغراق.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص592–626.","url":""}]},{"id":"s28-92","number":92,"surah":28,"verses":[77],"verseLabel":"القصص: 77","question":"ما سرّ التعبير بـ﴿وَأَحْسِنْ كَمَا أَحْسَنَ اللَّهُ إِلَيْكَ﴾؟","answer":"جعل إحسان الله السابق معيارًا أخلاقيًا لاستعمال المال في الإحسان إلى الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص592–626.","url":""}]},{"id":"s28-93","number":93,"surah":28,"verses":[78],"verseLabel":"القصص: 78","question":"ما سرّ التعبير في قول قارون ﴿إِنَّمَا أُوتِيتُهُ عَلَى عِلْمٍ عِنْدِي﴾؟","answer":"حصر سبب الغنى في كفاءته، فمحا فضل الله وحقوق الناس من تفسير نجاحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص627–646.","url":""}]},{"id":"s28-94","number":94,"surah":28,"verses":[79],"verseLabel":"القصص: 79","question":"ما سرّ التعبير بـ﴿فَخَرَجَ عَلَى قَوْمِهِ فِي زِينَتِهِ﴾؟","answer":"جعل الزينة ظرفًا يحيط به؛ خرج في عرض مقصود يفتن العيون ويعلن التفوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص647–668.","url":""}]},{"id":"s28-95","number":95,"surah":28,"verses":[80],"verseLabel":"القصص: 80","question":"ما سرّ التعبير في قول أهل العلم ﴿وَيْلَكُمْ ثَوَابُ اللَّهِ خَيْرٌ﴾؟","answer":"قابلوا انبهار العين بميزان العاقبة، وربطوا نيل الخير بالإيمان والعمل والصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص647–668.","url":""}]},{"id":"s28-96","number":96,"surah":28,"verses":[81],"verseLabel":"القصص: 81","question":"ما سرّ التعبير بـ﴿فَخَسَفْنَا بِهِ وَبِدَارِهِ الْأَرْضَ﴾؟","answer":"ابتلعته الأرض مع رمز ثروته واستقراره؛ فما تفاخر به صار جزءًا من هلاكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص669–677.","url":""}]},{"id":"s28-97","number":97,"surah":28,"verses":[82],"verseLabel":"القصص: 82","question":"لماذا أصبح المتمنون مكانه يقولون ﴿وَيْكَأَنَّ اللَّهَ يَبْسُطُ الرِّزْقَ﴾؟","answer":"جاءت ﴿وَيْكَأَنَّ﴾ للتنبيه أو التعجب على اختلاف توجيهها؛ فانتقل الذين تمنوا مكان قارون إلى الاعتراف بأن الله يبسط الرزق ويقدر، وأن الكافر لا يفلح.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص678–699.","url":""}]},{"id":"s28-98","number":98,"surah":28,"verses":[83],"verseLabel":"القصص: 83","question":"ما سرّ الجمع بين إرادة العلو وإرادة الفساد في ﴿لَا يُرِيدُونَ عُلُوًّا فِي الْأَرْضِ وَلَا فَسَادًا﴾؟","answer":"جمع أصل داء فرعون وقارون: طلب السيادة وإفساد الحقوق؛ وضدهما شرط الدار الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص700–713.","url":""}]},{"id":"s28-99","number":99,"surah":28,"verses":[84],"verseLabel":"القصص: 84","question":"ما وجه اتفاق ﴿مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ خَيْرٌ مِنْهَا﴾ في القصص والنمل، وما خصوص ختام آية القصص؟","answer":"اتفقت الآيتان في تقرير أن الحسنة يزاد صاحبها خيرًا منها، ثم صرحت آية القصص في مقابلها بأن أصحاب السيئات لا يجزون إلا ما كانوا يعملون؛ فجمعت فضل الإحسان وعدل الجزاء. وقد فُتح الموضعان.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص714–726؛ وج40، ص527–551.","url":""}]},{"id":"s28-100","number":100,"surah":28,"verses":[85],"verseLabel":"القصص: 85","question":"ما سرّ التعبير بـ﴿إِنَّ الَّذِي فَرَضَ عَلَيْكَ الْقُرْآنَ لَرَادُّكَ إِلَى مَعَادٍ﴾؟","answer":"الآية وعد مؤكد بتثبيت النبي وردّه إلى معاد. وذكر المبحث في المعاد وجوهًا، منها الرجوع إلى مكة في الدنيا، والمرجع في الآخرة أو المقام المحمود؛ فلا يحصر اللفظ في واحد منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص727–744.","url":""}]},{"id":"s28-101","number":101,"surah":28,"verses":[85],"verseLabel":"القصص: 85","question":"ما سرّ التعبير بـ﴿رَبِّي أَعْلَمُ مَنْ جَاءَ بِالْهُدَى﴾؟","answer":"ردَّ العلم إلى الرب الذي يعلم حقيقة من جاء بالهدى ومن هو في ضلال مبين؛ وفي التعبير تسلية للنبي وقطع للمجادلة مع توكيد أن ما جاء به هداية وبينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص727–744.","url":""}]},{"id":"s28-102","number":102,"surah":28,"verses":[86],"verseLabel":"القصص: 86","question":"ما سرّ التعبير بـ﴿وَمَا كُنْتَ تَرْجُو أَنْ يُلْقَى إِلَيْكَ الْكِتَابُ﴾؟","answer":"نفى التطلع السابق للوحي ليؤكد أنه اصطفاء ورحمة، لا مشروعًا بشريًا خطط له.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص745–757.","url":""}]},{"id":"s28-103","number":103,"surah":28,"verses":[87],"verseLabel":"القصص: 87","question":"ما سرّ التعبير بـ﴿وَلَا يَصُدُّنَّكَ عَنْ آيَاتِ اللَّهِ بَعْدَ إِذْ أُنْزِلَتْ إِلَيْكَ﴾؟","answer":"شدد النهي لأن نعمة الوحي تستلزم الثبات أمام ضغط المكذبين، لا التراجع بعد البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص758–768.","url":""}]},{"id":"s28-104","number":104,"surah":28,"verses":[88],"verseLabel":"القصص: 88","question":"ما سرّ ختم السورة بـ﴿كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ﴾؟","answer":"بعد فرعون وقارون وملكهما قرر القاعدة الجامعة: يفنى كل متعلق ويبقى الله وحده والحكم له.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص769–780.","url":""}]},{"id":"s28-105","number":105,"surah":28,"verses":[88],"verseLabel":"القصص: 88","question":"ما سرّ الجمع بين ﴿لَهُ الْحُكْمُ﴾ و﴿إِلَيْهِ تُرْجَعُونَ﴾؟","answer":"له القرار في الدنيا والآخرة، والرجوع إليه يجعل هذه الحقيقة موعدًا شخصيًا لا مبدأ مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص769–780.","url":""}]},{"id":"s28-106","number":106,"surah":28,"verses":[20],"verseLabel":"القصص: 20؛ يس: 20","question":"ما سرّ تقديم ﴿رَجُلٌ﴾ في القصص: ﴿وَجَاءَ رَجُلٌ مِنْ أَقْصَى الْمَدِينَةِ يَسْعَى﴾، وتقديم ﴿مِنْ أَقْصَى الْمَدِينَةِ﴾ في يس؟","answer":"في يس قُدّم منشأ المجيء لإبراز بُعد المكان ونفي مظنة التواطؤ مع الرسل؛ أما في القصص فقُدّم الرجل لأن العناية بشخص الناصح وشجاعته في إنذار موسى، وجاء ترتيب القصص على الأصل بتقديم الفاعل. وقد فُتح الموضعان مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص142–151؛ وج47، ص556–572.","url":""}]},{"id":"s29-1","number":1,"surah":29,"verses":[1],"verseLabel":"العنكبوت: 1","question":"ما وجه استهلال سورة العنكبوت بالحروف المقطعة ﴿الم﴾؟","answer":"جاء الاستهلال بالحروف المقطعة من خصائص السورة المكية، وعرض المبحث وجه التحدي بالقرآن المؤلف من الحروف التي يعرفها العرب؛ أما تعيين معنى الحروف نفسها فلا يجزم فيه بوجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص781–809.","url":""}]},{"id":"s29-2","number":2,"surah":29,"verses":[2],"verseLabel":"العنكبوت: 2","question":"ما سرّ الاستفهام في ﴿أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا﴾؟","answer":"فضح وهم أن دعوى الإيمان تكفي بلا اختبار يكشف صدقها من كذبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص793–809.","url":""}]},{"id":"s29-3","number":3,"surah":29,"verses":[2],"verseLabel":"العنكبوت: 2","question":"ما سرّ اختيار ﴿وَهُمْ لَا يُفْتَنُونَ﴾؟","answer":"فسر المبحث الفتنة هنا بالاختبار الذي يميز الخبيث من الطيب؛ فصيغة المبني للمجهول توجه النظر إلى حتمية الامتحان لا إلى فاعل بشري بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص793–809.","url":""}]},{"id":"s29-4","number":4,"surah":29,"verses":[3],"verseLabel":"العنكبوت: 3","question":"ما أوجه معنى ﴿فَلَيَعْلَمَنَّ اللَّهُ الَّذِينَ صَدَقُوا﴾ مع سبق علم الله؟","answer":"ليس المراد حدوث علم بعد جهل؛ بل عرض المبحث وجوهًا، منها ظهور ما سبق في العلم ليترتب عليه الجزاء، أو تعلق العلم الأزلي بالمعلوم عند وقوعه. لذلك أبقيت المسألة متعددة التوجيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص793–809.","url":""}]},{"id":"s29-5","number":5,"surah":29,"verses":[4],"verseLabel":"العنكبوت: 4","question":"ما سرّ الاستفهام في ﴿أَمْ حَسِبَ الَّذِينَ يَعْمَلُونَ السَّيِّئَاتِ أَنْ يَسْبِقُونَا﴾؟","answer":"صور فرارهم من الحكم سباقًا مستحيلًا؛ لا تخرجهم سرعة ولا حيلة من القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص10–17.","url":""}]},{"id":"s29-6","number":6,"surah":29,"verses":[5],"verseLabel":"العنكبوت: 5","question":"ما سرّ التعبير بـ﴿مَنْ كَانَ يَرْجُو لِقَاءَ اللَّهِ فَإِنَّ أَجَلَ اللَّهِ لَآتٍ﴾؟","answer":"ثبت الرجاء بموعد لا يتخلف، حتى يحتمل المؤمن زمن الابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص18–33.","url":""}]},{"id":"s29-7","number":7,"surah":29,"verses":[6],"verseLabel":"العنكبوت: 6","question":"ما سرّ التعبير بـ﴿وَمَنْ جَاهَدَ فَإِنَّمَا يُجَاهِدُ لِنَفْسِهِ﴾؟","answer":"رد ثمرة المجاهدة إلى صاحبها؛ فالله غني، والطاعة إنقاذ للنفس لا نفع للخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص18–33.","url":""}]},{"id":"s29-8","number":8,"surah":29,"verses":[7],"verseLabel":"العنكبوت: 7","question":"ما سرّ الجمع بين ﴿لَنُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ﴾ و﴿وَلَنَجْزِيَنَّهُمْ أَحْسَنَ الَّذِي كَانُوا يَعْمَلُونَ﴾؟","answer":"الأول إزالة للموانع، والثاني إيصال للفضل؛ فجمع النجاة والارتقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص34–46.","url":""}]},{"id":"s29-9","number":9,"surah":29,"verses":[8],"verseLabel":"العنكبوت: 8","question":"ما سرّ التعبير في الوالدين بـ﴿وَوَصَّيْنَا الْإِنْسَانَ بِوَالِدَيْهِ حُسْنًا﴾ ثم استثناء الشرك؟","answer":"جعل الإحسان إلى الوالدين وصية عامة، ثم حد الطاعة عند المجاهدة على الشرك؛ فثبت حقهما من غير أن يقدّم على حق الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص47–65.","url":""}]},{"id":"s29-10","number":10,"surah":29,"verses":[8],"verseLabel":"العنكبوت: 8","question":"ما سرّ التعبير عن الشريك بـ﴿مَا لَيْسَ لَكَ بِهِ عِلْمٌ﴾؟","answer":"نفي العلم كناية عن نفي الحقيقة؛ فلا دليل يمكن أن يقوم على شريك معدوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص47–65.","url":""}]},{"id":"s29-11","number":11,"surah":29,"verses":[10],"verseLabel":"العنكبوت: 10","question":"ما سرّ التعبير عن المنافق بـ﴿فَإِذَا أُوذِيَ فِي اللَّهِ جَعَلَ فِتْنَةَ النَّاسِ كَعَذَابِ اللَّهِ﴾؟","answer":"سوّى ألمًا مؤقتًا بعقاب الله الدائم، فاختل ميزانه واستسلم للضغط.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص72–88.","url":""}]},{"id":"s29-12","number":12,"surah":29,"verses":[10],"verseLabel":"العنكبوت: 10","question":"ما سرّ قولهم عند النصر ﴿إِنَّا كُنَّا مَعَكُمْ﴾؟","answer":"أظهر الظرف انتهازيتهم: ينسبون أنفسهم للمؤمنين عند الغنيمة بعد تركهم عند المحنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص72–88.","url":""}]},{"id":"s29-13","number":13,"surah":29,"verses":[12],"verseLabel":"العنكبوت: 12","question":"ما سرّ التعبير في قول الكافرين ﴿اتَّبِعُوا سَبِيلَنَا وَلْنَحْمِلْ خَطَايَاكُمْ﴾؟","answer":"قدّموا ضمانًا لا يملكونه ليجعلوا التقليد آمنًا، ثم كذبهم النص صراحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص94–114.","url":""}]},{"id":"s29-14","number":14,"surah":29,"verses":[13],"verseLabel":"العنكبوت: 13","question":"ما سرّ الجمع بين حمل أثقالهم وحمل أثقال مع أثقالهم؟","answer":"لا يسقط عنهم ذنبهم، ويزاد عليهم مثل إثم من أضلوه دون أن ينقص من التابع.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص94–114.","url":""}]},{"id":"s29-15","number":15,"surah":29,"verses":[14],"verseLabel":"العنكبوت: 14","question":"ما سرّ التعبير بـ﴿أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا﴾ بدل ذكر تسعمائة وخمسين؟","answer":"استحضار الألف ثم استثناء الخمسين يصور طول المدة ويحقق مقدارها بلا زيادة ولا نقص؛ وهو أبلغ في مقام تسلية النبي بصبر نوح من اختصار العدد في رقم واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص115–124.","url":""}]},{"id":"s29-16","number":16,"surah":29,"verses":[14],"verseLabel":"العنكبوت: 14","question":"ما أوجه المغايرة بين ﴿سَنَةٍ﴾ و﴿عَامًا﴾ في الآية؟","answer":"عرض المبحث المغايرة اللفظية، وذكر وجهًا بلاغيًا يجعل ﴿السنة﴾ لزمن الشدة في الدعوة و﴿العام﴾ لزمن الرخاء، مع اختلاف الأقوال في تعيين الخمسين؛ فلا تجعل الدلالة قاعدة مطردة بلا قيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص115–124.","url":""}]},{"id":"s29-17","number":17,"surah":29,"verses":[15],"verseLabel":"العنكبوت: 15","question":"ما أوجه عود الضمير المؤنث في ﴿وَجَعَلْنَاهَا آيَةً لِلْعَالَمِينَ﴾؟","answer":"ذكر المبحث احتمالات لعود الضمير، منها السفينة، أو حادثة النجاة، أو القصة وما تضمنته من إنجاء وعقوبة؛ والمقصود جعل ذلك علامة وعبرة للعالمين، فلا يحصر الضمير في مرجع واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص125–138.","url":""}]},{"id":"s29-18","number":18,"surah":29,"verses":[16],"verseLabel":"العنكبوت: 16","question":"ما سرّ التعبير في قول إبراهيم ﴿اعْبُدُوا اللَّهَ وَاتَّقُوهُ ذَلِكُمْ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ﴾؟","answer":"جمع أصل التوحيد وحارسه العملي، وعلق إدراك الخيرية بعلم ينتج اختيارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص139–149.","url":""}]},{"id":"s29-19","number":19,"surah":29,"verses":[17],"verseLabel":"العنكبوت: 17","question":"ما سرّ التعبير عن صنع الأوثان بـ﴿وَتَخْلُقُونَ إِفْكًا﴾؟","answer":"«تخلقون» هنا تختلقون؛ كما صنعوا أجسام الأصنام صنعوا حولها كذبة الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص150–170.","url":""}]}]);
